INSERT INTO classes (name, publication, hit_points, mana_points, skills, proficiencies) VALUES ('Arcanista', 'Tormenta20', '8+CON', '6 por nível', '["Misticismo","Vontade","Conhecimento","Diplomacia","Enganação","Guerra","Iniciativa","Intimidação","Intuição","Investigação","Nobreza","Ofício","Percepção"]'::jsonb, '[]'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Caminho do Arcanista', 1, 'A magia é um poder incrível, capaz de alterar a realidade. Esse poder tem fontes distintas e cada uma opera conforme suas próprias regras. Escolha uma das opções a seguir. Uma vez feita, essa escolha não pode ser mudada.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Bruxo', 1, 'Você lança magias através de um foco — uma varinha, cajado, chapéu... Para lançar uma magia, você precisa empunhar o foco com uma mão (e gesticular com a outra) ou fazer um teste de Misticismo (CD 20 + o custo em PM da magia; se falhar, a magia não funciona, mas você gasta os PM mesmo assim). O foco tem RD 10 e PV iguais à metade dos seus, independentemente de seu material ou forma. Se for danificado, é totalmente restaurado na próxima vez que você recuperar seus PM por descanso. Se for destruído (reduzido a 0 PV), você fica atordoado por uma rodada. Você pode recuperar um foco destruído ou perdido com uma semana de trabalho e T$ 100. Seu atributo-chave para magias é Inteligência.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Feiticeiro', 1, 'Você lança magias através de um poder inato que corre em seu sangue. Escolha uma linhagem como origem de seus poderes (veja a página 39). Você recebe a herança básica da linhagem escolhida. Você não depende de nenhum item ou estudo, mas sua capacidade de aprender magias é limitada — você aprende uma magia nova a cada nível ímpar (3º, 5º, 7º etc.), em vez de a cada nível. Seu atributo-chave para magias é Carisma.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Mago', 1, 'Você lança magias através de estudo e memorização de fórmulas arcanas. Você só pode lançar magias memorizadas; suas outras magias não podem ser lançadas, mesmo que você tenha pontos de mana para tal. Para memorizar magias, você precisa estudar seu grimório por uma hora. Quando faz isso, escolhe metade das magias que conhece (por exemplo, se conhece 7 magias, escolhe 3). Essas serão suas magias memorizadas. Você pode memorizar magias uma vez por dia. Caso não possa estudar (por não ter tempo, por ter perdido o grimório...), não poderá trocar suas magias memorizadas. Um grimório tem as mesmas estatísticas de um foco (veja acima) e pode ser recuperado da mesma forma. Você começa com uma magia adicional (para um total de 4) e, sempre que ganha acesso a um novo círculo de magias, aprende uma magia adicional daquele círculo. Seu atributo-chave para magias é Inteligência.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Magias', 1, 'Você pode lançar magias arcanas de 1º círculo. A cada quatro níveis, pode lançar magias de um círculo maior (2º círculo no 5º nível, 3º círculo no 9º nível e assim por diante). Você começa com três magias de 1º círculo. A cada nível, aprende uma magia de qualquer círculo que possa lançar. Seu atributo-chave para lançar magias é definido pelo seu Caminho (veja acima) e você soma o bônus do atributo-chave no seu total de PM. Veja o Capítulo 4 para as regras de magia.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Familiares Arcanos', 1, 'Um familiar é uma criatura mágica. Em termos de jogo, é um parceiro especial com o qual você pode se comunicar telepaticamente em alcance longo. Ele obedece a suas ordens, mas ainda está limitado ao que uma criatura de sua espécie pode fazer. Se ele morrer, você fica atordoado por uma rodada. Você pode invocar um novo familiar com um ritual que exige um dia e T$ 100 em ingredientes.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Arcano de Batalha', 1, 'Quando lança uma magia, você soma seu atributo-chave na rolagem de dano.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Agrilhoar os Caídos', 1, 'Quando uma de suas magias de necromancia reduz os PV de um inimigo vivo a 0 ou menos, você pode aprisionar uma parte de seu espírito, que então fica flutuando ao seu redor. Para cada espírito, você recebe +2 na Defesa e em testes de resistência. Quando lança uma magia de dano, você pode libertar um espírito para causar +2d6 pontos de dano de trevas. Você pode acumular um máximo de espíritos simultâneos igual ao seu atributo-chave e eles permanecem ao seu redor até serem libertados ou até o fim do dia.', true, '{"other":"3º nível de arcanista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Alquimia Arcana', 1, 'A CD para resistir aos preparados alquímicos e poções que você usa aumenta em +1 para cada círculo de magia a que você tiver acesso.', true, '{"other":"treinado em Ofício (alquimista)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Apoteose Celestial', 1, 'Sua conexão com o divino se torna ainda mais profunda, às custas de uma fração de sua mortalidade. Você recebe +1 em Sabedoria e aprende uma magia divina de cada círculo a que tenha acesso. Entretanto, sua Constituição diminui em –1.', true, '{"other":"Herança Superior (linhagem celestial), 17° nível de arcanista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Apoteose Dracônica', 1, 'A influência de sua magia dracônica se torna cada vez mais evidente, tornando-o mais e mais próximo dos dragões. As magias do seu elemento escolhido causam +1 ponto de dano por dado e, contra criaturas imunes a esse elemento, ainda causam metade do dano. Contudo, você não pode mais lançar magias do tipo oposto ao seu elemento escolhido (fogo para frio e ácido para eletricidade).', true, '{"other":"Herança Superior (linhagem dracônica), 17° nível de arcanista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Apoteose Feérica', 1, 'Sua natureza feérica se acentua, mas isso o afasta do mundo dos mortais. Sempre que um ou mais inimigos falharem em um teste de Vontade contra uma de suas magias, você recebe 1 PM temporário cumulativo que dura até o fim da cena. Se a magia é de encantamento ou ilusão, em vez disso você recebe 2 PM temporários. Em ambos os casos, o ganho é limitado pelo total de PM gasto na magia. Contudo, você não pode mais lançar magias de convocação e necromancia.', true, '{"other":"Herança Superior (linhagem feérica), 17° nível de arcanista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Apoteose Rubra', 1, 'Você acolheu a corrupção rubra em seu ser — uma escolha que pode ser percebida por todos ao redor. Escolha uma magia que cause dano de cada círculo a que tem acesso. O tipo de dano dessas magias muda para psíquico. Além disso, quando lança uma magia de dano psíquico, você soma seu total de poderes da Tormenta na rolagem de dano. Este poder conta como um poder da Tormenta (exceto para perda de Carisma).', true, '{"other":"Herança Superior (linhagem rubra), 17° nível de arcanista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Arcanista de Linha de Frente', 1, 'Quando você lança uma magia, criaturas adjacentes sofrem –2 em seus testes de resistência contra ela e, se ela causar dano, causa um dado extra do mesmo tipo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Asas de Sapo', 1, 'Você pode empunhar dois catalisadores diferentes em uma mão ao mesmo tempo e, quando lança uma magia, pode gastar ambos para aplicar seus efeitos.', true, '{"other":"treinado em Ofício (alquimista)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Aumento de Atributo', 1, 'Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Caldeirão do Bruxo', 1, 'Você pode criar poções, como se tivesse o poder geral Preparar Poção. Se tiver ambos, pode criar poções de até 5º círculo.', true, '{"other":"Bruxo, treinado em Ofício (alquimista)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Conhecimento Mágico', 1, 'Você aprende duas magias de qualquer círculo que possa lançar. Você pode escolher este poder quantas vezes quiser.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Contingência Arcana', 1, 'Quando lança Runa de Proteção com o aprimoramento que muda o alvo para “você”, você pode substituir o componente material da magia por uma penalidade em PM igual ao círculo da magia inscrita na runa.', true, '{"other":"Runa de Proteção"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Contramágica Aprimorada', 1, 'Uma vez por rodada, você pode fazer uma contramágica como uma reação (veja a página 173).', true, '{"other":"Dissipar Magia"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Contramágica Superior', 1, 'Quando anula uma magia com uma contramágica, você recebe uma quantidade de PM temporários igual ao círculo da magia anulada (limitada pelos PM que gastou para anular).', true, '{"other":"Contramágica Aprimorada, 9º nível de arcanista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Envolto em Mistério', 1, 'Sua aparência e postura assombrosas o permitem manipular e assustar pessoas ignorantes ou supersticiosas. O mestre define o que exatamente você pode fazer e quem se encaixa nessa descrição. Como regra geral, você recebe +5 em Enganação e Intimidação contra pessoas não treinadas em Conhecimento ou Misticismo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Escriba Arcano', 1, 'Você pode aprender magias copiando os textos de pergaminhos e grimórios de outros magos. Aprender uma magia dessa forma exige um dia de trabalho e T$ 250 em matérias-primas por PM necessário para lançar a magia. Assim, aprender uma magia de 3º círculo (6 PM) exige 6 dias de trabalho e o gasto de T$ 1.500.', true, '{"other":"Mago, treinado em Ofício (escriba)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Especialista em Escola', 1, 'Escolha uma escola de magia. A CD para resistir a suas magias dessa escola aumenta em +2.', true, '{"other":"Bruxo ou Mago"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Especialista em Invocações', 1, 'Você soma seu atributo-chave na Defesa de suas criaturas conjuradas por habilidades mágicas (incluindo capangas) e a ação necessária para comandá-las diminui em um passo (de padrão para movimento e de movimento para livre). Contudo, cada comando só pode ser executado uma vez por rodada.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Familiar', 1, 'Você possui um animal de estimação mágico. Veja o quadro para detalhes.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Familiar Aprimorado', 1, 'Seu familiar pode falar e passa a fornecer um segundo benefício, escolhido entre os tipos comuns de familiares (Tormenta20, p. 38).', true, '{"other":"Familiar, 5º nível de arcanista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Fluxo de Mana', 1, 'Você pode manter dois efeitos sustentados ativos simultaneamente com apenas uma ação livre, pagando o custo de cada efeito separadamente.', true, '{"other":"10º nível de arcanista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Foco Vital', 1, 'Se você estiver segurando seu foco e sofrer dano que o levaria a 0 PV ou menos, você fica com 1 PV e o foco perde PV igual ao valor excedente ou até ser destruído (se o foco for destruído, você sofre o dano excedente). Pré-requisito: Bruxo. e', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Fortalecimento Arcano', 1, 'A CD para resistir a suas magias aumenta em +1. Se você puder lançar magias de 4º círculo, em vez disso ela aumenta em +2.', true, '{"other":"5º nível de arcanista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Herança Aprimorada', 1, 'Você recebe a herança aprimorada de sua linhagem sobrenatural.', true, '{"other":"Feiticeiro, 6º nível de arcanista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Herança Superior', 1, 'Você recebe a herança superior de sua linhagem sobrenatural.', true, '{"other":"Herança Aprimorada, 11º nível de arcanista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Ingrediente Especial', 1, 'Quando usa uma poção, você pode usar um catalisador e aplicar seus efeitos a ela.', true, '{"other":"Caldeirão do Bruxo, 5º nível de arcanista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Magia Performática', 1, 'Quando lança uma magia diante de uma ou mais criaturas inteligentes (Int –3 ou mais), você pode fazer um teste de Atuação (CD 20 + custo em PM da magia) para lançá-la de forma impressionante. Se você passar, a CD da magia aumenta em +1. Esse bônus aumenta em +1 para cada 10 pontos pelos quais o teste passar da CD. Se falhar, a magia não funciona.', true, '{"other":"Car 1, treinado em Atuação"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Magia Pungente', 1, 'Quando lança uma magia, você pode pagar 1 PM para aumentar em +2 a CD para resistir a ela.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Memória Súbita', 1, 'Escolha uma de suas magias que não esteja memorizada. Você pode gastar uma ação de movimento para memorizar essa magia até o fim da cena. Se fizer isso, uma de suas outras magias memorizadas, a sua escolha, deixa de estar memorizada.', true, '{"other":"Mago"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Mestre em Escola', 1, 'Escolha uma escola de magia. O custo para lançar magias dessa escola diminui em –1 PM.', true, '{"other":"Especialista em Escola com a escola escolhida, 8º nível de arcanista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'O Próprio Sangue', 1, 'Se você aprender novamente como feiticeiro uma magia que já possa lançar por uma habilidade qualquer (como uma habilidade de raça ou um poder concedido), a CD para resistir a ela aumenta em +2.', true, '{"other":"Feiticeiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Poder Mágico', 1, 'Você recebe +1 ponto de mana por nível de arcanista. Quando sobe de nível, os PM que recebe por este poder aumentam de acordo. Por exemplo, se escolher este poder no 4º nível, recebe 4 PM. Quando subir para o 5º nível, recebe +1 PM e assim por diante.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Raio Arcano', 1, 'Você pode gastar uma ação padrão para causar 1d8 pontos de dano de essência num alvo em alcance curto. Esse dano aumenta em +1d8 para cada círculo de magia acima do 1º que você puder lançar. O alvo pode fazer um teste de Reflexos (CD atributo-chave) para reduzir o dano à metade. O raio arcano conta como uma magia para efeitos de habilidades e itens que beneficiem suas magias. e', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Raio Dividido', 1, 'Você pode usar Raio Arcano como uma ação completa, em vez de padrão. Se fizer isso, ele afeta um número de alvos igual ao seu atributo-chave.', true, '{"other":"Raio Arcano, 5º nível de arcanista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Raio Elemental', 1, 'Quando usa Raio Arcano, você pode pagar 1 PM para que ele cause dano de ácido, eletricidade, fogo, frio ou trevas, a sua escolha. Se o alvo falhar no teste de Reflexos, sofre uma condição, de acordo com o tipo de dano (veja a descrição das condições na página 394). Ácido: vulnerável por 1 rodada. Eletricidade: ofuscado por 1 rodada. Fogo: fica em chamas. Frio: lento por 1 rodada. Trevas: não pode curar PV por 1 rodada. Pré-requisito: Raio Arcano. e', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Raio Poderoso', 1, 'Os dados de dano do seu Raio Arcano aumentam para d12 e o alcance dele aumenta para médio. Pré-requisito: Raio Arcano. e', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Ritual do Lich (Necromante)', 1, 'Você aprendeu o Ritual do Lich e pode executar seus passos (veja o quadro acima).', true, '{"other":"Celebrar Ritual, Escrever Pergaminho, Preparar Poção, 17º nível de necromante"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Sifão de Mana', 1, 'Quando você lança uma magia e pelo menos um inimigo falha no teste de resistência contra ela, você recupera uma quantidade de pontos de mana igual ao círculo da magia (limitada pelo total de PM gastos nela).', true, '{"other":"17° nível de arcanista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Tinta do Mago', 1, 'Você pode criar pergaminhos, como se tivesse o poder Escrever Pergaminho. Se tiver ambos, seu custo para criar pergaminhos é reduzido à metade.', true, '{"other":"Mago, treinado em Ofício (escriba)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Trama Célere', 1, 'Uma vez por rodada, quando usa uma ação padrão para lançar uma magia, você pode gastar 2 PM para fazer uma conjuração dupla. Isso permite que você lance uma segunda magia de 1º círculo como ação livre, pagando seu custo em PM como normal.', true, '{"other":"9º nível de arcanista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Transliteração Impossível', 1, 'Quando usa um pergaminho de uma magia que conheça, você recebe +2 PM para gastar em aprimoramentos e a magia não pode ser anulada por contramágica.', true, '{"other":"Escriba Arcano"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Alta Arcana', 1, 'No 20º nível, seu domínio das artes arcanas é total. O custo em PM de suas magias arcanas é reduzido à metade (após aplicar aprimoramentos e quaisquer outros efeitos que reduzam custo).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Serpentes Dracônicas (Guia de NPCs)', 1, 'Quando lança uma magia que causa dano do tipo de sua linhagem dracônica, você pode gastar +1 PM para aumentar o dano dessa magia em +1d12.', true, '{"other":"medusa, feiticeiro (linhagem dracônica)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Caminho do Necromante (Necromante)', 1, 'Você lança magias por meio de uma conexão com a morte. Você pode aprender magias de necromancia divinas como se fossem arcanas, mas não pode aprender magias de encantamento e pelo menos metade das magias que aprender devem ser de necromancia. Além disso, para lançar suas magias você precisa primeiro acessar sua conexão com a morte. Para isso, você deve gastar uma quantidade de PV igual ao círculo máximo de magias que deseja usar (limitado pelo círculo máximo a que tem acesso). Uma vez ativada, a conexão se mantém até o fim da cena. Seu atributo-chave para magias é Inteligência.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Falar com Mortos (Necromante)', 1, 'Você pode se comunicar com mortos-vivos por meio de seus poderes arcanos. Você pode usar Misticismo com mortos-vivos para mudar atitude e persuasão (Tormenta20, p. 118).
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Animar Cadáver (Necromante)', 1, 'No 2º nível, você pode gastar uma ação completa e 3 PM para animar o cadáver de uma criatura Pequena, Média ou Grande em alcance curto. O cadáver se torna um parceiro iniciante de um tipo a sua escolha, adequado ao seu tamanho e anatomia, que não conta em seu limite de parceiros (mas você só pode ter um parceiro cadáver por vez). Quando sofre dano, você pode sacrificar o parceiro cadáver para reduzir esse dano à metade. Cadáveres sacrificados não podem ser reanimados.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Necrologia (Necromante)', 1, 'No 3º nível, você recebe +2 em Cura, Fortitude e na CD para resistir às suas magias de necromancia. A cada cinco níveis, esse bônus aumenta em +1.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Distorção Necrótica (Necromante)', 1, 'No 4º nível, escolha uma de suas magias conhecidas de 1º círculo que não seja de necromancia. A escola dessa magia muda para necromancia. Essa mudança não tem efeitos mecânicos (além da troca de escola), mas altera a aparência e natureza de seu efeito (por exemplo, uma Armadura Arcana de necromancia cria uma armadura de ossos ou de sombras, enquanto uma magia Concentração de Combate manifesta espíritos dos mortos que o aconselham durante a luta).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Necropotência (Necromante)', 1, 'No 5º nível, quando estabelece sua conexão com a morte, você pode gastar o dobro de PV. Se fizer isso, sempre que reduzir um ou mais inimigos vivos a 0 PV ou menos com uma magia de necromancia, você recebe 2 PM temporários. Você pode ganhar um máximo de PM temporários por cena igual ao seu nível. Esses pontos temporários desaparecem no fim da cena.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Domínio Sobre a Morte (Necromante)', 1, 'No 20° nível, você domina as fronteiras da vida e da morte. O custo em PM de suas magias de necromancia é reduzido à metade (após aplicar aprimoramentos e quaisquer outros efeitos que reduzam custo). Além disso, quando você mata uma criatura viva com uma magia de necromancia, pode gastar 2 PM para erguer seu cadáver como um morto-vivo sob seu controle. Isso funciona como a magia Servo Morto-Vivo, mas você escolhe o tipo de parceiro entre quaisquer aprimoramentos da magia e não precisa pagar seu componente material. Mortos-vivos erguidos dessa forma não contam em seu limite de parceiros durante a cena em que são criados (ao fim da cena, mortos-vivos excedentes, a sua escolha, voltar a ser apenas cadáveres).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'O Ritual do Lich (Necromante)', 1, 'O Ritual do Lich representa o auge do conhecimento mágico de um necromante. É o resultado de anos de estudos, pesquisas e experimentos, sendo conhecido por poucos. Os passos deste ritual são descritos a seguir.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Linhagens Sobrenaturais', 1, 'O poder de um feiticeiro vem de seu sangue — mais precisamente, do sangue de um antepassado sobrenatural, como um dragão ou uma fada. Além da capacidade de lançar magias, o feiticeiro herda desse antepassado uma fração de seu poder natural, que ele pode desenvolver ao longo de sua vida. Ao escolher o caminho do feiticeiro, escolha uma linhagem da lista a seguir. Você recebe a herança básica de sua linhagem e pode desenvolver as demais através de poderes de arcanista.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Linhagem Abençoada', 1, '• Básica. Escolha um deus maior. Uma vez feita, essa escolha não pode ser mudada. Você aprende uma magia divina de 1º círculo e pode aprender magias divinas de 1º círculo como magias de feiticeiro. No 2º nível, você recebe um poder concedido do deus escolhido, aprovado pelo mestre, sem precisar ser devoto dele (mas você ainda pode ser devoto desse ou de outro deus). • Aprimorada. Suas magias divinas de círculo igual ou menor que sua Sabedoria custam –1 PM e você pode aprender magias divinas de 2º e 3º círculos como magias de feiticeiro. • Superior. Você recebe +1 em Sabedoria e aprende uma magia divina de cada círculo a que tenha acesso, limitado por sua Sabedoria. A cada dia, após descansar, pode trocar essas magias por outras dos mesmos círculos. Por fim, pode aprender magias divinas de 4º e 5º círculos como magias de feiticeiro.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Linhagem Dracônica', 1, 'Um de seus antepassados foi um majestoso dragão. Escolha um tipo de dano entre ácido, eletricidade, fogo ou frio. • Básica. Você soma seu Carisma em seus pontos de vida iniciais e recebe redução de dano 5 ao tipo escolhido. • Aprimorada. Suas magias do tipo escolhido custam –1 PM e causam +1 ponto de dano por dado. • Superior. Você passa a somar o dobro do seu Carisma em seus pontos de vida iniciais e se torna imune a dano do tipo escolhido. Além disso, sempre que reduz um ou mais inimigos a 0 PV ou menos com uma magia do tipo escolhido, você recebe uma quantidade de PM temporários igual ao círculo da magia.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Linhagem Feérica', 1, 'Seu sangue foi tocado pelas fadas. • Básica. Você se torna treinado em Enganação e aprende uma magia de 1º círculo de encantamento ou ilusão, arcana ou divina, a sua escolha. • Aprimorada. A CD para resistir a suas magias de encantamento e ilusão aumenta em +2 e suas magias dessas escolas custam –1 PM. • Superior. Você recebe +2 em Carisma. Se uma criatura passar no teste de resistência contra uma magia de encantamento ou ilusão lançada por você, você fica alquebrado até o final da cena.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Arcanista', 'Linhagem Rubra', 1, 'Seu sangue foi corrompido pela Tormenta. • Básica. Você recebe um poder da Tormenta. Além disso, pode perder outro atributo em vez de Carisma por poderes da Tormenta. • Aprimorada. Escolha uma magia para cada poder da Tormenta que você possui. Essas magias custam –1 PM. Sempre que recebe um novo poder da Tormenta, você pode escolher uma nova magia. Esta herança conta como um poder da Tormenta (exceto para perda de Carisma). • Superior. Você recebe +4 PM para cada poder da Tormenta que tiver. Esta herança conta como um poder da Tormenta (exceto para perda de Carisma).', false, NULL);
INSERT INTO classes (name, publication, hit_points, mana_points, skills, proficiencies) VALUES ('Bardo', 'Tormenta20', '12+CON', '4 por nível', '["Atuação","Reflexos","Acrobacia","Cavalgar","Conhecimento","Diplomacia","Enganação","Furtividade","Iniciativa","Intuição","Investigação","Jogatina","Ladinagem","Luta","Misticismo","Nobreza","Percepção","Pontaria","Vontade"]'::jsonb, '["Armas marciais"]'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Inspiração', 1, 'Você pode gastar uma ação padrão e 2 PM para inspirar as pessoas com sua arte. Você e todos os seus aliados em alcance curto ganham +1 em testes de perícia até o fim da cena. A cada quatro níveis, pode gastar +2 PM para aumentar o bônus em +1.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Magias', 1, 'Escolha três escolas de magia. Uma vez feita, essa escolha não pode ser mudada. Você pode lançar magias arcanas de 1º círculo que pertençam a essas escolas. À medida que sobe de nível, pode lançar magias de círculos maiores (2º círculo no 6º nível, 3º círculo no 10º nível e 4º círculo no 14º nível). Você começa com duas magias de 1º círculo. A cada nível par (2º, 4º etc.), aprende uma magia de qualquer círculo e escola que possa lançar. Você pode lançar essas magias vestindo armaduras leves sem precisar de testes de Misticismo. Seu atributo-chave para lançar magias é Carisma e você soma seu Carisma no seu total de PM. Veja o Capítulo 4 para as regras de magia.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Acorde Místico', 1, 'Se estiver empunhando um instrumento musical, você pode gastar uma ação padrão para fazer um teste de Atuação oposto ao teste de Vontade de uma criatura em alcance curto. Se você vencer, a criatura sofre 1d6 pontos de dano de essência e fica vulnerável por 1 rodada. Esse dano aumenta em +1d6 para cada círculo de magia acima do 1º que você puder lançar. Quando faz um ataque como parte da execução de uma magia (como pelo aprimoramento de Toque Chocante), você pode usar este poder no lugar do ataque.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Acorde Poderoso', 1, 'Os dados de dano do seu Acorde Místico aumentam para d10, o alcance dele aumenta para médio e, se você vencer o teste oposto, a vítima fica desprevenida, em vez de vulnerável.', true, '{"other":"Acorde Místico"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Adereço Musical', 1, 'Você pode gastar 10 minutos para acoplar (ou desacoplar) um item esotérico a um instrumento musical. Isso permite empunhar o esotérico com a mesma mão que empunha o instrumento e usar seu efeito em Acorde Místico, como se esse poder fosse uma magia. Cada instrumento musical só pode ter um esotérico acoplado.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Apresentação Impactante', 1, 'Quando usa Inspiração, você impacta também os inimigos dentro do alcance. Na próxima vez que um inimigo fizer um teste de ataque ou de resistência nessa cena, ele rola dois dados e usa o pior resultado (apenas uma vez por cena).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Arte Mágica', 1, 'Enquanto você estiver sob efeito de sua Inspiração, a CD para resistir a suas habilidades de bardo aumenta em +2.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Aumentar Repertório', 1, 'Você aprende duas magias de qualquer círculo que possa lançar. Elas devem pertencer às escolas que você sabe usar, mas podem ser arcanas ou divinas. Você pode escolher este poder quantas vezes quiser.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Aumento de Atributo', 1, 'Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Balada do Atirador', 1, 'Você pode usar Esgrima Mágica, e qualquer poder de bardo que o tenha como pré-requisito, com armas de ataque à distância leves ou de uma mão. Quando faz isso, você pode substituir testes de Pontaria por Atuação.', true, '{"other":"Esgrima Mágica"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Celebridade Artoniana', 1, 'No início de cada cena, você pode gastar 3 PM para fazer um teste de Atuação oposto pelo teste de Vontade de uma criatura inteligente (Int –3 ou maior) que possa ver. Se você vencer, a criatura se revela sua fã. Você recebe +5 em todos os testes de perícia contra ela e ela sofre –5 em todos os testes dela contra você até o fim da aventura. Quem vai querer agredir seu ídolo?', true, '{"other":"Estrelato, 17º nível de bardo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Dança Acrobática', 1, 'Você pode substituir testes de Acrobacia por Atuação. Quando você faz isso para passar por um inimigo, ele só pode usar Acrobacia ou Iniciativa no teste oposto.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Dança das Lâminas', 1, 'Quando você lança uma magia com execução de uma ação padrão, pode gastar 1 PM para fazer um ataque corpo a corpo como uma ação livre.', true, '{"other":"Esgrima Mágica, 10º nível de bardo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Esgrima Mágica', 1, 'Sua arte mescla esgrima e magia, transformando dança em golpes. Se estiver sob efeito de Inspiração, você pode substituir testes de Luta por testes de Atuação, mas apenas para ataques com armas corpo a corpo leves ou de uma mão.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Espada Encantada', 1, 'Quando você causa dano com seu Golpe Elemental, o alvo sofre uma condição conforme o tipo de dano escolhido. Ácido: vulnerável por 1 rodada. Eletricidade: ofuscado por 1 rodada. Fogo: em chamas. Frio: lento por 1 rodada.', true, '{"other":"Golpe Elemental"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Estrelato', 1, 'Suas apresentações o tornaram famoso, fazendo com que você seja reconhecido e bem tratado por aqueles que apreciam a arte. Por outro lado, pode ser difícil passar despercebido, especialmente em grandes cidades. Quando usa Atuação para impressionar uma plateia, o bônus recebido em perícias baseadas em Carisma aumenta para +5.', true, '{"other":"6º nível de bardo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Fascinar em Massa', 1, 'Quando usa Música: Balada Fascinante, você pode gastar +2 PM. Se fizer isso, afeta todas as criaturas a sua escolha no alcance da música (você faz um único teste de Atuação, oposto pelo teste de Vontade de cada criatura).', true, '{"other":"Música: Balada Fascinante"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Golpe Elemental', 1, 'Enquanto estiver sob efeito de Inspiração, sempre que você acertar um ataque corpo a corpo, pode gastar 1 PM para causar 1d6 de dano extra de ácido, eletricidade, fogo ou frio, a sua escolha. Para cada quatro níveis que possuir, pode gastar +1 PM para aumentar o dano em +1d6.', true, '{"other":"Golpe Mágico"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Golpe Mágico', 1, 'Enquanto estiver sob efeito de Inspiração, sempre que você acertar um ataque corpo a corpo em um inimigo, recebe 2 PM temporários cumulativos. Você pode ganhar um máximo de PM temporários por cena igual ao seu nível. Esses pontos temporários desaparecem no final da cena.', true, '{"other":"Esgrima Mágica"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'História de Acampamento', 1, 'Você pode gastar 1 hora para entreter um número de pessoas igual ao seu nível com histórias e canções. A recuperação de PM por descanso dessas pessoas aumenta em +1 por nível nesse dia.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Inspiração Espirituosa', 1, 'Na primeira vez que você usa Inspiração em cada combate, você e seus aliados recebem uma quantidade de PM temporários igual ao bônus fornecido por essa habilidade.', true, '{"other":"11º nível de bardo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Inspiração Marcial', 1, 'Quando você usa Inspiração, você e seus aliados aplicam o bônus recebido em rolagens de dano (além de testes de perícia).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Inspiração Resoluta', 1, 'Quando você usa Inspiração, você e seus aliados aplicam o bônus recebido na Defesa (além de testes de perícia).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Inspiração Revigorante', 1, 'Quando você usa Inspiração, você e seus aliados recebem uma quantidade de PV temporários igual a 5 vezes o bônus fornecido.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Lendas e Histórias', 1, 'Você é um arquivo vivo de relatos, canções e folclore. Além de outros benefícios a critério do mestre, quando faz um teste de Conhecimento, Misticismo, Nobreza ou Religião para informação, identificar criaturas ou identificar itens mágicos, você pode gastar 1 PM para rolá-lo novamente.', true, '{"other":"Int 1"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Magia Performática', 1, 'Quando lança uma magia diante de uma ou mais criaturas inteligentes (Int –3 ou mais), você pode fazer um teste de Atuação (CD 20 + custo em PM da magia) para lançá-la de forma impressionante. Se você passar, a CD da magia aumenta em +1. Esse bônus aumenta em +1 para cada 10 pontos pelos quais o teste passar da CD. Se falhar, a magia não funciona.', true, '{"other":"Car 1, treinado em Atuação"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Mago Vermelho', 1, 'Se estiver empunhando uma arma leve ou ágil, você soma o círculo máximo de magias que pode lançar nos testes de ataque e nas rolagens de dano com ela. Além disso, a mão da arma é considerada livre para lançar magias.', true, '{"other":"treinado em Misticismo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Manipular', 1, 'Você pode gastar 1 PM para fazer uma criatura fascinada por você ficar enfeitiçada até o fim da cena (Von CD Car anula). Se a criatura passar, fica imune a este efeito por um dia. Usar esta habilidade não conta como ameaça à criatura fascinada.', true, '{"other":"Música: Balada Fascinante"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Manipular em Massa', 1, 'Quando usa Manipular, você pode gastar +2 PM. Se fizer isso, afeta todas as criaturas a sua escolha em alcance curto.', true, '{"other":"Fascinar em Massa, Manipular, 10º nível de bardo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Música: Balada Fascinante', 1, 'Faça um teste de Atuação oposto pelo teste de Vontade de uma criatura no alcance. Se você passar, ela fica fascinada enquanto você se concentrar (uma ação padrão por rodada). Um alvo hostil ou envolvido em combate recebe +5 no teste de resistência e tem direito a um novo teste sempre que você se concentrar. Se a criatura passar, fica imune a este efeito por um dia.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Música: Canção Assustadora', 1, 'Faça um teste de Atuação oposto pelo teste de Vontade de cada criatura a sua escolha dentro do alcance (você faz um único teste). Alvos que falhem ficam abalados até o fim da cena. Alvos que passem ficam imunes a este efeito por um dia.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Música: Marcha Vitoriosa', 1, 'Faça um teste de Atuação. Para cada 10 pontos no resultado desse teste, seus aliados dentro do alcance recebem +1 em rolagens de dano por 1 rodada.', true, '{"other":"Inspiração Marcial, 5º nível de bardo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Música: Melodia Curativa', 1, 'Criaturas a sua escolha no alcance recuperam 1d6 PV. Quando usa esta habilidade, você pode gastar mais pontos de mana. Para cada PM extra, aumente a cura em +1d6 PV.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Música: Réquiem Sombrio', 1, 'Um cadáver de uma criatura Média ou menor dentro do alcance se ergue como um morto-vivo sob seu comando. Ele é um parceiro iniciante de um tipo a sua escolha aprovado pelo mestre que não conta em seu limite de parceiros. Você pode animar um máximo de cadáveres simultâneos igual ao seu Carisma. Os cadáveres se decompõem no fim da cena.', true, '{"other":"necromancia como uma de suas escolas de magia"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Música: Sonata da Distração', 1, 'Faça um teste de Atuação oposto pela Vontade de cada criatura a sua escolha dentro do alcance (você faz um único teste). Alvos que falharem ficam desprevenidos por 1 rodada. Alvos que passarem ficam imunes a este efeito por 1 dia. Mental.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Melodia Restauradora', 1, 'Quando você usa Música: Melodia Curativa, pode gastar +2 PM. Se fizer isso, escolha uma das condições a seguir: abalado, alquebrado, apavorado, atordoado, cego, confuso, enfeitiçado, esmorecido, exausto, fatigado, frustrado, pasmo ou surdo. Você remove a condição escolhida das criaturas afetadas pela música.', true, '{"other":"Música: Melodia Curativa"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Mestre dos Sussurros', 1, 'Você é dissimulado, atento para rumores e ótimo em espalhar fofocas. Quando faz um teste de Investigação para interrogar ou um teste de Enganação para intriga, você rola dois dados e usa o melhor resultado. Além disso, pode fazer esses testes em ambientes sociais (taverna, festival, corte...) sem custo e em apenas um minuto.', true, '{"other":"Car 1, treinado em Enganação e Investigação"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Paródia', 1, 'Uma vez por rodada, quando vê outra criatura lançando uma magia em alcance médio, você pode pagar 1 PM e fazer um teste de Atuação (CD 15 + custo em PM da magia). Se passar, até o final de seu próximo turno você pode lançar essa magia.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Portas da Fama', 1, 'Você recebe +10 em testes de Diplomacia, Enganação e Furtividade para entrar em lugares proibidos — as pessoas simplesmente presumem que você tem acesso a tudo!', true, '{"other":"Estrelato"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Prestidigitação', 1, 'Quando faz uma ação padrão, você pode aproveitar seus gestos para lançar uma magia com execução de ação completa ou menor. Faça um teste de Atuação (CD 15 + custo em PM da magia). Se passar, você lança a magia como uma ação livre. Se falhar, a magia não funciona, mas você gasta os PM mesmo assim. Outros personagens só percebem que você lançou uma magia com um teste de Misticismo (CD 20).', true, '{"other":"6º nível de bardo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Ressoar', 1, 'Quando lança uma magia que tenha apenas você como alvo, você pode gastar 2 PM e fazer um teste de Atuação (CD 15 + custo em PM da magia). Se você passar, um aliado em alcance curto que esteja sob efeito de sua Inspiração é afetado pelo efeito básico da magia como se você a tivesse lançado nele.', true, '{"other":"17º nível de bardo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Triunfo do Amor', 1, 'Se você “conquistar” romanticamente um NPC, seus PM aumentam em +1 por nível até o fim da aventura. O mestre define exatamente o que você precisa fazer, de acordo com o NPC. Por padrão, isso envolve aumentar a atitude dele em relação a você para prestativo e então passar em um teste de Atuação, Diplomacia ou Enganação oposto pela Vontade do NPC +10. Você pode receber esse benefício até duas vezes por aventura (ou seja, pode conquistar até duas pessoas por aventura para ganhar +2 PM por nível).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Eclético', 1, 'A partir do 2º nível, quando vai fazer um teste de perícia, você pode gastar 1 PM para receber os benefícios de ser treinado nessa perícia para este teste.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Artista Completo', 1, 'No 20º nível, você pode usar Inspiração como uma ação livre. Enquanto estiver sob efeito de sua Inspiração, qualquer habilidade de bardo (incluindo magias) que você usar tem seu custo em PM reduzido pela metade (após aplicar quaisquer outras habilidades que reduzam o custo).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Cadência Magimarcial (Magimarcialista)', 1, 'Sempre que lança uma magia de bardo você recebe uma carga arcana e, sempre que faz a ação agredir, recebe uma carga marcial. Você pode acumular um máximo de cargas de cada tipo igual ao seu Carisma e elas duram até o fim da cena.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Magificação (Magimarcialista)', 1, 'Se tiver pelo menos 1 carga arcana e 1 carga marcial, você recebe +2 em testes de ataque e rolagens de dano e é considerado sob Inspiração (Tormenta20, p. 44) para efeitos baseados nisso. A cada cinco níveis, esses bônus aumentam em +1.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Bravado Magimarcial (Magimarcialista)', 1, 'No 2º nível, quando lança uma magia, você pode gastar 1 carga marcial para reduzir seu custo em –1 PM (cumulativo com outras reduções) e, quando faz um ataque, pode gastar 1 carga arcana para receber +1d6 na rolagem de dano.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Dança Defensiva (Magimarcialista)', 1, 'No 3º nível, quando faz um teste de resistência, você pode gastar 1 carga marcial para receber +5 nesse teste e, quando sofre dano, pode gastar 1 carga arcana para receber redução de dano 10 contra esse dano.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Arte Sublime (Magimarcialista)', 1, 'A partir do 7º nível, quando usa Bravado Magimarcial ou Dança Defensiva, você pode gastar uma carga adicional do tipo exigido para dobrar seu efeito.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Crescendo Vitorioso (Magimarcialista)', 1, 'No 20° nível, no início de cada combate, você recebe 1 carga arcana e 1 carga marcial. Além disso, você soma seu total de cargas marciais na CD para resistir às suas habilidades de bardo e o total de suas cargas arcanas em seus testes de ataque e rolagens de dano.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bardo', 'Músicas de Bardo', 1, 'Alguns poderes do bardo são Músicas. Esses poderes compartilham as seguintes regras.
INSERT INTO classes (name, publication, hit_points, mana_points, skills, proficiencies) VALUES ('Bucaneiro', 'Tormenta20', '16+CON', '3 por nível', '["Luta ou Pontaria","Reflexos","Acrobacia","Atletismo","Atuação","Enganação","Fortitude","Furtividade","Iniciativa","Intimidação","Jogatina","Luta","Ofício","Percepção","Pilotagem","Pontaria"]'::jsonb, '["Armas marciais"]'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Audácia', 1, 'Quando faz um teste de perícia, você pode gastar 2 PM para somar seu Carisma no teste. Você não pode usar esta habilidade em testes de ataque.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Insolência', 1, 'Você soma seu Carisma na Defesa, limitado pelo seu nível. Esta habilidade exige liberdade de movimentos; você não pode usá-la se estiver de armadura pesada ou na condição imóvel.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Evasão', 1, 'A partir do 2º nível, quando sofre um efeito que permite um teste de Reflexos para reduzir o dano à metade, você não sofre dano algum se passar. Você ainda sofre dano normal se falhar no teste de Reflexos. Esta habilidade exige liberdade de movimentos; você não pode usá-la se estiver de armadura pesada ou na condição imóvel.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Abusar dos Fracos', 1, 'Quando ataca uma criatura sob efeito de uma condição de medo, seu dano aumenta em um passo.', true, '{"other":"Flagelo dos Mares"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Amigos no Porto', 1, 'Quando chega em uma comunidade portuária, você pode fazer um teste de Carisma (CD 10). Se passar, encontra um amigo para o qual pode pedir um favor ou que pode ajudá-lo como parceiro veterano de um tipo a sua escolha por um dia.', true, '{"other":"Car 1, 6º nível de bucaneiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Aparar', 1, 'Uma vez por rodada, quando é atingido por um ataque, você pode gastar 1 PM para fazer um teste de ataque com bônus igual ao seu nível (além do normal). Se o resultado do seu teste for maior que o do oponente, você evita o ataque. Você só pode usar este poder se estiver usando uma arma corpo a corpo leve ou ágil.', true, '{"other":"Esgrimista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Apostador', 1, 'Você pode gastar um dia para encontrar e participar de uma mesa de wyrt ou outro jogo de azar. Escolha um valor e faça um teste de Jogatina contra a CD correspondente: T$ 100 (CD 15), T$ 200 (CD 20), T$ 400 (CD 25), T$ 800 (CD 30), T$ 1.600 (CD 35) e assim por diante. Se passar, você ganha o valor escolhido (ou um item ou favor equivalente, a critério do mestre). Se falhar, perde esse mesmo o valor. A critério do mestre, o lugar onde você está pode limitar ou impossibilitar o uso deste poder.', true, '{"other":"treinado em Jogatina"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Ardil Afiado', 1, 'Você pode usar Audácia em testes de manobra. Se fizer isso contra um oponente desprevenido, soma o dobro do Carisma no teste.', true, '{"other":"Car 1, treinado em Enganação"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Ataque Acrobático', 1, 'Quando se aproxima de um inimigo com um salto ou pirueta (em termos de jogo, usando Atletismo ou Acrobacia para se mover) e o ataca no mesmo turno, você recebe +2 nesse teste de ataque e na rolagem de dano.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Aumento de Atributo', 1, 'Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Aventureiro Ávido', 1, 'Uma vez por rodada, você pode gastar 5 PM para realizar uma ação padrão ou de movimento adicional. Se possuir o poder Surto Heroico, em vez disso seu custo diminui em –2 PM.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Bloqueio Desconcertante', 1, 'Quando uma criatura erra um ataque corpo a corpo contra você, ou quando você bloqueia um ataque com Aparar, você pode gastar 1 PM. Se você fizer isso, a criatura fica desprevenida contra seu próximo ataque feito até o fim do seu próximo turno.', true, '{"other":"Esgrimista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Bom de Trago', 1, 'Uma vez por rodada, você pode ingerir uma bebida, preparado ou poção que esteja empunhando como uma ação livre.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Bravatas', 1, 'Audazes e imprudentes, bucaneiros têm o costume da bravata — a promessa pública de realizar uma façanha, às vezes atrelada a uma restrição, como "Navegarei até Galrasia com um barco furado!". Todas as Bravatas compartilham as seguintes regras.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Bravata Audaz', 1, 'Você jura fazer uma façanha específica, como roubar o tesouro de Sckhar ou ganhar um beijo do príncipe e da princesa até o fim do baile. Se cumprir a bravata, seus PM aumentam em +2 por nível de bucaneiro até o fim da aventura.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Bravata Imprudente', 1, 'Na primeira rodada de um combate, você pode jurar derrotar seus inimigos com uma restrição a sua escolha, como lutar com uma mão nas costas, de guarda aberta (em termos de jogo, desprevenido), de olhos vendados (cego) etc. Uma restrição só é válida se prejudicá-lo (por exemplo, lutar com uma mão nas costas só vale como restrição se você luta com duas armas). O mestre tem a palavra final sobre a validade de uma restrição. Você sofre a penalidade durante todo o combate, mas, se vencer, recebe +2 nos testes de ataque e na margem de ameaça até o fim da aventura.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Charme Cafajeste', 1, 'Você aprende e pode lançar Enfeitiçar (atributo- -chave Carisma). A CD para resistir a esta habilidade aumenta em +2 para criaturas inamistosas e em +5 para criaturas hostis. Esta não é uma habilidade mágica e provém de sua habilidade de cativar seus adversários (veja “Magias Simuladas”, p. 44).', true, '{"other":"treinado em Enganação, 3º nível de bucaneiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Cobrir de Pólvora', 1, 'Você pode gastar uma ação de movimento, 1 PM e uma bala de arma de fogo para cobrir uma criatura em alcance curto com uma pequena quantidade de pólvora. O alvo fica cego por 1 rodada (Ref CD Car evita) e, até o fim da cena, o próximo ataque contra ele causa +1d6 pontos de dano de fogo e deixa-o em chamas.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Cortejo de Espadas', 1, 'Quando você faz um teste de Acrobacia para passar por um inimigo, o espaço ocupado por esse inimigo não conta como terreno difícil e ele só pode usar Iniciativa para o teste oposto. Se você vencer esse teste, recebe +2 na Defesa e em Reflexos contra esse inimigo por 1 rodada.', true, '{"other":"treinado em Acrobacia"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Dançar nas Cordas', 1, 'Se você usar Ataque Acrobático tendo vencido um teste oposto para passar pelo espaço de um inimigo, os bônus fornecidos por esse poder aumentam para +5 e se aplicam a todos os seus ataques contra esse inimigo nessa rodada.', true, '{"other":"Ataque Acrobático"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'En Garde', 1, 'Você pode gastar uma ação de movimento e 1 PM para assumir postura de luta. Até o fim da cena, se estiver usando uma arma corpo a corpo leve ou ágil, você recebe +2 na margem de ameaça com essas armas e +2 na Defesa.', true, '{"other":"Esgrimista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Entrada Triunfal', 1, 'Se um combate começar e você for o primeiro na iniciativa, recebe uma quantidade de PV temporários igual à metade de seus PV máximos.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Esgrima Sambur', 1, 'Se estiver empunhando duas armas corpo a corpo leves ou ágeis e fizer a ação agredir, você pode gastar 1 PM para fazer dois ataques, um com cada arma (se tiver Ambidestria ou Estilo de Duas Armas, em vez disso não sofre penalidade para usá-los). Além disso, se tiver o poder Aparar, pode usá-lo uma segunda vez na rodada.', true, '{"other":"Esgrimista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Esgrimista', 1, 'Quando usa uma arma corpo a corpo leve ou ágil, você soma sua Inteligência nas rolagens de dano (limitado pelo seu nível).', true, '{"other":"Int 1"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Estampido Ensurdecedor', 1, 'Quando faz um ataque à distância com uma arma de fogo, você pode pagar 1 PM para deixar todas as criaturas adjacentes a você abaladas e surdas (Fort CD Car reduz a duração das condições para 1 rodada).', true, '{"other":"Grudar o Cano"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Estocada no Flanco', 1, 'Uma vez por rodada, quando vence um teste oposto para passar por um inimigo, você pode gastar 2 PM para fazer um ataque contra ele. Se você acertar o ataque e causar dano de corte ou perfuração, o inimigo fica sangrando.', true, '{"other":"Cortejo de Espadas"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Flagelo dos Mares', 1, 'Você aprende e pode lançar Amedrontar (atributo-chave Carisma). Esta não é uma habilidade mágica e provém de sua capacidade de incutir medo em seus inimigos.', true, '{"other":"treinado em Intimidação"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Folião', 1, 'Você sabe fazer amizades durante festas, de noitadas em tavernas a bailes na corte. Nesses locais, você recebe +2 em testes de perícias de Carisma e a atitude de todas as pessoas em relação a você melhora em uma categoria.', true, '{"other":"Car 1"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Gole da Coragem', 1, 'Uma vez por cena, quando ingerir uma bebida, preparado ou poção, você recebe uma ação padrão adicional nesse turno.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Golpe Humilhante', 1, 'Você pode gastar 2 PM para humilhar uma criatura em alcance curto. Até o fim da cena, sempre que você acertar um ataque nessa criatura, ela sofre uma penalidade de –1 na Defesa. A penalidade é cumulativa, limitada pelo seu Carisma e dura até o fim da cena.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Grudar o Cano', 1, 'Quando faz um ataque à distância com uma arma de fogo contra um oponente adjacente, você não sofre a penalidade de –5 no teste de ataque e aumenta seu dano em um passo.', true, '{"other":"treinado em Luta, Pistoleiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Introdução Calorosa', 1, 'Na primeira rodada de um combate, você pode gastar uma ação a para se apresentar. Veja o quadro 1-17 da página 60 do suplemento Heróis de Arton para os tipos de ação que você pode gastar e seus respectivos benefícios. Você recebe todos os benefícios das ações anteriores e eles duram até o fim da cena.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Lobo do Mar', 1, 'Você já viu quase todo o mundo e almeja ver o resto. Quando você chega a um lugar no qual nunca esteve, pelo resto da aventura o custo de Audácia diminui em –1 PM e você pode usá-la em testes de ataque (ambos nesse lugar).', true, '{"other":"17º nível de bucaneiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Lorotas da Terra e do Mar', 1, 'Você pode gastar 10 minutos para contar uma mentira sobre seu passado. Escolha uma cena de uma de suas aventuras e reconte-a de forma “criativa” para um NPC que não a testemunhou. Então faça um teste de Enganação (CD 15 + 5 para cada vez que usou este poder na mesma aventura). Se passar, pode usar um poder qualquer cujos pré- -requisitos cumpra e que seja relacionado à sua mentira (a critério do mestre), até o fim do dia ou até usar este efeito novamente. Se falhar, não pode mais usar este efeito até o fim da aventura.', true, '{"other":"treinado em Enganação, 11º nível de bucaneiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Onda de Sangue', 1, 'Sempre que você deixa alguém sangrando, a perda de vida causada por sangramento aumenta em um passo (cumulativo até um máximo de d12) e a criatura falha automaticamente em seu próximo teste de Constituição para remover essa condição.', true, '{"other":"Estocada no Flanco"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Passo Das Ondas', 1, 'Uma vez por rodada, quando acerta um ataque em um inimigo, você pode gastar 2 PM para se mover até a metade do seu deslocamento. Esse deslocamento ignora terreno difícil e não ativa reações dos inimigos (como pelo poder Ataque Reflexo).', true, '{"other":"Pernas do Mar"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Pernas do Mar', 1, 'Você recebe +2 em Acrobacia e Atletismo. Além disso, quando está se equilibrando ou escalando, você não fica desprevenido e seu deslocamento não é reduzido à metade.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Pirouette', 1, 'Enquanto está sob efeito de En Garde, você pode gastar uma ação de movimento para receber +5 na Defesa por 1 rodada.', true, '{"other":"En Garde"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Pistoleiro', 1, 'Você recebe proficiência com armas de fogo e +2 nas rolagens de dano com essas armas.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Presença Paralisante', 1, 'Você soma seu Carisma em Iniciativa e, se for o primeiro na iniciativa, ganha uma ação padrão extra na primeira rodada.', true, '{"other":"Car 1, 4º nível de bucaneiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Remise', 1, 'Enquanto está sob efeito de En Garde, uma vez por rodada, quando usa a ação agredir, você pode gastar 2 PM para realizar um ataque adicional.', true, '{"other":"En Garde, 7º nível de bucaneiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Ripostar', 1, 'Quando usa a habilidade aparar e evita o ataque, você pode gastar 1 PM. Se fizer isso, pode fazer um ataque corpo a corpo imediato contra o inimigo que o atacou (se ele estiver em alcance).', true, '{"other":"Aparar, 12º nível de bucaneiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Sucesso Atrai Sucesso', 1, 'Você pode gastar 2 PM para invocar uma onda de boa sorte. Sempre que fizer um acerto crítico em um inimigo, você recebe um bônus cumulativo de +2 nas rolagens de dano (limitado pelo seu Carisma) até o fim da cena.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Touché', 1, 'Quando se aproxima de um inimigo e o ataca com uma arma corpo a corpo leve ou ágil no mesmo turno, você pode gastar 2 PM para aumentar seu dano em um passo e receber +5 na margem de ameaça neste ataque.', true, '{"other":"Esgrimista, 10º nível de bucaneiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Esquiva Sagaz', 1, 'No 3º nível, você recebe +1 na Defesa e em Reflexos. Esse bônus aumenta em +1 a cada quatro níveis. Esta habilidade exige liberdade de movimentos; você não pode usá-la se estiver de armadura pesada ou na condição imóvel.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Panache', 1, 'A partir do 5º nível, sempre que faz um acerto crítico em combate ou reduz um inimigo a 0 PV, você recupera 1 PM.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Evasão Aprimorada', 1, 'A partir do 10º nível, quando sofre um efeito que permite um teste de Reflexos para reduzir o dano à metade, você não sofre dano algum se passar e sofre apenas metade do dano se falhar. Esta habilidade exige liberdade de movimentos; você não pode usá-la se estiver de armadura pesada ou na condição imóvel.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Sorte de Nimb', 1, 'No 20º nível, você encara os piores desafios e ri na cara deles — pois sabe que tem a sorte ao seu lado. Quando faz um teste, você pode gastar 5 PM para rolá-lo novamente. Qualquer resultado 11 ou mais na segunda rolagem será considerado um 20 natural.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Escola de Duelo (Duelista)', 1, 'No 2º nível, escolha uma escola de duelo entre as seguintes. Uma vez feita, essa escolha não pode ser mudada.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Truques de Capa (Duelista)', 1, 'A partir do 4º nível, se estiver usando uma capa esvoaçante (ou outro item semelhante aprovado pelo mestre), você pode gastar 2 PM e a ação indicada para gerar um dos efeitos a seguir.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Técnica Avançada (Duelista)', 1, 'No 10º nível, você aprende uma técnica de combate conforme sua escola de duelo. Você só pode usar esta habilidade se estiver usando sua escola.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bucaneiro', 'Duelista Lendário (Duelista)', 1, 'No 20º nível, seu domínio de sua escola atinge o ápice. Quando faz um ataque utilizando sua escola de duelo, você pode gastar 1 PM para rolá-lo novamente. Quando um oponente o ataca enquanto você está usando sua escola de duelo, você pode gastar 1 PM para forçá-lo a rolar o teste novamente (apenas uma vez por ataque).', false, NULL);
INSERT INTO classes (name, publication, hit_points, mana_points, skills, proficiencies) VALUES ('Bárbaro', 'Tormenta20', '24+CON', '3 por nível', '["Fortitude","Luta","Adestramento","Atletismo","Cavalgar","Iniciativa","Intimidação","Ofício","Percepção","Pontaria","Sobrevivência","Vontade"]'::jsonb, '["Armas marciais","Escudos"]'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Fúria', 1, 'Você pode gastar 2 PM para invocar uma fúria selvagem. Você recebe +2 em testes de ataque e rolagens de dano corpo a corpo, mas não pode fazer nenhuma ação que exija calma e concentração (como usar a perícia Furtividade ou lançar magias). A cada cinco níveis, pode gastar +1 PM para aumentar os bônus em +1. A Fúria termina se, ao fim da rodada, você não tiver atacado nem sido alvo de um efeito (ataque, habilidade, magia...) hostil.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Alma de Bronze', 1, 'Quando entra em fúria, você recebe uma quantidade de pontos de vida temporários igual a seu nível + sua Força.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Alma Inabalável', 1, 'Quando faz um teste de resistência, você pode gastar 1 PM para substituir a perícia normal por Intimidação. Se você passar no teste e a fonte do efeito for uma criatura, ela fica abalada por 1d4 rodadas (Vontade CD igual ao resultado do teste de Intimidação evita).', true, '{"other":"treinado em Intimidação"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Ampliar Brado', 1, 'O alcance de seus brados aumenta para médio e a CD para resistir a eles aumenta em +2.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Arremesso Violento', 1, 'Enquanto você está em fúria, o dano e o alcance de suas armas de arremesso aumenta em um passo (de curto para médio e de médio para longo) e a penalidade em ataques que você sofre por arremessar armas sem alcance diminui para –2.', true, '{"other":"Fúria da Savana"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Aumento de Atributo', 1, 'Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Beberrão Selvagem', 1, 'Você pode gastar uma ação de movimento para ingerir um preparado alquímico que cause dano e tenha uma criatura como alvo. Se fizer isso, armazena o equivalente a 3 cargas do preparado em sua boca. Até o fim da cena, sempre que acerta um ataque corpo a corpo, você pode gastar uma carga para que o ataque cause dano adicional igual ao do preparado.', true, '{"other":"Con 3"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Brado: Assombroso', 1, 'Você pode gastar uma quantidade de PM limitada pela sua Constituição. Para cada PM que gastar, você causa 1d6 pontos de dano psíquico em todos os inimigos no alcance do brado (Von CD Con reduz à metade). Medo.', true, '{"other":"Brado Assustador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Brado Assustador', 1, 'Você pode gastar uma ação de movimento e 1 PM para soltar um berro feroz. Todos os inimigos em alcance curto ficam vulneráveis até o fim da cena. Pré-requisito: treinado em Intimidação. Medo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Brado: Retardante', 1, 'Você dá um berro que faz seus inimigos hesitarem. Criaturas a sua escolha no alcance do brado ficam lentas por 1 rodada. Medo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Brado: Sísmico', 1, 'Você emite um brado que faz o chão tremer. Criaturas no alcance do brado ficam vulneráveis por 1d4 rodadas e caídas (Fort CD For reduz para vulneráveis por 1 rodada). Criaturas que já estavam vulneráveis, inclusive por este efeito, ficam desprevenidas pelo mesmo tempo.', true, '{"other":"outro poder de brado"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Brado Vitorioso', 1, 'Quando faz um acerto crítico ou reduz um inimigo a 0 ou menos PV enquanto está em fúria, você pode usar um dos seus poderes de brado como ação livre.', true, '{"other":"Brado Assustador, Sangue dos Inimigos"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Crítico Brutal', 1, 'Seu multiplicador de crítico com armas corpo a corpo e de arremesso aumenta em +1. Por exemplo, seu multiplicador com um machado de batalha (normalmente x3) será x4.', true, '{"other":"6º nível de bárbaro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Destruidor', 1, 'Quando causa dano com uma arma corpo a corpo de duas mãos, você pode rolar novamente qualquer resultado 1 ou 2 das rolagens de dano da arma.', true, '{"other":"For 1"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Enigma do Aço', 1, 'Após tantas lutas e matanças, você descobriu que a verdadeira força não reside na arma, mas na mão de quem a empunha. Se estiver empunhando uma arma mundana, você recebe +5 em testes de ataque e causa dois dados extras de dano do mesmo tipo.', true, '{"other":"17º nível de bárbaro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Espírito Inquebrável', 1, 'Enquanto está em fúria, você não fica inconsciente por estar com 0 PV ou menos (você ainda morre se chegar em um valor negativo igual à metade de seus pontos de vida máximos).', true, '{"other":"Alma de Bronze"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Espiritualista', 1, 'Você recebe +1 PM a cada nível ímpar. Além disso, aprende e pode lançar uma magia adicional definida pelo seu animal totêmico (atributo-chave Sabedoria) e pode lançá-la e sustentá-la mesmo em fúria. As magias são: Coruja (Augúrio), Corvo (Voz Divina), Falcão (Mapear), Grifo (Físico Divino), Lobo (Localização), Raposa (Camuflagem Ilusória), Tartaruga (Vestimenta da Fé), Urso (Soco de Arsenal).', true, '{"other":"Sab 2, Totem Espiritual, 6º nível de bárbaro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Esquiva Sobrenatural', 1, 'Seus instintos são tão apurados que você consegue reagir ao perigo antes que seus sentidos o percebam. Você nunca fica surpreendido.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Força Indomável', 1, 'Quando faz um teste de Força ou Atletismo, você pode gastar 1 PM para somar seu nível nele. Você pode usar esta habilidade depois de rolar o dado, mas deve usá-la antes de o mestre dizer se você passou ou não.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Frenesi', 1, 'Uma vez por rodada, se estiver em fúria e usar a ação agredir para fazer um ataque corpo a corpo ou com uma arma de arremesso, você pode gastar 2 PM para fazer um ataque adicional.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Fúria Bestial', 1, 'Enquanto você está em fúria, o dano das suas armas naturais aumenta em dois passos e o multiplicador de crítico delas aumenta em +1.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Fúria da Savana', 1, 'Seu deslocamento aumenta em +3m. Quando usa Fúria, você aplica o bônus em ataque e dano também a armas de arremesso.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Fúria Elemental', 1, 'Escolha um elemento entre ácido, eletricidade, fogo ou frio. Uma vez feita, essa escolha não pode ser mudada. Enquanto está em fúria e faz um ataque em que aplique seus benefícios, você causa +1d12 pontos de dano do tipo escolhido.', true, '{"other":"Totem Espiritual, 11º nível de bárbaro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Fúria Raivosa', 1, 'Se sua Fúria for terminar por você não ter atacado nem sido alvo de um efeito hostil, você pode pagar 1 PM para continuar em fúria nesta rodada. Se você atacar ou for atacado na rodada seguinte, sua fúria continua normalmente.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Golpe Poderoso', 1, 'Ao acertar um ataque corpo a corpo ou com uma arma de arremesso, você pode gastar 1 PM para causar um dado extra de dano do mesmo tipo (por exemplo, com um montante, causa +1d6, para um dano total de 3d6; com um machado de guerra, causa +1d12, para um dano total de 2d12).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Ímpeto', 1, 'Você pode gastar 1 PM para aumentar seu deslocamento em +6m por uma rodada.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Impiedoso', 1, 'Você recebe +2 em testes de ataque, rolagens de dano e na CD de suas habilidades contra criaturas vulneráveis.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Investida Imprudente', 1, 'Quando faz uma investida, você pode aumentar sua penalidade na Defesa pela investida para –5 para receber um bônus de +1d12 na rolagem de dano deste ataque.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Invocar os Ancestrais', 1, 'Você pode gastar uma ação completa e 2 PM para invocar 1d4+1 ancestrais capangas em espaços desocupados em alcance curto. Eles têm Defesa igual à sua, 1 PV, são incorpóreos e falham automaticamente em qualquer teste de resistência ou oposto. Você pode gastar uma ação de movimento para fazê-los se mover (deslocamento 9m). Cada ancestral fornece um bônus cumulativo de +2 em rolagens de dano a um personagem adjacente e, uma vez por rodada, quando faz a ação agredir, você pode gastar um ancestral pra fazer um ataque adicional.', true, '{"other":"Totem Espiritual, 11º nível de bárbaro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Manifestar Totem', 1, 'Escolha um tipo de parceiro entre assassino, atirador, combatente, fortão, guardião, perseguidor ou montaria. Uma vez feita, essa escolha não pode ser mudada. Você pode gastar 3 PM e uma ação de movimento para invocar uma manifestação espiritual de seu animal totêmico até o fim da cena. Ele é um parceiro veterano do tipo escolhido.', true, '{"other":"Totem Espiritual, 7º nível de bárbaro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Pele de Aço', 1, 'O bônus de Pele de Ferro aumenta para +8.', true, '{"other":"Pele de Ferro, 8º nível de bárbaro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Pele de Ferro', 1, 'Você recebe +4 na Defesa, mas apenas se não estiver usando armadura pesada.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Poderes de Brado', 1, 'Poderes de brado compartilham as seguintes regras.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Recuperação Gutural', 1, 'Quando usa um brado enquanto está em fúria, você recebe uma quantidade de PV temporários igual à metade do seu nível + sua Força.', true, '{"other":"Alma de Bronze, um poder de brado"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Regeneração Sobrenatural', 1, 'Enquanto está em fúria e com menos da metade de seus PV máximos, você tem Cura Acelerada 5.', true, '{"other":"Con 5, Vigor Primal, 5º nível de bárbaro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Revide', 1, 'Uma vez por rodada, quando sofre dano de um ataque corpo a corpo enquanto está em fúria, você pode gastar 2 PM para fazer um ataque corpo a corpo contra a criatura que o atacou, desde que ela esteja em seu alcance.', true, '{"other":"Frenesi, 11º nível de bárbaro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Rigidez Selvagem', 1, 'Enquanto está em fúria, você soma o bônus da fúria na Defesa, em Fortitude e em RD.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Sangue dos Inimigos', 1, 'Enquanto está em fúria, quando faz um acerto crítico ou reduz um inimigo a 0 PV, você recebe um bônus cumulativo de +1 em testes de ataque e rolagens de dano, limitado pelo seu nível, até o fim da cena.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Sede Sanguinária', 1, 'Enquanto está em fúria, quando faz um acerto crítico ou reduz um inimigo a 0 PV ou menos, você recupera 10 PV e 2 PM.', true, '{"other":"Sangue dos Inimigos, 5º nível de bárbaro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Superstição', 1, 'Você odeia magia, o que faz com que seja mais resistente a ela. Você recebe resistência a magia +5.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Totem Espiritual', 1, 'Você soma sua Sabedoria no seu total de pontos de mana. Escolha um animal totêmico (veja o quadro ao lado). Você aprende e pode lançar uma magia definida pelo animal escolhido (atributo-chave Sabedoria) e pode lançá-la mesmo em fúria.', true, '{"other":"Sab 1, 4º nível de bárbaro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Vigor Primal', 1, 'Você pode gastar uma ação de movimento e uma quantidade de PM limitada por sua Constituição. Para cada PM que gastar, você recupera 1d12 pontos de vida.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Instinto Selvagem', 1, 'No 3º nível, você recebe +1 em rolagens de dano, Percepção e Reflexos. A cada seis níveis, esse bônus aumenta em +1.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Redução de Dano', 1, 'A partir do 5º nível, graças a seu vigor e força de vontade, você ignora parte de seus ferimentos. Você recebe redução de dano 2 (todo dano que sofre é reduzido em 2). A cada três níveis, sua RD aumenta em 2, até um máximo de RD 10 no 17º nível.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Fúria Titânica', 1, 'No 20º nível, o bônus que você recebe nos testes de ataque e rolagens de dano quando usa Fúria é dobrado. Por exemplo, se gastar 5 PM, em vez de um bônus de +5, recebe um bônus de +10.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Grunhidos (Machado de Pedra)', 1, 'Você conhece apenas o idioma rústico da pequena comunidade onde viveu e nenhum outro. Você não só é incapaz de compreender outros dialetos como não se importa com isso, comunicando-se com grunhidos e sons simples. Contudo, você conhece uma palavra no idioma valkar (o mais comum de Arton) por nível de machado de pedra.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Machado de Pedra (Machado de Pedra)', 1, 'Você não recebe proficiência com armas simples. Você sabe usar apenas adaga, azagaia, clava, funda, lança, machadinha e tacape. No 9° nível, aprende a usar uma arma simples ou marcial a sua escolha. Entretanto, quando ataca com uma arma natural, um ataque desarmado ou uma dessas armas, você recebe +1 no teste de ataque e na rolagem de dano.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Tanga de Peles (Machado de Pedra)', 1, 'Você não recebe proficiência com armaduras leves. Entretanto, se não estiver usando armadura, você soma sua Constituição na Defesa. Além disso, no 3º nível, e a cada quatro níveis seguintes, você recebe +1 na Defesa.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Fúria Primitiva (Machado de Pedra)', 1, 'A partir do 2º nível, se não estiver usando armadura e estiver empunhando uma das armas de sua habilidade Machado de Pedra, o custo de sua Fúria é reduzido em –1 PM. Além disso, uma vez por cena, quando entra em fúria, você recebe uma quantidade de PV temporários igual ao seu nível + sua Constituição.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Resiliência Primal (Machado de Pedra)', 1, 'A partir do 5º nível, graças a seu vigor e força de vontade, você ignora parte de seus ferimentos. Você recebe redução de dano 3. A cada três níveis, sua RD aumenta em 3, até um máximo de RD 15 no 17º nível.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Fúria Rústica (Machado de Pedra)', 1, 'No 20º nível, quando entra em fúria, você pode gastar 5 PM. Se fizer isso, durante a fúria você recebe Cura Acelerada 10 (cumulativo com outras Curas Aceleradas) e, quando faz a ação agredir, pode fazer um ataque desarmado adicional.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Bárbaro', 'Animais Totêmicos', 1, 'A seguir está uma lista de animais venerados por tribos bárbaras de Arton.
INSERT INTO classes (name, publication, hit_points, mana_points, skills, proficiencies) VALUES ('Cavaleiro', 'Tormenta20', '20+CON', '3 por nível', '["Fortitude","Luta","Adestramento","Atletismo","Cavalgar","Diplomacia","Guerra","Iniciativa","Intimidação","Nobreza","Percepção","Vontade"]'::jsonb, '["Armas marciais","Armaduras pesadas","Escudos"]'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Código de Honra', 1, 'Cavaleiros distinguem-se de meros combatentes por seguir um código de conduta. Fazem isto para mostrar que estão acima dos mercenários e bandoleiros que infestam os campos de batalha. Você não pode atacar um oponente pelas costas (em termos de jogo, não pode se beneficiar do bônus de flanquear), caído, desprevenido ou incapaz de lutar. Se violar o código, você perde todos os seus PM e só pode recuperá-los a partir do próximo dia. Rebaixar-se ao nível dos covardes e desesperados abala a autoconfiança que eleva o cavaleiro.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Baluarte', 1, 'Quando sofre um ataque ou faz um teste de resistência, você pode gastar 1 PM para receber +2 na Defesa e nos testes de resistência até o início do seu próximo turno. A cada quatro níveis, pode gastar +1 PM para aumentar o bônus em +2. A partir do 7º nível, quando usa esta habilidade, você pode gastar 2 PM adicionais para fornecer o mesmo bônus a todos os aliados adjacentes. Por exemplo, pode gastar 4 PM ao todo para receber +4 na Defesa e nos testes de resistência e fornecer este mesmo bônus aos outros. A partir do 15º nível, você pode gastar 5 PM adicionais para fornecer o mesmo bônus a todos os aliados em alcance curto.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Duelo', 1, 'A partir do 2º nível, você pode gastar 2 PM para escolher um oponente em alcance curto e receber +2 em testes de ataque e rolagens de dano contra ele até o fim da cena. Se atacar outro oponente, o bônus termina. A cada cinco níveis, você pode gastar +1 PM para aumentar o bônus em +1.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Armas da Cavalaria', 1, 'Você recebe +2 em testes de ataque e rolagens de dano com espadas longas e bastardas, escudos leves e pesados, lanças montadas e de justa, maças e alabardas.', true, '{"other":"5º nível de cavaleiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Armadura da Honra', 1, 'No início de cada cena, você recebe uma quantidade de pontos de vida temporários igual a seu nível + seu Carisma. Os PV temporários duram até o final da cena.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Aumento de Atributo', 1, 'Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Autoridade Feudal', 1, 'Você pode gastar uma hora e 2 PM para conclamar o povo a ajudá-lo (qualquer pessoa sem um título de nobreza ou uma posição numa igreja reconhecida pelo seu reino). Em termos de jogo, essas pessoas contam como um parceiro iniciante de um tipo a sua escolha (aprovado pelo mestre) que lhe acompanha até o fim da aventura. Esta habilidade só pode ser usada em locais onde sua posição carregue alguma influência (a critério do mestre).', true, '{"other":"6º nível de cavaleiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Cavaleiro das Paixões', 1, 'Você recebe +5 em testes de atributo para usar suas Paixões.', true, '{"other":"um poder de Paixão"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Cavaleiro Bandido', 1, 'Você abandonou sua honra em favor de vitórias fáceis. Você perde as habilidades Código de Honra e Duelo, mas recebe Ataque Furtivo como se fosse um ladino do seu nível de cavaleiro.', true, '{"other":"Código de Honra, Duelo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Cavaleiro Sagrado', 1, 'Você recebe um poder de paladino cujos pré-requisitos cumpra, usando seu nível de cavaleiro como nível de paladino.', true, '{"other":"treinado em Religião, devoto de uma divindade que aceite paladinos"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Desprezar os Covardes', 1, 'Você recebe redução de dano 5 se estiver caído, desprevenido ou flanqueado.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Duelista Escudado', 1, 'Enquanto sua habilidade Duelo estiver ativa e você estiver empunhando um escudo, você recebe RD igual ao bônus concedido pela habilidade.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Duelo Irrecusável', 1, 'Enquanto sua habilidade Duelo estiver ativa, a criatura escolhida sofre uma penalidade em testes de ataque e rolagens de dano contra seus aliados igual ao bônus concedido pela habilidade.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Escudeiro', 1, 'Você recebe os serviços de um escudeiro, um parceiro especial que cuida de seu equipamento. Suas armas fornecem +1 em rolagens de dano e sua armadura concede +1 na Defesa. Além disso, você pode pagar 1 PM para receber ajuda do escudeiro em combate. Você recebe uma ação de movimento que pode usar para se levantar, sacar um item ou trazer sua montaria. O escudeiro não conta em seu limite de parceiros. Caso ele morra, você pode treinar outro com um mês de trabalho.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Especialização em Armadura', 1, 'Se estiver usando armadura pesada, você recebe redução de dano 5 (cumulativa com a RD fornecida por Bastião).', true, '{"other":"12º nível de cavaleiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Estandarte', 1, 'Sua flâmula torna-se um símbolo de inspiração. No início de cada cena, você e todos os aliados que possam ver seu estandarte recebem um número de PM temporários igual ao seu Carisma (mínimo 1). Esses pontos temporários desaparecem no final da cena.', true, '{"other":"Título, 14º nível de cavaleiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Etiqueta', 1, 'Você recebe +2 em Diplomacia e Nobreza e quando faz um teste dessas perícias pode gastar 1 PM para rolá-lo novamente.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Grão-Mestre', 1, 'Você é um cavaleiro lendário. Talvez seja um oficial de alto escalão — ou mesmo o líder — de uma ordem de cavalaria, talvez seja apenas um cavaleiro errante famoso no Reinado e além. Você recebe +5 em testes de Diplomacia e Nobreza e, quando ataca um inimigo contra o qual esteja recebendo os bônus de Duelo, ou quando faz uma investida, você causa dois dados de dano extras do mesmo tipo.', true, '{"other":"17º nível de cavaleiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Honra Compartilhada', 1, 'Quando usa o poder Armadura da Honra, você pode fornecer seu benefício a todos os aliados em alcance curto.', true, '{"other":"Armadura da Honra"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Inércia do Aço', 1, 'Quando acerta um ataque com uma arma de duas mãos em uma criatura, você pode gastar 3 PM para causar metade do dano desse ataque a cada inimigo adjacente a essa criatura.', true, '{"other":"5º nível de cavaleiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Investida Convicta', 1, 'Quando faz uma investida, você pode gastar 1 PM para somar seu Carisma nos testes de ataque e rolagens de dano dela.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Investida Defensiva', 1, 'Quando faz uma investida, você não sofre a penalidade de –2 na Defesa e seu deslocamento não ativa reações de inimigos (como por Ataque Reflexo).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Investida Destruidora', 1, 'Quando faz a ação investida, você pode gastar 2 PM. Se fizer isso, causa +2d8 pontos de dano. Você deve usar esta habilidade antes de rolar o ataque.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Mestre das Posturas', 1, 'O custo para assumir uma postura de combate diminui em –1 PM e você pode assumir e manter duas posturas ao mesmo tempo.', true, '{"other":"dois poderes de postura, 11º nível de cavaleiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Montaria Corajosa', 1, 'Sua montaria concede +1d6 em rolagens de dano corpo a corpo (cumulativo com qualquer bônus que ela já forneça como parceiro).', true, '{"other":"Montaria"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Poderes de Paixão', 1, 'Paixões são aspectos da vida de um cavaleiro aos quais ele se entrega com dedicação total. São crenças tão importantes que, em nome delas, ele é capaz de se inspirar e sobrepujar quaisquer limitações. Contudo, se um cavaleiro é derrotado enquanto está inspirado por sua Paixão, a vergonha pode abalá-lo profundamente. Esses poderes compartilham as seguintes regras.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Paixão: Amor', 1, 'Ao escolher esta Paixão, decida a quem ela vai se aplicar. Pode ser um personagem específico (como um amigo, parente ou interesse romântico) ou um grupo de pessoas (como sua família). Você pode evocar esta Paixão para extrair forças desse amor. Se passar, recupera 2d4 PM por ponto de bônus máximo que sua habilidade Duelo pode fornecer.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Paixão: Honra', 1, 'A principal virtude de um cavaleiro, a honra é o combustível de seus feitos. Você pode evocar esta Paixão para resistir aos mais severos ferimentos. Se passar, recupera 2d12 PV por ponto de bônus máximo que sua habilidade Duelo pode fornecer.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Paixão: Hospitalidade', 1, 'Para um cavaleiro, a hospitalidade vai além do abrigo físico: representa também o papel do cavaleiro como guardião daqueles ao seu redor. Você pode evocar esta Paixão para proteger seus aliados. Se passar, você emana uma aura de 6m de raio; dentro dela, você e seus aliados recebem um bônus na Defesa e em testes de resistência igual ao bônus máximo que sua habilidade Duelo pode fornecer.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Paixão: Lealdade', 1, 'Ao escolher esta Paixão, decida a quem sua lealdade será dedicada. Pode ser um nobre, uma organização, uma região etc. Você pode evocar esta Paixão para buscar forças nesse compromisso de fidelidade. Se passar, você recebe um bônus em testes de ataque e rolagens de dano igual ao bônus máximo que sua habilidade Duelo pode fornecer.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Pajem', 1, 'Você recebe os serviços de um pajem, um parceiro que o auxilia em pequenos afazeres. Você recebe +2 em Diplomacia, por estar sempre aprumado, e sua condição de descanso é uma categoria acima do padrão pela situação (veja a página 106). O pajem pode executar pequenas tarefas, como entregar mensagens e comprar itens, e não conta em seu limite de parceiros. Caso ele morra, você pode treinar outro com uma semana de trabalho.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Posturas de Combate', 1, 'Alguns poderes do cavaleiro são Posturas de Combate. Esses poderes compartilham as seguintes regras.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Postura de Combate: Aríete Implacável', 1, 'Ao assumir esta postura, você aumenta o bônus de ataque em investidas em +2. Para cada 2 PM adicionais que gastar quando assumir a postura, aumenta o bônus de ataque em +1. Além disso, se fizer uma investida contra um construto ou objeto, causa +2d8 de dano. Você precisa se deslocar todos os turnos para manter esta postura ativa.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Postura de Combate: Armamento Pesado', 1, 'Para assumir esta postura, você precisa estar empunhando uma arma corpo a corpo de duas mãos. Você recebe +2 em Fortitude e em rolagens de dano com esta arma. Para cada PM adicional que você gastar quando assumir a postura, esse bônus aumenta em +1 (até um limite de +5). Além disso, quando acerta um ataque nesta postura, você pode empurrar o alvo 1,5m. Você precisa atacar todos os turnos para manter esta postura ativa.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Postura de Combate: Castigo de Ferro', 1, 'Sempre que um aliado adjacente sofrer um ataque corpo a corpo, você pode gastar 1 PM para fazer um ataque na criatura que o atacou.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Postura de Combate: Foco de Batalha', 1, 'Sempre que um inimigo atacá-lo, você recebe 1 PM temporário (cumulativos). Você pode ganhar um máximo de PM temporários por cena igual ao seu nível. Esses pontos temporários desaparecem no final da cena.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Postura de Combate: Muralha Intransponível', 1, 'Para assumir esta postura você precisa estar empunhando um escudo. Você recebe +1 na Defesa e em Reflexos. Além disso, quando sofre um efeito que permite um teste de Reflexos para reduzir o dano à metade, não sofre nenhum dano se passar. Para cada 2 PM adicionais que gastar quando assumir a postura, aumente esse bônus em +1. Por fim, enquanto mantiver esta postura, seu deslocamento é reduzido para 3m.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Postura de Combate: Provocação Petulante', 1, 'Enquanto esta postura estiver ativa, todos os inimigos que iniciarem seus turnos em alcance curto devem fazer um teste de Vontade (CD Car). Se falharem, qualquer ação hostil que realizarem deve ter você como alvo (mas suas outras ações não têm esta restrição). Ações hostis incluem ataques e outras ações que causem dano e/ou condições negativas. Mental.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Postura de Combate: Quebra-Magia', 1, 'Você recebe resistência a magia +2. Para cada PM adicional que você gastar quando assumir esta postura, esse bônus aumenta em +1. Além disso, uma vez por rodada, quando uma criatura em seu alcance usa uma habilidade mágica, você pode gastar 1 PM para fazer um ataque corpo a corpo contra ela.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Postura de Combate: Sequência Blindada', 1, 'Para assumir esta postura, você precisa estar vestindo armadura pesada. Quando faz a ação agredir, você pode fazer um ataque desarmado além de seus demais ataques.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Postura de Combate: Torre Inabalável', 1, 'Você assume uma postura defensiva que o torna imune a qualquer tentativa de tirá-lo do lugar, de forma mundana ou mágica. Enquanto mantiver a postura, você não pode se deslocar, mas soma sua Constituição na Defesa e pode substituir testes de Reflexos e Vontade por testes de Fortitude.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Presença de Muralha', 1, 'Você pode gastar 1 PM para gerar uma aura com 9m de raio e duração sustentada. Cada inimigo que começar seu turno nessa área deve fazer um teste de Vontade (CD Car). Se falhar, seu deslocamento é reduzido à metade pela duração do efeito. Se passar, não é mais afetado por este efeito nesse dia. Medo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Solidez', 1, 'Se estiver usando um escudo, você soma o bônus na Defesa recebido pelo escudo em testes de resistência.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Título', 1, 'Você adquire um título de nobreza. Converse com o mestre para definir os benefícios exatos de seu título. Como regra geral, no início de cada aventura você recebe 20 TO por nível de cavaleiro (rendimentos dos impostos) ou a ajuda de um parceiro veterano (um membro de sua corte).', true, '{"other":"Autoridade Feudal, 10º nível de cavaleiro, ter conquistado terras ou realizado um serviço para um nobre que possa se tornar seu suserano"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Torre Armada', 1, 'Quando um inimigo erra um ataque contra você, você pode gastar 1 PM. Se fizer isso, recebe +5 em rolagens de dano contra esse inimigo até o fim de seu próximo turno.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Caminho do Cavaleiro', 1, 'No 5º nível, escolha entre Bastião ou Montaria.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Resoluto', 1, 'A partir do 11º nível, você pode gastar 1 PM para refazer um teste de resistência contra uma condição (como abalado, paralisado etc.) que esteja o afetando. O segundo teste recebe um bônus de +5 e, se você passar, cancela o efeito. Você só pode usar esta habilidade uma vez por efeito.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Bravura Final', 1, 'No 20º nível, sua virtude vence a morte. Se for reduzido a 0 ou menos PV, pode gastar 3 PM para continuar consciente e de pé. Esta habilidade tem duração sustentada. Quando se encerra, você sofre os efeitos de seus PV atuais, podendo cair inconsciente ou mesmo morrer.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Jovem Pajem (Vassalo)', 1, 'Você inicia sua carreira como um pajem, servindo a um sir ou dame mais experiente. Você se torna treinado em Adestramento ou Ofício (armeiro).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Suserano (Vassalo)', 1, 'Escolha um membro da nobreza aprovado pelo mestre. Você serve a esse nobre, sendo oficialmente reconhecido como parte de sua corte. Os efeitos de seu status ficam a cargo do mestre mas, como regra geral, você recebe +5 em testes de Diplomacia e Intimidação ao lidar com vassalos de seu suserano de nível inferior ao seu e, nas terras dele, pode obter alojamento e alimentação sem custo. Se deixar de servir a seu suserano por qualquer motivo, você perde todos os seus PM e só pode recuperá-los após ser aceito por outro suserano.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Valete (Vassalo)', 1, 'A partir do 2º nível, você já acompanha seu senhor na corte e nos salões nobres. Você se torna treinado em Diplomacia ou Nobreza e recebe um poder de cavaleiro a sua escolha.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Escudeiro Aprendiz (Vassalo)', 1, 'A partir do 3º nível, você ajuda seu senhor na batalha. Você se torna treinado em Cavalgar e recebe proficiência com armaduras pesadas. Se já tiver proficiência com armaduras pesadas, recebe +2 na Defesa enquanto usa uma armadura pesada.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Guarda do Castelo (Vassalo)', 1, 'No 4º nível, você já patrulha as muralhas do castelo sozinho. Você se torna treinado em Intuição e recebe um poder de cavaleiro a sua escolha.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Vigilante de Estradas (Vassalo)', 1, 'A partir do 5º nível, você expande suas responsabilidades para além do castelo. Você recebe a habilidade Montaria e se torna treinado em Percepção.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Cavaleiro do Reino (Vassalo)', 1, 'No 6º nível, você recebe o título de sir ou dame e atinge o grau mais baixo da nobreza. Você recebe uma arma, armadura ou escudo superior com duas melhorias a sua escolha e recebe um poder de cavaleiro a sua escolha.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Sargento do Reino (Vassalo)', 1, 'No 7º nível, você adquire uma posição no exército do reino. Você recebe um poder de cavaleiro ou de guerreiro a sua escolha (como um guerreiro de nível igual ao seu para propósitos de pré-requisitos).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Capitão do Reino (Vassalo)', 1, 'No 8º nível, você se torna um oficial no exército, respeitado e prestigiado por militares, nobres e plebeus. Você recebe o poder Escudeiro e a habilidade Golpe Divino (Tormenta20, p. 82), como um paladino de nível igual ao seu. Esta não é uma habilidade mágica e provém de seu senso de justiça e determinação em combate (veja “Magias Simuladas”, p. 44).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Lorde (Vassalo)', 1, 'No 9º nível você ascende dentro da nobreza, recebendo um feudo — e muitas responsabilidades. Você recebe o poder Autoridade Feudal. Se já possui esse poder, as pessoas convocadas passam a contar como um parceiro veterano. Além disso, escolha um dos caminhos a seguir.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Barão (Vassalo)', 1, 'No 10º nível, você ascende dentro da nobreza e passa a receber impostos de seus plebeus. Você recebe o poder Título e um domínio de nível 1 (veja p. 314). Se já tiver um domínio, em vez disso ele recebe uma construção gratuita (cujos pré-requisitos seu domínio cumpra).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Visconde (Vassalo)', 1, 'No 11º nível, você adquire um título mais alto. Se escolheu o Caminho do Soldado, recebe +1 PV por nível de vassalo. Se escolheu o Caminho do Governante, recebe +1 em Inteligência.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Conde (Vassalo)', 1, 'A partir do 12º nível, você é um alto nobre e tem acesso a equipamentos poderosos. No início de cada aventura, você recebe um “orçamento” de T$ 30.000 que pode gastar em itens mágicos. Esses itens devem ser devolvidos ou reembolsados no fim da aventura. Além disso, recebe um poder de cavaleiro ou geral a sua escolha.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Marquês (Vassalo)', 1, 'No 13º nível, seus feitos alçam-no a um título ainda mais alto. Se escolheu o Caminho do Soldado, você recebe redução de dano 5 e +2 na Defesa. Se escolheu o Caminho do Governante, você passa a somar seu Carisma em seus testes de resistência.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Duque (Vassalo)', 1, 'No 14º nível, você se tornou um dos mais altos nobres do reino. Quando você usa Autoridade Feudal, o nível do parceiro convocado aumenta em um passo. Além disso, você recebe um poder de cavaleiro a sua escolha.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Arquiduque (Vassalo)', 1, 'No 15º nível você atinge o mais alto grau da nobreza, possuindo uma aura que o distingue das pessoas normais e o torna quase intocável. Uma vez por rodada, quando uma criatura inteligente lhe causar dano, você pode gastar 5 PM para reduzir esse dano a 0.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Conselheiro Real (Vassalo)', 1, 'A partir do 16º nível, você se torna um dos conselheiros do rei e passa a partilhar do poder de Sua Majestade. Você recebe um poder de cavaleiro a sua escolha e aprende e pode lançar uma magia divina de até 4º círculo a sua escolha (atributo-chave Carisma).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Rei Mercenário (Vassalo)', 1, 'No 17º nível, você dá seus primeiros passos rumo à majestade, e a terra responde às suas aspirações. Se escolheu o Caminho do Soldado, você recebe 3 pontos de atributo para distribuir como quiser em Força, Destreza e Constituição. Se escolheu o Caminho do Governante, recebe 3 pontos de atributo para distribuir como quiser em Inteligência, Sabedoria e Carisma.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Rei (Vassalo)', 1, 'No 18º nível, seu reino já não precisa mais do apoio de seu antigo lorde — mas vocês ainda são aliados. Você recebe +1 em Carisma e um poder de cavaleiro a sua escolha.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Alto Rei (Vassalo)', 1, 'No 19º nível, você se torna um alto rei, senhor de seu reino e do antigo reino de seu lorde. Tem a sua disposição seguidores e riquezas sem fim — seu “orçamento” de itens mágicos aumenta para T$ 100.000 e seu limite de parceiros aumenta em 2.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Imperador (Vassalo)', 1, 'No 20º nível, você chegou ao ápice político de Arton. Talvez tenha colonizado um continente desconhecido. Talvez tenha conquistado o Império de Tauron ou o Reinado. De qualquer forma, você agora é um grande imperador, respeitado e temido por todos. Sua fama não tem limites e as pessoas atribuem a você os mais variados poderes. Você recebe +1 em dois atributos diferentes a sua escolha e aprende e pode lançar uma magia divina de até 5º círculo a sua escolha (atributo- -chave Carisma). Você pode começar a pensar em dar terras a seu antigo escudeiro, formando mais um rei e continuando o nobre ciclo do cavaleiro vassalo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'Vassalo em Campanha (Vassalo)', 1, 'O vassalo é uma classe diferente. Em vez de oferecer muitos poderes abertos, que podem ser escolhidos pelo jogador, tem uma lista em grande parte fixa e imutável. Em vez de se encaixar em quase qualquer campanha, exige uma progressão narrativa para o personagem — determinando parcialmente os rumos da história. Como lidar com toda essa esquisitice?
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Cavaleiro', 'O Treinamento de um Vassalo (Vassalo)', 1, 'Ao longo de sua carreira, o vassalo se torna treinado em diversas perícias. Sempre que receber um desses treinamentos por uma habilidade de vassalo, se já for treinado na perícia, em vez disso você recebe +2 nela.', false, NULL);
INSERT INTO classes (name, publication, hit_points, mana_points, skills, proficiencies) VALUES ('Caçador', 'Tormenta20', '16+CON', '4 por nível', '["Luta ou Pontaria","Sobrevivência","Adestramento","Atletismo","Cavalgar","Cura","Fortitude","Furtividade","Iniciativa","Investigação","Luta","Ofício","Percepção","Pontaria","Reflexos"]'::jsonb, '["Armas marciais","Escudos"]'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Marca da Presa', 1, 'Você pode gastar uma ação de movimento e 1 PM para analisar uma criatura em alcance curto. Até o fim da cena, você recebe +1d4 nas rolagens de dano contra essa criatura. A cada quatro níveis, você pode gastar +1 PM para aumentar o bônus de dano (veja a tabela da classe).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Rastreador', 1, 'Você recebe +2 em Sobrevivência. Além disso, pode se mover com seu deslocamento normal enquanto rastreia sem sofrer penalidades no teste de Sobrevivência. Poder de Caçador. No 2º nível, e a cada nível seguinte, você recebe uma habilidade da lista a seguir.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Ambidestria', 1, 'Se estiver empunhando duas armas (e pelo menos uma delas for leve) e fizer a ação agredir, você pode fazer dois ataques, um com cada arma. Se fizer isso, sofre –2 em todos os testes de ataque até o seu próximo turno.', true, '{"other":"Des 2"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Armadilha Alquímica', 1, 'Quando prepara uma armadilha, você pode gastar uma dose de um preparado alquímico. Se fizer isso, as criaturas afetadas pela armadilha também sofrem os efeitos desse preparado automaticamente. Prérequisito: Armadilheiro.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Armadilha: Arataca', 1, 'A vítima sofre 2d6 pontos de dano de perfuração e fica agarrada. Uma criatura agarrada pode escapar com uma ação padrão e um teste de Força ou Acrobacia (CD Sab).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Armadilha: Espinhos', 1, 'A vítima sofre 6d6 pontos de dano de perfuração. Um teste de Reflexos (CD Sab) reduz o dano à metade.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Armadilha: Laço', 1, 'A vítima deve fazer um teste de Reflexos (CD Sab). Se passar, fica caída. Se falhar, fica agarrada. Uma criatura agarrada pode se soltar com uma ação padrão e um teste de Força ou Acrobacia (CD Sab).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Armadilha: Rede', 1, 'Todas as criaturas na área ficam enredadas e não podem sair da área. Uma vítima pode se libertar com uma ação padrão e um teste de Força ou Acrobacia (CD 25). Além disso, a área ocupada pela rede é considerada terreno difícil. Nesta armadilha você escolhe quantas criaturas precisam estar na área para ativá-la.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Armadilheiro', 1, 'A CD para encontrar e resistir às suas armadilhas aumenta em +5 e você soma sua Sabedoria ao dano delas.', true, '{"other":"um poder de armadilha, 5º nível de caçador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Arqueiro', 1, 'Se estiver usando uma arma de ataque à distância, você soma sua Sabedoria nas rolagens de dano (limitado pelo seu nível).', true, '{"other":"Sab 1"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Aumento de Atributo', 1, 'Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Avanço do Predador', 1, 'Uma vez por rodada, quando uma criatura marcada por sua Marca da Presa se afasta voluntariamente de você, você pode gastar 1 PM para se mover na direção dela (até o limite do seu deslocamento).', true, '{"other":"Ímpeto, 11° nível de caçador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Batedor Marcial', 1, 'Você pode usar testes de Sobrevivência no lugar de testes de Guerra. Além disso, se passar em um teste para analisar terreno, além de quaisquer benefícios encontrados, na próxima vez que usar Marca da Presa nessa cena você recupera 1 PM.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Bote', 1, 'Se estiver empunhando duas armas e fizer uma investida, você pode pagar 1 PM para fazer um ataque adicional com sua arma secundária.', true, '{"other":"Ambidestria, 6º nível de caçador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Camuflagem', 1, 'Você pode gastar 2 PM para se esconder mesmo sem camuflagem ou cobertura disponível.', true, '{"other":"6º nível de caçador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Chuva de Lâminas', 1, 'Uma vez por rodada, quando usa Ambidestria, você pode pagar 2 PM para fazer um ataque adicional com sua arma primária.', true, '{"other":"Des 4, Ambidestria, 12º nível de caçador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Companheiro Animal', 1, 'Você recebe um companheiro animal. Veja o quadro na página 62.', true, '{"other":"Car 1, treinado em Adestramento"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Curandeiro dos Ermos', 1, 'Você pode usar Ervas Curativas como uma ação de movimento e os dados de cura dessa habilidade aumentam para d8.', true, '{"other":"Ervas Curativas"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Elo com a Natureza', 1, 'Você soma sua Sabedoria em seu total de pontos de mana e aprende e pode lançar Caminhos da Natureza (atributo-chave Sabedoria). Pré-requisitos: Sab 1, 3º nível de caçador. e', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Elo Com a Natureza Maior', 1, 'Escolha duas magias entre Abençoar Alimentos, Acalmar Animal, Alarme, Aviso, Conjurar Armadilhas , Detectar Ameaças, Orientação ou Suporte Ambiental. Você aprende e pode lançar as magias escolhidas (atributo- -chave Sabedoria) e pode usar seus aprimoramentos como se tivesse acesso aos mesmos círculos de magia que um druida do seu nível. Você pode escolher este poder mais vezes para magias diferentes.', true, '{"other":"Elo com a Natureza"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Emboscar', 1, 'Você pode gastar 2 PM para realizar uma ação padrão adicional em seu turno. Você só pode usar este poder na primeira rodada de um combate.', true, '{"other":"treinado em Furtividade"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Empatia Selvagem', 1, 'Você pode se comunicar com animais por meio de linguagem corporal e vocalizações. Você pode usar Adestramento com animais para mudar atitude e persuasão (veja Diplomacia, na página 118).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Escaramuça', 1, 'Quando se move 6m ou mais, você recebe +2 na Defesa e Reflexos e +1d8 nas rolagens de dano de ataques corpo a corpo e à distância em alcance curto até o início de seu próximo turno. Você não pode usar esta habilidade se estiver vestindo armadura pesada.', true, '{"other":"Des 2, 6º nível de caçador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Escaramuça Superior', 1, 'Quando usa Escaramuça, seus bônus aumentam para +5 na Defesa e Reflexos e +1d12 em rolagens de dano.', true, '{"other":"Escaramuça, 12º nível de caçador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Espreitar', 1, 'Quando usa a habilidade Marca da Presa, você recebe um bônus de +1 em testes de perícia contra a criatura marcada. Esse bônus aumenta em +1 para cada PM adicional gasto na habilidade e também dobra com a habilidade Inimigo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Ervas Curativas', 1, 'Você pode gastar uma ação completa e uma quantidade de PM a sua escolha (limitado por sua Sabedoria) para aplicar ervas que curam ou desintoxicam em você ou num aliado adjacente. Para cada PM que gastar, cura 2d6 PV ou remove uma condição envenenado afetando o alvo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Explorador Viajado', 1, 'Você pode escolher dois tipos de terrenos extras para sua habilidade Explorador. Você pode escolher este poder mais vezes para tipos de terrenos adicionais.', true, '{"other":"5º nível de caçador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Flecheiro', 1, 'Você pode usar Sobrevivência no lugar de Ofício para fabricar munições e pode fabricar munições com uma melhoria.', true, '{"other":"3° nível de caçador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Golpe do Predador', 1, 'Se você causar dano em uma criatura analisada por sua Marca da Presa, ela fica sangrando. Se ela já estiver sangrando, a perda de vida por sangramento aumenta em um passo (cumulativo até um máximo de d12) e ela falha automaticamente em seu próximo teste de Constituição para remover essa condição.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Herói do Povo', 1, 'Você recebe +2 na Defesa e em testes de resistência. Além disso, sempre que acertar um ataque em um vilão que esteja ameaçando pessoas comuns (um bandido assolando camponeses, um nobre tirano, um monstro devorando viajantes...), você recebe 2 PM temporários. Você pode receber um número máximo de PM temporários por cena igual ao seu nível e eles desaparecem no fim da cena.', true, '{"other":"5º nível de caçador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Identificar Presas', 1, 'Você pode identificar criaturas como uma ação de movimento. Além disso, se passar nesse teste, para cada informação obtida você recebe +1 em rolagens de dano contra criaturas dessa espécie até o fim da cena.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Ímpeto', 1, 'Você pode gastar 1 PM para aumentar seu deslocamento em +6m por uma rodada.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Inimigo de (Criatura)', 1, 'Escolha um tipo de criatura entre animal, construto, espírito, monstro ou morto-vivo, ou duas raças humanoides (por exemplo, orcs e gnolls, ou elfos e qareen). Quando você usa a habilidade Marca da Presa contra uma criatura do tipo ou da raça escolhida, dobra os dados de bônus no dano. O nome desta habilidade varia de acordo com o tipo de criatura escolhida (Inimigo de Monstros, Inimigo de Mortos-Vivos etc.). Você pode escolher este poder outras vezes para inimigos diferentes.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Lâminas Guardiãs', 1, 'Enquanto você estiver empunhando duas armas corpo a corpo, recebe +2 na Defesa e em testes de resistência contra inimigos em seu alcance natural.', true, '{"other":"Ambidestria, 5° nível de caçador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Lanceiro', 1, 'Você recebe +2 em testes de ataque e rolagens de dano com lanças (exceto lanças montadas e de justa). Além disso, se estiver empunhando uma dessas armas com as duas mãos, seu dano com ela aumenta em um passo e ela é considerada uma arma alongada.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Olho do Falcão', 1, 'Você pode usar a habilidade Marca da Presa em criaturas em alcance longo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Pega!', 1, 'Você pode gastar uma ação de movimento e 1 PM para fazer a manobra agarrar contra uma criatura em alcance curto usando Adestramento em vez de Luta, usando seu companheiro animal para isso. Se o alvo estiver sob efeito de sua Marca da Presa, você soma os dados dessa habilidade como um bônus no teste. A criatura permanece agarrada até vencer um teste de manobra contra seu companheiro animal (como acima) ou até você mandar seu animal soltá-la (uma ação livre).', true, '{"other":"Companheiro Animal"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Ponto Fraco', 1, 'Quando usa a habilidade Marca da Presa, seus ataques contra a criatura marcada recebem +2 na margem de ameaça. Esse bônus dobra com a habilidade Inimigo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Primeiro Sangue', 1, 'Na primeira rodada de cada combate, você recebe +2 em testes de ataque e todos os seus dados de dano aumentam em dois passos.', true, '{"other":"Emboscar"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Sequência Dilaceradora', 1, 'Quando usa Ambidestria, se acertar ambos os ataques, você pode gastar 1 PM para causar +2d8 pontos de dano no segundo ataque.', true, '{"other":"Ambidestria, 11° nível de caçador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Sequência do Predador', 1, 'Quando usa Ambidestria com armas que causam tipos de dano diferentes, se acertar ambos os ataques, você pode gastar 1 PM para fazer uma manobra entre desarmar, derrubar ou quebrar contra o mesmo alvo.', true, '{"other":"Ambidestria, 8° nível de caçador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Sombra dos Ermos', 1, 'Você pode gastar uma ação de movimento e 1 PM para receber camuflagem leve com duração sustentada.', true, '{"other":"Camuflagem"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Tiro de Abate', 1, 'Quando usa a ação mirar, até o fim do turno você recebe +2 em testes de ataque e na margem de ameaça com ataques à distância, e os dados extras de sua habilidade Marca da Presa também são multiplicados em caso de acerto crítico.', true, '{"other":"Sab 1, Espreitar"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Tiro Trespassante', 1, 'Quando você faz um ataque à distância com uma arma de disparo e reduz os pontos de vida do alvo a 0 ou menos, pode gastar 1 PM para fazer um ataque adicional contra outra criatura que esteja adiante na mesma linha, usando a mesma arma e munição do ataque original.', true, '{"other":"Arqueiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Tempestade de Lâminas', 1, 'Quando usa Chuva de Lâminas, você pode fazer um ataque adicional com sua arma secundária (para um total de quatro ataques na ação).', true, '{"other":"Chuva de Lâminas, 17º nível de caçador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Tocaia Habilidosa', 1, 'Sua Marca da Presa também fornece +1 na CD de suas habilidades contra a criatura marcada para cada PM gasto. Esse bônus dobra com a habilidade Inimigo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Último Sangue', 1, 'Seus ataques contra criaturas sangrando causam um dado extra de dano do mesmo tipo.', true, '{"other":"5º nível de caçador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Explorador', 1, 'No 3º nível, escolha um tipo de terreno entre aquático, ártico, colina, deserto, floresta, montanha, pântano, planície, subterrâneo ou urbano. A partir do 11º nível, você também pode escolher área de Tormenta. Quando estiver no tipo de terreno escolhido, você soma sua Sabedoria (mínimo +1) na Defesa e nos testes de Acrobacia, Atletismo, Furtividade, Percepção e Sobrevivência. A cada quatro níveis, escolha outro tipo de terreno para receber o bônus ou aumente o bônus em um tipo de terreno já escolhido em +2.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Caminho do Explorador', 1, 'No 5º nível, você pode atravessar terrenos difíceis sem sofrer redução em seu deslocamento e a CD para rastrear você aumenta em +10. Esta habilidade só funciona em terrenos nos quais você tenha a habilidade Explorador.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Mestre Caçador', 1, 'No 20º nível, você pode usar a habilidade Marca da Presa como uma ação livre. Além disso, quando usa a habilidade, pode pagar 5 PM para aumentar sua margem de ameaça contra a criatura em +2. Se você reduz uma criatura contra a qual usou Marca da Presa a 0 pontos de vida, recupera 5 PM.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Caminho do Atirador (Seteiro)', 1, 'Você abriu mão do treinamento convencional de um caçador para abraçar o caminho do atirador. Suas habilidades de seteiro relacionadas a ataques e armas só funcionam com arcos e bestas.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Tiro de Supressão (Seteiro)', 1, 'Sempre que você causa dano com um arco ou besta em uma criatura que esteja sob efeito de sua Marca da Presa, essa criatura sofre uma penalidade cumulativa de –1 em rolagens de dano, até um valor igual à quantidade de PM gasta em Marca da Presa, até o fim da cena.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Disparo Constritor (Seteiro)', 1, 'No 5° nível, quando usa a ação mirar, você pode pagar 2 PM. Se fizer isso, pode executar uma manobra entre desarmar, empurrar ou quebrar com um de seus ataques à distância feitos até o fim desse turno.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Rajada de Flechas (Seteiro)', 1, 'A partir do 10° nível, você pode gastar uma ação completa e 2 PM para alvejar uma área com seus disparos. Escolha um ponto no alcance de sua arma, então faça um ataque à distância e compare-o com a Defesa de cada inimigo num raio de 3m dele. Então faça uma rolagem de dano, com um bônus cumulativo de +2 para cada acerto, e aplique-a em cada inimigo atingido. Você gasta apenas uma munição, independente de quantos inimigos atacou.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Sentinela (Seteiro)', 1, 'No 15° nível, uma vez por rodada, quando uma criatura sob efeito de sua Marca da Presa acerta um ataque contra um aliado, você pode gastar 1 PM para fazer um ataque contra essa criatura.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Mestre do Disparo (Seteiro)', 1, 'No 20° nível, você pode usar sua Marca da Presa como uma ação livre. Além disso, uma vez por rodada, quando faz um ataque com um arco ou besta contra um alvo de sua Marca da Presa, você pode fazer um ataque adicional contra ele.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Caçador', 'Armadilhas', 1, 'Alguns poderes do caçador são Armadilhas. Esses poderes compartilham as seguintes regras.
INSERT INTO classes (name, publication, hit_points, mana_points, skills, proficiencies) VALUES ('Clérigo', 'Tormenta20', '16+CON', '5 por nível', '["Religião","Vontade","Conhecimento","Cura","Diplomacia","Fortitude","Iniciativa","Intuição","Luta","Misticismo","Nobreza","Ofício","Percepção"]'::jsonb, '["Armaduras pesadas","Escudos"]'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Devoto Fiel', 1, 'Você se torna devoto de um deus maior. Veja as regras de devotos na página 96. Ao contrário de devotos normais, você recebe dois poderes concedidos por se tornar devoto, em vez de apenas um. Como alternativa, você pode cultuar o Panteão como um todo. Não recebe nenhum Poder Concedido, mas sua única obrigação e restrição é não usar armas cortantes ou perfurantes (porque derramam sangue, algo que clérigos do Panteão consideram proibido). Sua arma preferida é a maça e você pode canalizar energia positiva ou negativa a sua escolha (uma vez feita, essa escolha não pode ser mudada). Cultuar o Panteão conta como sua devoção.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Magias', 1, 'Você pode lançar magias divinas de 1º círculo. A cada quatro níveis, pode lançar magias de um círculo maior (2º círculo no 5º nível, 3º círculo no 9º nível e assim por diante). Você começa com três magias de 1º círculo. A cada nível, aprende uma magia de qualquer círculo que possa lançar. Seu atributo-chave para lançar magias é Sabedoria e você soma sua Sabedoria no seu total de PM. Veja o Capítulo 4 para as regras de magia.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Abençoar Arma', 1, 'Você se torna proficiente na arma preferida de sua divindade. Se estiver empunhando essa arma, pode gastar uma ação de movimento e 3 PM para infundi-la com poder divino. Até o final da cena, a arma é considerada mágica e emite luz dourada ou púrpura (como uma tocha). Além disso, o dano da arma aumenta em um passo e você pode usar sua Sabedoria em testes de ataque e rolagens de dano com ela, em vez do atributo padrão (não cumulativo com efeitos que somam este atributo).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Acólito Escudeiro', 1, 'Você recebe os serviços de um acólito escudeiro, um parceiro especial que não conta em seu limite de parceiros. Você recebe +2 em Religião e o custo de uma de suas magias de 1º círculo, escolhida ao você receber este poder, diminui em –1 PM. Além disso, você pode gastar 1 PM para receber os efeitos de um esotérico ou catalisador em seu inventário, mesmo que não o esteja empunhando. Caso perca seu acólito, você pode treinar outro com uma semana de trabalho.', true, '{"other":"Autoridade Eclesiástica"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Arma Divina', 1, 'Quando você usa Abençoar Arma, além dos efeitos normais, a sua arma adquire os efeitos do encanto sagrado (se você canalizar energia positiva) ou do encanto profano (se você canalizar energia negativa).', true, '{"other":"Abençoar Arma, 7º nível de clérigo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Aumento de Atributo', 1, 'Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Básico)', 1, 'Você possui uma posição formal em uma igreja reconhecida pelos outros membros de sua fé. Os efeitos deste poder variam de acordo com a igreja e o deus — clérigos de Khalmyr, por exemplo, possuem autoridade como juízes no Reinado — e ficam a cargo do mestre. Como regra geral, você recebe +5 em testes de Diplomacia ou Intimidação ao lidar com devotos de sua divindade e paga metade do preço de itens alquímicos, poções e serviços em templos de sua divindade.', true, '{"other":"5º nível de clérigo, devoto de um deus maior"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Deuses)', 1, 'Você possui uma posição formal e reconhecida em uma igreja. Você recebe +5 em testes de Diplomacia e Intimidação ao lidar com devotos de sua divindade, além do benefício específico de sua divindade.', true, '{"other":"5º nível de clérigo ou frade, devoto de um deus maior"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Aharadak)', 1, 'Você aprende e pode lançar Sussurros Insanos (Tormenta20, p. 207) como uma magia divina. Além disso, se estiver em um templo de Aharadak, ou com pelo menos 5 outros devotos do Deus da Tormenta, pode gastar 1 hora para executar um ritual que o aproxima da Anticriação. Se fizer isso, você recebe um embrião rubro, uma larva que se aloja em seu corpo e ocupa 1 espaço. Até o fim da aventura, ou até executar esse ritual novamente, você pode despertar essa larva para receber 1 poder da Tormenta a sua escolha, cujos pré-requisitos cumpra, até o fim da cena. Ao fim da cena, a larva se desaloja e cai no chão como uma pequena poça de visco rubro.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Allihanna)', 1, 'Você recebe +5 em Adestramento e Cavalgar, e pode usar essas perícias com animais mesmo sem ser treinado. Além disso, quando descansa em terreno natural, recebe uma bênção dos espíritos locais. Para cada patamar, você recebe 1d4 de auxílio que pode ser adicionado como um bônus em um teste de perícia feito até o fim do dia.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Arsenal)', 1, 'Quando visita um templo do Deus da Guerra, você pode orar para que ele abençoe seu… arsenal. Escolha uma arma, armadura ou escudo; o item recebe uma melhoria a sua escolha (exceto material especial) cujos pré-requisitos ele cumpra. Essa melhoria não conta no limite de melhorias do item. Se tiver o poder Conjurar Arma, você pode aplicar esse benefício às armas ou munições conjuradas com ele. Esses efeitos duram até o fim da aventura ou até você orar por outra melhoria.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Azgher)', 1, 'Você recebe +5 em Sobrevivência. Além disso, uma vez por aventura, se visitar um templo de Azgher, você pode medir o peso de sua alma. Faça um teste de Religião com CD definida pelo mestre: 15 se você seguiu os preceitos de Azgher à risca durante o último mês; 20 se seguiu-os, mas não perfeitamente; 25 se quebrou suas Obrigações & Restrições. Você recebe 1 TO por patamar para cada ponto do resultado acima da CD.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Hyninn)', 1, 'Quando chega a uma comunidade, você pode fazer um teste de Sabedoria (CD 10). Se passar, faz contato com ladrões locais; até partir desse lugar, você recebe +5 em testes de Diplomacia para barganha e de Investigação para interrogar. Além disso, uma vez durante sua estadia pode ganhar a ajuda de um parceiro veterano de um tipo a sua escolha entre ajudante (Enganação, Furtividade e Ladinagem), assassino, fortão, perseguidor ou vigilante, que não conta em seu limite de parceiros.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Kallyadranoch)', 1, 'Você recebe +5 em Intimidação. Além disso, se visitar um templo de Kallyadranoch, você recebe uma fração da energia dominante do Deus dos Dragões. Durante uma cena a sua escolha, sempre que aplicar uma condição de medo em um ou mais inimigos, você recupera 1d4 PM.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Khalmyr)', 1, 'Você recebe +5 em testes de Diplomacia e Intimidação com agentes da lei (cavaleiros, paladinos, guardas e outros, a critério do mestre). Além disso, uma vez por aventura, se estiver em um templo de Khalmyr, você pode solicitar uma escolta: até dois parceiros iniciantes, cada um de um tipo a sua escolha entre combatente, guardião ou médico. Eles o acompanham até o fim da aventura.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Lena)', 1, 'Você recebe o poder Aparência Inofensiva (se já possuí-lo, a CD para resistir a ele aumenta em +2). Além disso, quando passa um dia descansando em um templo da Deusa da Vida, recebe +1 em testes de resistência e +1 PV por nível até o fim da aventura. A seu critério, aliados que façam o mesmo podem receber esses benefícios.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Lin-Wu)', 1, 'Você recebe +2 em testes de perícia e na CD de suas habilidades contra criaturas treinadas em ao menos uma perícia desonrada (Enganação, Furtividade e Ladinagem) ou que possuam a habilidade Ataque Furtivo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Marah)', 1, 'Você é um conduíte para a beleza de Marah e recebe +1 em Carisma. Além disso, quando usa uma habilidade que cause uma condição entre enfeitiçado, fascinado ou pasmo, pode gastar 2 PM para fazer com que as criaturas afetadas rolem dois dados para seus testes de resistência e usem o pior resultado.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Megalokk)', 1, 'Você tem autoridade até mesmo sobre monstros irracionais. A atitude de qualquer monstro com Int –3 ou menor em relação a você aumenta em uma categoria. Se mesmo assim o monstro atacá-lo, você recebe +1 em testes de ataque e rolagens de dano contra ele.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Nimb)', 1, 'Essa conversa de autoridade não tem muito a ver com Nimb. Você está fora! Uma vez por dia, você pode conferir o status de autoridade de Nimb a outra criatura em alcance curto, que não seja devota do Deus do Caos. A vítima faz um teste de Vontade (CD Sab). Se ela passar, você fica confuso. Contudo, se ela falhar, fica sob efeito das Obrigações & Restrições de Nimb. Além disso, devotos do Deus do Caos procuram a vítima instintivamente, pedindo conselhos, infernizando sua vida e criando caos generalizado. Esse efeito dura um dia e, durante esse tempo, você fica livre das Obrigações & Restrições de Nimb. Conveniente, não?', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Oceano)', 1, 'Você tem autoridade sobre as águas. Seu deslocamento nadando é dobrado. Além disso, uma vez por dia, se estiver em uma extensão de água natural, como um mar, lago ou rio, pode gastar 1 PM para convocar um animal anfíbio ou aquático, um parceiro iniciante a sua escolha entre combatente, fortão ou guardião, que não conta no seu limite de parceiros. O animal o acompanha até o fim do dia.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Sszzaas)', 1, 'Você pode conduzir uma cerimônia especial com devotos do Deus da Traição. Você precisa de no mínimo 3 outros devotos para essa cerimônia, ela dura 1 hora e precisa ser realizada num local totalmente escondido (envolve cânticos profanos e exaltações a Sszzaas). Se fizer isso, para cada outro devoto na cerimônia seu total de PM aumenta em +1 até o fim da aventura e você recebe +1 em Enganação (ambos limitados pelo seu nível). O bônus em Enganação dura indefinidamente, mas diminui em 1 sempre que você fizer um teste dessa perícia.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Tanna-Toh)', 1, 'Você recebe +5 em Conhecimento e em testes de perícia para identificar criatura, item e magia (veja Misticismo em Tormenta20, p. 121). Além disso, se visitar um templo da Deusa do Conhecimento, tem acesso a todo o conteúdo de sua biblioteca. Escolha uma perícia em que não seja treinado. Até o fim da aventura, ou até usar esse benefício novamente, você recebe os benefícios de ser treinado na perícia escolhida.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Tenebra)', 1, 'Se estiver em um templo de Tenebra à noite, você pode conduzir uma cerimônia especial: Súplica à Deusa das Trevas. Isso é uma Missa (veja Tormenta20, p. 57), mas seus efeitos duram uma semana. Os participantes recebem redução de luz e fogo 5 e seus efeitos de trevas causam um dado extra de dano. À noite, esses benefícios são dobrados.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Thwor)', 1, 'Você recebe +5 em qualquer teste de perícias baseadas em Carisma feito para convencer alguém a ajudar a causa duyshidakk (o mestre tem a palavra final sobre as situações em que esse bônus se aplica). Além disso, se visitar um templo de Thwor ou um local qualquer em que haja um diagrama do Akzath como parte da arquitetura, você e quaisquer aliados a sua escolha podem escolher se colocar mais próximos a um lado do Akzath. Escolha entre +10 PV e +1 em testes de perícias, exceto ataques (Vida, Início, Continuidade...) ou +1 em testes de ataque e rolagens de dano (Morte, Fim, Mudança...). Esse benefício dura até o fim da aventura, ou até ser trocado.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Thyatis)', 1, 'Você recebe um ícone da fênix, um item esotérico especial que reduz o custo de magias de adivinhação e de fogo em –1 PM (cumulativo com outras reduções) e que conta como um símbolo sagrado de Thyatis. Se perder esse ícone, você pode receber outro visitando um templo do Deus da Ressurreição e da Profecia e fazendo uma doação de T$ 100.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Valkaria)', 1, 'Você pode permanecer por uma aventura inteira em um mesmo local, desde que haja um templo de Valkaria a no máximo um dia de distância. Além disso, ao visitar um templo de Valkaria, pode decretar que está em uma “demanda”, uma missão envolvendo viagens com um objetivo definido, como recuperar um tesouro ou capturar um vilão. Em uma demanda, você recebe +1 PV por nível e dormir ao relento conta como uma condição de descanso confortável para você, mas dormir sob um teto conta como condição ruim. Esse efeito dura até que a demanda seja cumprida. Se você abandonar a demanda, fica alquebrado até fazer uma penitência.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Autoridade Eclesiástica (Wynna)', 1, 'Você paga metade do preço por pergaminhos, poções e serviços em templos de Wynna. Além disso, se passar um dia meditando em um templo da Deusa da Magia, recebe uma fração de seu conhecimento místico. Escolha uma magia que você não conheça, arcana ou divina, de até 2º círculo. Até o fim da aventura, ou até usar esse benefício novamente, você pode lançar essa magia pagando seu custo normal.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Bênção de Batalha', 1, 'Bênção passa a afetar também você (em vez de apenas seus aliados). Além disso, na primeira rodada de combate, você pode lançar essa magia como ação de movimento (em vez de padrão).', true, '{"other":"Bênção"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Canalizar Energia Positiva/Negativa', 1, 'Você pode gastar uma ação padrão e PM para liberar uma onda de luz (se sua divindade canaliza energia positiva) ou trevas (se canaliza energia negativa) que afeta criaturas a sua escolha em alcance curto. Para cada PM que gastar, luz cura 1d6 PV em criaturas vivas e causa 1d6 pontos de dano de luz em mortos-vivos (Vontade CD Sab reduz o dano à metade). Trevas tem o efeito inverso — causa dano de trevas a criaturas vivas e cura mortos-vivos.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Canalizar Abençoado', 1, 'Quando você usa Canalizar Energia Positiva, pode gastar 1 PM. Se fizer isso, além do normal, as criaturas afetadas recebem 10 PV temporários.', true, '{"other":"Canalizar Energia Positiva, 11° nível de clérigo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Canalizar Amplo', 1, 'Quando você usa a habilidade Canalizar Energia, pode gastar +2 PM para aumentar o alcance dela para médio.', true, '{"other":"Canalizar Energia Positiva ou Negativa"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Canalizar Concentrado', 1, 'Quando usa Canalizar Energia, você pode afetar apenas uma criatura no alcance (em vez de todas). Se fizer isso, a cura ou o dano da habilidade aumenta em +1 por dado e a CD aumenta em +2.', true, '{"other":"Canalizar Energia, 11° nível de clérigo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Canalizar Profanado', 1, 'Quando você usa Canalizar Energia Negativa, pode gastar 1 PM. Se fizer isso, além do normal, criaturas que falhem na resistência não podem recuperar PV por 1 rodada.', true, '{"other":"Canalizar Energia Negativa, 11° nível de clérigo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Canalizar Poderoso', 1, 'Os dados de seu Canalizar Energia mudam para d10.', true, '{"other":"Canalizar Amplo, 9° nível de clérigo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Comunhão Vital', 1, 'Quando lança uma magia que cure uma criatura, você pode pagar +2 PM para que outra criatura em alcance curto (incluindo você mesmo) recupere uma quantidade de pontos de vida igual à metade dos PV da cura original. e', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Conhecimento Mágico', 1, 'Você aprende duas magias de qualquer círculo que possa lançar. Você pode escolher este poder quantas vezes quiser.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Conversão de Fé', 1, 'Uma vez por cena, você pode gastar uma ação completa e 3 PM para pregar sua fé a uma criatura inteligente (Int –3 ou maior) do tipo lacaio em alcance curto. Faça um teste de Religião oposto ao teste de Vontade da criatura (você recebe +5 no teste com devotos de seu deus, mas sofre –5 com devotos de outros deuses). Se você vencer, até o fim da cena a atitude da criatura se torna prestativa com relação a você e ela passa a atuar como um parceiro iniciante de um tipo à escolha do mestre, que não conta no seu limite de parceiros.', true, '{"other":"Autoridade Eclesiástica"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Dizimar Infiéis', 1, 'Se estiver usando uma arma afetada por Abençoar Arma, você pode gastar uma ação padrão e 2 PM para canalizar a punição divina! Faça um ataque corpo a corpo e compare o resultado com a Defesa de cada criatura em alcance curto. Então faça uma rolagem de dano e aplique-a em cada criatura atingida. Cada inimigo atingido fica ofuscado (se você canaliza energia positiva) ou vulnerável (se canaliza energia negativa) por 1 rodada.', true, '{"other":"Abençoar Arma, 5º nível de clérigo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Égide da Fé', 1, 'Quando você lança Escudo da Fé, a magia também fornece 5 PV temporários para cada +1 na Defesa. Esses PV temporários duram até o fim da cena.', true, '{"other":"Escudo da Fé"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Expulsar/Comandar Mortos-Vivos', 1, 'Você pode gastar uma ação padrão e 3 PM para expulsar (se sua divindade canaliza energia positiva) ou comandar (se canaliza energia negativa) todos os mortos-vivos em alcance curto. Mortos-vivos expulsos ficam apavorados por 1d6 rodadas. Mortos-vivos comandados não inteligentes (Int –4 ou menor) ficam sob suas ordens por um dia (até um limite de ND somados igual a seu nível +3; dar uma ordem a todos eles é uma ação de movimento) e mortos-vivos comandados inteligentes ficam fascinados por uma rodada. Mortos-vivos têm direito a um teste de Vontade (CD Sab) para evitar qualquer destes efeitos. Pré-requisito: Canalizar Energia Positiva ou Negativa. e', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Força da Devoção', 1, 'Quando você lança uma magia de clérigo, sua CD aumenta em +1 para cada dois poderes concedidos de sua divindade que você possui.', true, '{"other":"6º nível de clérigo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Liturgia Mágica', 1, 'Você pode gastar uma ação de movimento para executar uma breve liturgia de sua fé. Se fizer isso, a CD para resistir à sua próxima habilidade de clérigo (desde que usada até o final de seu próximo turno) aumenta em +2.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Liturgia Marcial', 1, 'Você pode gastar uma ação de movimento para executar uma breve liturgia de sua fé. Se fizer isso, você recebe +2 no teste de ataque e na rolagem de dano de seu próximo ataque corpo a corpo nesse turno.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Magia Sagrada/Profana', 1, 'Quando lança uma magia divina que causa dano, você pode gastar +1 PM. Se fizer isso, muda o tipo de dano da magia para luz (se sua divindade canaliza energia positiva) ou trevas (se canaliza energia negativa).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Mestre Celebrante', 1, 'O número de pessoas que você afeta com uma missa aumenta em dez vezes e os benefícios que elas recebem dobram. Abaixo detalhamos como isso se aplica.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Missas', 1, 'Alguns poderes do clérigo são Missas. Esses poderes compartilham as seguintes regras.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Missa: Bênção da Vida', 1, 'Os participantes recebem pontos de vida temporários em um valor igual ao seu nível + sua Sabedoria.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Missa: Chamado às Armas', 1, 'Os participantes recebem +1 em testes de ataque e rolagens de dano.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Missa: Compartilhar Milagre', 1, 'Escolha um dos seus poderes concedidos. Até o fim do dia, cada participante desta Missa pode usar esse poder durante 1 rodada, como se fosse devoto da sua divindade (os demais pré-requisitos do poder ainda devem ser cumpridos).', true, '{"other":"17° nível de clérigo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Missa: Elevação do Espírito', 1, 'Os participantes recebem pontos de mana temporários em um valor igual a sua Sabedoria.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Missa: Escudo Divino', 1, 'Os participantes recebem +1 na Defesa e testes de resistência.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Missa: Imposição da Vontade', 1, 'A CD para resistir às habilidades dos participantes aumenta em +1.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Missa: Mente Abençoada', 1, 'Os participantes recebem +2 em testes de perícias baseadas em Sabedoria.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Missa: Superar as Limitações', 1, 'Cada participante recebe +1d6 num único teste a sua escolha e pode usá-lo mesmo após rolar o dado.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Prece de Combate', 1, 'Quando lança uma magia divina com tempo de conjuração de uma ação padrão em si mesmo, você pode gastar +2 PM para lançá-la como uma ação de movimento.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Presente dos Deuses', 1, 'Você recebe uma arma superior e mágica, com duas melhorias e um encanto a sua escolha. Normalmente, será a arma preferida de seu deus, mas pode ser outra, de acordo com o mestre. A cada quatro níveis, a arma ganha mais uma melhoria e um encanto a sua escolha. Nas mãos de uma pessoa que não seja devota de sua divindade, a arma se comporta como um item mundano. Se a arma for perdida ou destruída, você pode receber outra fazendo uma penitência (como se tivesse descumprido as Obrigações & Restrições de sua divindade).', true, '{"other":"9º nível de clérigo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Punição Divina', 1, 'Uma vez por rodada, quando lança uma magia divina com tempo de execução de ação de movimento em si mesmo, você pode gastar +2 PM fazer um ataque como ação livre.', true, '{"other":"Prece de Combate"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Representante Divino', 1, 'Você fala com a autoridade de seu deus. Escolha uma magia divina que possa lançar com tempo de execução de ação padrão ou completa. Você pode lançar essa magia como uma ação de movimento, sem precisar gesticular ou se concentrar (mas ainda precisa falar).', true, '{"other":"17º nível de clérigo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Símbolo Sagrado Energizado', 1, 'Você pode gastar uma ação de movimento e 1 PM para fazer uma prece e energizar seu símbolo sagrado até o fim da cena. Um símbolo sagrado energizado emite uma luz dourada ou prateada (se sua divindade canaliza energia positiva) ou púrpura ou avermelhada (se canaliza energia negativa) que ilumina como uma tocha. Enquanto você estiver empunhando um símbolo sagrado energizado, o custo em PM para lançar suas magias divinas diminui em 1. e', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Solo Profanado', 1, 'Quando você lança uma magia de dano de trevas dentro de uma área de Profanar, criaturas que falhem no teste de resistência da magia não podem curar PV por um número de rodadas igual ao círculo da magia.', true, '{"other":"Profanar"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Solo Sagrado', 1, 'Quando você lança uma magia de luz dentro de uma área de Consagrar, criaturas a sua escolha nessa área recebem RD igual ao dobro do círculo da magia contra o próximo dano que sofrerem até o início do seu próximo turno.', true, '{"other":"Consagrar"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Mão da Divindade', 1, 'No 20º nível, você pode gastar uma ação completa e 15 PM para canalizar energia divina. Ao fazer isso, você lança três magias divinas quaisquer (de qualquer círculo, incluindo magias que você não conhece), como uma ação livre e sem gastar PM (mas ainda precisa pagar outros custos). Você pode aplicar aprimoramentos, mas precisa pagar por eles. Após usar esta habilidade, você fica atordoado por 1d4 rodadas (mesmo se for imune a esta condição). Corpos mortais não foram feitos para lidar com tanto poder.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Inimigo dos Deuses (Usurpador)', 1, 'Por roubar o poder de todos os deuses, o usurpador não é aceito por nenhum. Você não pode ter nenhuma devoção.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Magias (Usurpador)', 1, 'Você pode lançar magias divinas de 1º círculo. A cada quatro níveis, pode lançar magias de um círculo maior (2º círculo no 5º nível, 3º círculo no 9º nível e assim por diante). Você não começa com nenhuma magia e não aprende magias automaticamente como um clérigo faria (mas veja Usurpar, a seguir). Seu atributo-chave para lançar magias é Carisma e você soma seu Carisma no seu total de PM.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Usurpar (Usurpador)', 1, 'Você pode lançar qualquer magia divina de um círculo a que tenha acesso. Para lançar uma magia dessa forma, deve passar em um teste de Enganação (CD 15 + custo em PM da magia). Se falhar, a magia é perdida, mas os PM são gastos mesmo assim. Você não pode escolher 10 nesse teste, mesmo que possua uma habilidade que permita isso, e sofre penalidade de armadura nele. Além disso, sofre uma penalidade de –5 se estiver em um local contendo um símbolo sagrado visível.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Canalização Falsa (Usurpador)', 1, 'No 2º nível, você pode canalizar tanto energia positiva quanto negativa.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Discrição Divina (Usurpador)', 1, 'No 3º nível, você recebe +1 em Furtividade e testes de resistência. A cada seis níveis, esse bônus aumenta em +1.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Poder Capturado (Usurpador)', 1, 'No 4º nível, você rouba o poder que os deuses concedem a seus devotos. Escolha um deus maior por nível e um poder concedido desse deus (você deve cumprir seus pré-requisitos e não pode escolher poderes exclusivos de qualquer classe, inclusive clérigo). Você pode gastar uma hora e fazer um teste de Enganação (CD é 20 +5 para cada uso adicional no mesmo dia). Se passar, você é considerado um devoto desse deus para efeitos de habilidades e itens, e pode usar o poder concedido escolhido, mas não precisa seguir as Obrigações e Restrições. Se falhar, você perde 3 PM. Este efeito dura até o fim do dia ou até você usá-lo novamente.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Clérigo', 'Roubo Divino (Usurpador)', 1, 'No 20º nível, você é capaz de roubar a própria essência divina. Quando lança uma magia com Usurpar, para cada 10 pontos no resultado do teste de Enganação, o total de PM que você gasta nessa magia é reduzido em –1 (cumulativo com outras reduções) e a CD para resistir a ela aumenta em +1.', false, NULL);
INSERT INTO classes (name, publication, hit_points, mana_points, skills, proficiencies) VALUES ('Complicações', 'Tormenta20', 'undefined+CON', 'undefined por nível', '[]'::jsonb, '[]'::jsonb);
INSERT INTO classes (name, publication, hit_points, mana_points, skills, proficiencies) VALUES ('Druida', 'Tormenta20', '16+CON', '4 por nível', '["Sobrevivência","Vontade","Adestramento","Atletismo","Cavalgar","Conhecimento","Cura","Fortitude","Iniciativa","Intuição","Luta","Misticismo","Ofício","Percepção","Religião"]'::jsonb, '["Escudos"]'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Devoto Fiel', 1, 'Você se torna devoto de um deus disponível para druidas (Allihanna, Megalokk ou Oceano). Veja as regras de devotos na página 96. Ao contrário de devotos normais, você recebe dois poderes concedidos por se tornar devoto, em vez de apenas um.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Empatia Selvagem', 1, 'Você pode se comunicar com animais por meio de linguagem corporal e vocalizações. Você pode usar Adestramento com animais para mudar atitude e persuasão (veja a página 118).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Magias', 1, 'Escolha três escolas de magia. Uma vez feita, essa escolha não pode ser mudada. Você pode lançar magias divinas de 1º círculo que pertençam a essas escolas. À medida que sobe de nível, pode lançar magias de círculos maiores (2º círculo no 6º nível, 3º círculo no 10º nível e 4º círculo no 14º nível). Você começa com duas magias de 1º círculo. A cada nível par (2º, 4º etc.), aprende uma magia de qualquer círculo e escola que possa lançar. Seu atributo-chave para lançar magias é Sabedoria e você soma sua Sabedoria no seu total de PM. Veja o Capítulo 4 para as regras de magia.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Arma Tradicional', 1, 'Quando faz um ataque com uma foice, você pode gastar 2 PM para lançar uma magia de ácido, eletricidade, fogo ou frio com execução de movimento, padrão ou completa como ação livre. Considere que a mão da arma está livre para lançar essa magia.', true, '{"other":"druida de Arton, 5º nível de druida"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Aspecto do Inverno', 1, 'Você aprende e pode lançar uma magia de convocação ou evocação, arcana ou divina, de qualquer círculo que possa lançar. Além disso, recebe redução de frio 5 e suas magias que causam dano de frio causam +1 ponto de dano por dado.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Aspecto do Outono', 1, 'Você aprende e pode lançar uma magia de necromancia, arcana ou divina, de qualquer círculo que possa lançar. Além disso, pode gastar 1 PM para impor uma penalidade de –2 nos testes de resistência de todos os inimigos em alcance curto até o início do seu próximo turno.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Aspecto da Primavera', 1, 'Você aprende e pode lançar uma magia de encantamento ou ilusão, arcana ou divina, de qualquer círculo que possa lançar. Além disso, escolha uma quantidade de magias igual ao seu Carisma (mínimo 1). O custo dessas magias é reduzido em −1 PM.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Aspecto do Verão', 1, 'Você aprende e pode lançar uma magia de transmutação, arcana ou divina, de qualquer círculo que possa lançar. Além disso, pode gastar 1 PM para cobrir uma de suas armas com chamas até o fim da cena. A arma causa +1d6 pontos de dano de fogo. Sempre que você acertar um ataque com ela em combate, recebe 1 PM temporário. Você pode ganhar um máximo de PM temporários por cena igual ao seu nível e eles desaparecem no fim da cena.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Aumento de Atributo', 1, 'Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Auspício do Crepúsculo', 1, 'Você pode gastar 1 PM para cobrir uma de suas armas com sombras até o fim da cena. A arma causa +1d6 pontos de dano de trevas. Se você estiver sob efeito de escuridão, sempre que acertar um ataque com ela em combate, recebe 5 PV temporários cumulativos.', true, '{"other":"druida de Tenebra"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Auspício da Madrugada', 1, 'Você pode gastar 1 PM para impor uma penalidade de –1 em testes de perícia e na CD de habilidades de criaturas a sua escolha em alcance curto por 1 rodada. Se você estiver sob efeito de escuridão, a penalidade se torna –2.', true, '{"other":"druida de Tenebra"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Auspício da Meia-Noite', 1, 'Você pode gastar uma ação de movimento e 2 PM para aumentar a CD das suas habilidades de druida em +1 até o fim da cena. Se você usar este poder sob efeito de escuridão, o bônus na CD se torna +2.', true, '{"other":"druida de Tenebra"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Banquete Selvagem', 1, 'Se você estiver em forma selvagem e gastar uma ação padrão para devorar um pedaço de uma criatura inconsciente que esteja com 0 PV ou menos (exceto construtos e seres incorpóreos), recebe +2 em Força, +5 em Intimidação e 2 PV temporários por nível até o fim da cena. Se a criatura é do tipo lacaio, ela morre.', true, '{"other":"druida de Megalokk, Forma Selvagem"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Ciclo da Vida', 1, 'Uma vez por cena, você pode gastar uma ação padrão para fazer um cadáver em alcance curto se decompor instantaneamente. Se fizer isso, você recebe +2 pontos de mana por ND que a criatura tinha em vida. Esses PM adicionais duram até o fim do dia.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Companheiro Aberrante', 1, 'Escolha um de seus companheiros animais. Ele recebe o tipo aberrante, ganhando os bônus de seu nível. Um parceiro aberrante fornece os benefícios a seguir. Iniciante: uma vez por rodada, você pode gastar 1 PM para disparar um pulso mental contra uma criatura em alcance curto; ela sofre 2d6 pontos de dano psíquico ou perde 1d4 PM, a sua escolha. Veterano: você também pode gastar 2 PM para causar 4d6 pontos de dano ou fazer a criatura perder 2d4 PM. Mestre: você também pode gastar 4 PM para causar 6d6 pontos de dano ou fazer a criatura perder 3d4 PM.', true, '{"other":"druida de Aharadak, Companheiro Animal, 6º nível de druida"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Companheiro Animal Detalhes', 1, 'Um companheiro animal é um amigo valoroso e fiel. Você decide de qual espécie é seu companheiro. Vocês têm um vínculo mental, sendo capazes de entender um ao outro. Seu companheiro animal obedece a você, mesmo que isso arrisque a vida dele. Em termos de jogo, seu companheiro animal é um parceiro ajudante, assassino, atirador, combatente, fortão, guardião, perseguidor, ou uma montaria, do nível iniciante. No 7º nível ele muda para veterano e, no 15º nível, para mestre (se tiver mais de um tipo, todos mudam de nível). Se o companheiro animal morrer, você fica atordoado por uma rodada. Você pode invocar um novo companheiro após um dia inteiro de prece e meditação. A seguir, alguns exemplos de animais (mas você é livre para escolher outros). Veja a página 260 para as regras de parceiros.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Companheiro Animal', 1, 'Você recebe um companheiro animal. Veja o quadro para detalhes. Você pode escolher este poder quantas vezes quiser, mas deve escolher companheiros diferentes e ainda está sujeito ao limite de parceiros que pode ter (veja a página 260).', true, '{"other":"Car 1, treinado em Adestramento"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Companheiro Animal Aprimorado', 1, 'Escolha um de seus companheiros animais. Ele recebe um segundo tipo, ganhando os bônus de seu nível. Por exemplo, se você tiver um companheiro guardião veterano, pode adicionar o tipo fortão a ele, tornando-o um guardião fortão veterano que concede +3 na Defesa e +1d12 em uma rolagem de dano corpo a corpo.', true, '{"other":"Companheiro Animal, 6º nível de druida"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Companheiro Animal Lendário', 1, 'Escolha um de seus companheiros animais. Esse animal passa a dobrar os bônus concedidos de seu tipo original.', true, '{"other":"Companheiro Animal, 18º nível de druida"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Companheiro Animal Mágico', 1, 'Escolha um de seus companheiros animais. Ele recebe um segundo tipo diferente, entre adepto, destruidor, magivocador ou médico, ganhando os bônus de seu nível.', true, '{"other":"Companheiro Animal, 8º nível de druida"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Companheiro Elemental', 1, 'Escolha um de seus companheiros animais. Ele recebe o tipo destruidor, ganhando os bônus de seu nível. Se você possuir o suplemento Ameaças de Arton, em vez disso ele pode se tornar também um parceiro aquin’ne, t’peel, pakk ou terrier (também ganhando o bônus de seu nível).', true, '{"other":"druida de Arton, Companheiro Animal"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Coração da Selva', 1, 'A CD para resistir a seus efeitos de veneno aumenta em +2 e estes efeitos causam +1 de perda de vida por dado.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Erupção Elemental', 1, 'Se você estiver em forma elemental, pode gastar uma ação de movimento e 2 PM. Se fizer isso, seu próximo ataque com uma arma natural realizado nessa cena afeta todas as criaturas em um cone de 6m (faça um único ataque corpo a corpo e compare o resultado com a Defesa de cada criatura na área) e causa dois dados de dano extras.', true, '{"other":"Forma Elemental"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Espírito dos Equinócios', 1, 'Você pode gastar 4 PM para ficar em equilíbrio com o mundo. Até o final da cena, quando rola um dado, pode rolar novamente qualquer resultado 1. Pré-requisitos: Aspecto da Primavera, Aspecto do Outono, 10º nível de druida. e', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Espírito dos Solstícios', 1, 'Você transita entre os extremos do mundo natural. Quando lança uma magia, pode gastar +4 PM para maximizar os efeitos numéricos variáveis dela. Por exemplo, uma magia Curar Ferimentos aprimorada para curar 5d8+5 PV irá curar automaticamente 45 PV, sem a necessidade de rolar dados. Uma magia sem efeitos variáveis não pode ser afetada por este poder.', true, '{"other":"Aspecto do Inverno, Aspecto do Verão, 10º nível de druida"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Força da Natureza', 1, 'Se estiver em forma selvagem, você pode gastar 4 PM para se cobrir de terra e raízes, como um elemental da própria terra, até o fim da cena. Nesse estado, você recebe +4 em um atributo a sua escolha.', true, '{"other":"Forma Selvagem Superior, 17º nível de druida"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Força dos Penhascos', 1, 'Você recebe +2 em Fortitude. Quando sofre dano enquanto em contato com o solo ou uma superfície de pedra, pode gastar uma quantidade de PM limitada por sua Sabedoria. Para cada PM gasto, reduz esse dano em 10.', true, '{"other":"4º nível de druida"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Forma Aberrante', 1, 'Quando usa Forma Selvagem, você pode gastar +2 PM para assumir uma forma aberrante. Nessa forma, você conta como se tivesse dois poderes da Tormenta adicionais (exceto para perda de Carisma).', true, '{"other":"druida de Aharadak, Forma Selvagem"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Forma de Cardume', 1, 'Quando usa Forma Selvagem, você pode gastar +1 PM para assumir a forma de um cardume de criaturas anfíbias com duração sustentada. Você recebe imunidade a manobras de combate, sofre apenas metade do dano de armas, pode entrar nos espaços ocupados por inimigos e criaturas no mesmo espaço que você ficam em condição ruim para lançar magias.', true, '{"other":"druida de Oceano, Forma Selvagem"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Forma Elemental', 1, 'Quando usa Forma Selvagem, você pode gastar +2 PM para assumir uma forma elemental. Escolha entre ácido, eletricidade, fogo ou frio. Você recebe imunidade ao tipo de dano escolhido e vulnerabilidade ao tipo oposto. Além disso, o alcance de suas armas naturais aumenta em +1,5m e elas causam dano do tipo escolhido (em vez de seu dano normal).', true, '{"other":"druida de Arton, Forma Selvagem"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Forma Esquelética', 1, 'Quando usa Forma Selvagem, você pode gastar +2 PM para assumir uma forma esquelética. Seu tipo muda para morto-vivo e você recebe redução de corte, frio e perfuração 5 e imunidade a efeitos de cansaço, metabólicos e de veneno. Por fim, você sofre dano por efeitos mágicos de cura de luz (Vontade CD do efeito reduz à metade) e recupera PV com dano de trevas.', true, '{"other":"druida de Tenebra, Forma Selvagem"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Forma Primal', 1, 'Quando usa Forma Selvagem, você pode se transformar em uma fera primal. Você recebe os benefícios de dois tipos de animais (bônus iguais não se acumulam; use o que você quiser de cada tipo).', true, '{"other":"18º nível de druida"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Forma Selvagem', 1, 'Você pode se transformar em animais (veja a seguir).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Forma Vegetal', 1, 'Quando usa Forma Selvagem, você pode gastar +2 PM para assumir uma forma vegetal. Você recebe RD 5/corte ou fogo e Natureza Vegetal (fica imune a atordoamento e metamorfose, mas é afetado por efeitos que afetem plantas monstruosas — se o efeito não tiver um teste de resistência, você tem direito a um teste de Fortitude).', true, '{"other":"druida de Allihanna, Forma Selvagem"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Forma Selvagem Aprimorada', 1, 'Quando usa Forma Selvagem, você pode gastar 6 PM ao todo para assumir uma forma aprimorada.', true, '{"other":"Forma Selvagem, 6º nível de druida"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Forma Selvagem Superior', 1, 'Quando usa Forma Selvagem, você pode gastar 10 PM ao todo para assumir uma forma superior.', true, '{"other":"Forma Selvagem Aprimorada, 12º nível de druida"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Instinto Venenoso', 1, 'Você pode usar Sab como atributo-chave de venenos (em vez de Int). Além disso, em Forma Selvagem, pode aplicar venenos de contato em suas armas naturais como ação livre.', true, '{"other":"Coração da Selva"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Liberdade da Pradaria', 1, 'Você recebe +2 em Reflexos. Se estiver ao ar livre, sempre que lança uma magia, pode gastar 1 PM para aumentar o alcance dela em um passo (de toque para curto, de curto para médio ou de médio para longo).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Magia Natural', 1, 'Em forma selvagem, você pode lançar magias e empunhar catalisadores e esotéricos.', true, '{"other":"Forma Selvagem"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Metamorfose Instantânea', 1, 'Uma vez por rodada, quando usa Forma Selvagem, você pode gastar +2 PM para usar essa habilidade como ação livre.', true, '{"other":"Forma Selvagem, 11º nível de druida"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Oráculo da Natureza', 1, 'Você pode gastar uma ação de movimento para se conectar com as energias naturais do mundo. Enquanto você permanecer no mesmo lugar, a CD para resistir a suas magias aumenta em +2 e, sempre que você lança uma magia, recebe 2 PM para gastar em aprimoramentos. Se você estiver em um ambiente urbano, a ação necessária para usar este poder muda para completa.', true, '{"other":"Xamã Místico, 11º nível de druida"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Orador dos Elementos', 1, 'Você aprende e pode lançar uma magia de dano de ácido, eletricidade, fogo ou frio, arcana ou divina, de qualquer círculo que possa lançar. Além disso, você pode aprender magias arcanas de ácido, eletricidade, fogo ou frio como se fossem divinas.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Presas Afiadas', 1, 'A margem de ameaça de suas armas naturais aumenta em +2.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Proteção Fúngica', 1, 'Você pode gastar 1 PM para cobrir seu corpo de esporos com duração sustentada. Nesse estado, sempre que você sofrer um ataque corpo a corpo de uma criatura adjacente, ela perde 1d8 PV. A cada quatro níveis acima do 1º, você pode gastar +1 PM quando usa este poder para aumentar a perda de vida em +1d8. Veneno.', true, '{"other":"Coração da Selva"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Segredos da Natureza', 1, 'Você aprende duas magias de qualquer círculo que possa lançar. Elas devem pertencer às escolas que você sabe usar, mas podem ser arcanas ou divinas. Você pode escolher este poder quantas vezes quiser.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Tranquilidade dos Lagos', 1, 'Você recebe +2 em Vontade. Se estiver portando um recipiente com água (não precisa estar empunhando), uma vez por rodada, quando faz um teste de resistência, pode pagar 1 PM para refazer a rolagem.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Transformação Repugnante', 1, 'Quando usa Forma Selvagem, você pode gastar +2 PM. Se fizer isso, inimigos em alcance curto sofrem 1d6 pontos de dano psíquico para cada poder da Tormenta que você possui e ficam alquebrados e frustrados (Vontade CD Sab reduz à metade e evita as condições).', true, '{"other":"Forma Aberrante"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Xamã Místico', 1, 'Você recebe +1 PM por nível de druida, pode aprender e lançar magias de uma escola adicional e a CD para resistir a suas magias aumenta em +1. Prérequisito: não possuir Forma Selvagem.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Caminho dos Ermos', 1, 'No 2º nível, você pode atravessar terrenos difíceis sem sofrer redução em seu deslocamento e a CD para rastreá-lo aumenta em +10. Esta habilidade só funciona em terrenos naturais.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Força da Natureza', 1, 'No 20º nível, você diminui o custo de todas as suas magias em –2 PM e aumenta a CD delas em +2. Os bônus dobram (–4 PM e +4 na CD) se você estiver em terrenos naturais.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Empatia Selvagem (Ermitão)', 1, 'Você pode se comunicar com animais, com criaturas vegetais não inteligentes (Int –4 ou –5) e espíritos por meio de linguagem corporal e vocalizações. Você pode usar Adestramento com animais para mudar atitude e persuasão (veja a página 118).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Sítio Sagrado (Ermitão)', 1, 'No 3º nível, você assume um local sagrado para sua divindade (veja o quadro).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'O Sítio Sagrado (Ermitão)', 1, 'Uma área erma com 5 km de raio, o sítio sagrado é um refúgio para o ermitão e fornece diversas habilidades a ele, algumas das quais o acompanham para além das fronteiras deste local. Caso o sítio sagrado seja destruído, você perde todos os seus PM e só pode recuperá-los ao criar um novo sítio. Fazer isso ocupa um tempo entre aventuras.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Vínculo com a Terra (Ermitão)', 1, 'No 5º nível, quando você estiver em um terreno de um dos tipos de seu sítio sagrado, suas magias custam –1 PM (cumulativo com outras reduções).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Temperado pelo Clima (Ermitão)', 1, 'No 11º nível, você recebe RD 5 contra dano dos tipos correspondentes aos terrenos associados ao seu sítio sagrado: aquático (eletricidade), ártico (frio), colina (impacto), deserto (fogo), floresta (corte), montanha (perfuração), pântano (ácido), planície (luz) e subterrâneo (trevas).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Eixo de Pedras (Ermitão)', 1, 'No 20º nível, você cria um eixo de pedras ritualísticas em seu sítio sagrado. Uma vez por aventura, você pode lançar no eixo de pedras uma quantidade de magias cujo custo em PM total somado seja igual ao seu nível + sua Sabedoria. Essas magias devem ter execução de movimento, padrão ou completa. Até o fim da aventura, se estiver em um terreno de um dos tipos associados ao seu sítio sagrado, uma vez por rodada você pode descarregar uma dessas magias como ação livre sem pagar seu custo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Forma Selvagem', 1, 'Você pode gastar uma ação completa e 3 PM para adquirir a forma de uma criatura selvagem. Em termos de jogo, quando usa esta habilidade você adquire os modificadores de uma das formas abaixo. Se ganhar uma arma natural, escolha seu tipo de dano entre corte, impacto e perfuração. Características não mencionadas não mudam. Na forma selvagem você não pode falar, empunhar itens ou lançar magias. Seu equipamento desaparece (mas você mantém os benefícios de quaisquer itens vestidos), ressurgindo quando você volta ao normal. Outras criaturas podem fazer um teste de Percepção oposto pelo seu teste de Enganação para perceber que você não é um animal comum (você recebe +10 neste teste). Cada transformação dura pelo tempo que você quiser, mas você reverte à forma normal se ficar inconsciente ou morrer.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Forma Ágil', 1, 'Você recebe Destreza +2 e duas armas naturais que causam 1d6 pontos de dano e possuem margem de ameaça 19. Quando usa a ação agredir, pode atacar com ambas, mas sofre –2 em todos os testes de ataque até o seu próximo turno.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Forma Feroz', 1, 'Você recebe Força +3, +2 na Defesa e uma arma natural que causa 1d8 pontos de dano.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Forma Resistente', 1, 'Você recebe +5 na Defesa, redução de dano 5 e uma arma natural que causa 1d6 pontos de dano.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Forma Sorrateira', 1, 'Você recebe Destreza +2 e uma arma natural que causa 1d4 pontos de dano. Seu tamanho muda para Pequeno (+2 em Furtividade, –2 em testes de manobra).
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Druida', 'Forma Veloz', 1, 'Você recebe Destreza +2, uma arma natural que causa 1d6 pontos de dano e um dos benefícios a seguir: deslocamento 15m, deslocamento de escalada 9m ou deslocamento de natação 9m.
INSERT INTO classes (name, publication, hit_points, mana_points, skills, proficiencies) VALUES ('Frade', 'Tormenta20', '12+CON', '6 por nível', '["Religião","Vontade","Adestramento","Atuação","Conhecimento","Cura","Diplomacia","Fortitude","Guerra","Iniciativa","Intimidação","Intuição","Investigação","Misticismo","Ofício","Percepção","Nobreza"]'::jsonb, '[]'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Devoto Fiel', 1, 'Você se torna devoto de um deus maior. Veja as regras de devotos em Tormenta20, p. 96. Ao contrário de devotos normais, você recebe dois poderes concedidos por se tornar devoto, em vez de apenas um. Como alternativa, você pode cultuar o Panteão como um todo. Não recebe nenhum Poder Concedido, mas sua única obrigação e restrição é não usar armas cortantes ou perfurantes (porque derramam sangue, algo que frades do Panteão consideram proibido). Sua arma preferida é a maça e você pode canalizar energia positiva ou negativa a sua escolha (uma vez feita, essa escolha não pode ser mudada). Cultuar o Panteão conta como sua devoção.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Erudição', 1, 'Quando faz um teste de perícia (exceto de ataque), você pode gastar uma quantidade de PM a sua escolha (limitada pela sua Inteligência). Para cada PM que gastar, recebe +2 no teste.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Magias', 1, 'Você pode lançar magias divinas de 1º círculo. A cada quatro níveis, pode lançar magias de um círculo maior (2º círculo no 5º nível, 3º círculo no 9º nível e assim por diante). Você começa com três magias de 1º círculo. A cada nível, aprende uma magia de qualquer círculo que possa lançar. Você pode lançar essas magias vestindo armaduras leves mas, se estiver usando armadura pesada, precisará fazer um teste de Misticismo como se fosse um conjurador arcano (veja “Armaduras e Magia Arcana”, em Tormenta20, p. 171). Seu atributo-chave para lançar magias é Sabedoria e você soma sua Sabedoria no seu total de PM. Veja o Capítulo 4 de Tormenta20 para as regras de magia.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Versiculário', 1, 'No 2º nível, você recebe um versiculário, um livro de anotações religiosas pessoais. Uma vez por dia, você pode gastar 1 hora estudando suas anotações no versiculário. Quando faz isso, escolha uma quantidade de magias igual à sua Inteligência (limitada pelo seu nível). Até o próximo dia, quando lança uma dessas magias, você recebe +1 PM para gastar em aprimoramentos. Se perder seu versiculário, você pode escrever outro com 1 semana de trabalho e o gasto de T$ 100.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Acelerar Sacrário', 1, 'Quando cria um sacrário, você pode gastar +2 PM para criá-lo como uma ação de movimento (em vez de uma ação padrão).', true, '{"other":"5º nível de frade"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Ampliar Sacrário', 1, 'Você pode criar sacrários em alcance médio e eles passam a ocupar uma esfera de 6m de raio.', true, '{"other":"10º nível de frade"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Aumento de Atributo', 1, 'Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Básico)', 1, 'Você possui uma posição formal em uma igreja reconhecida pelos outros membros de sua fé. Os efeitos deste poder variam de acordo com a igreja e o deus — clérigos de Khalmyr, por exemplo, possuem autoridade como juízes no Reinado — e ficam a cargo do mestre. Como regra geral, você recebe +5 em testes de Diplomacia ou Intimidação ao lidar com devotos de sua divindade e paga metade do preço de itens alquímicos, poções e serviços em templos de sua divindade.', true, '{"other":"5º nível de clérigo, devoto de um deus maior"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Deuses)', 1, 'Você possui uma posição formal e reconhecida em uma igreja. Você recebe +5 em testes de Diplomacia e Intimidação ao lidar com devotos de sua divindade, além do benefício específico de sua divindade.', true, '{"other":"5º nível de clérigo ou frade, devoto de um deus maior"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Aharadak)', 1, 'Você aprende e pode lançar Sussurros Insanos (Tormenta20, p. 207) como uma magia divina. Além disso, se estiver em um templo de Aharadak, ou com pelo menos 5 outros devotos do Deus da Tormenta, pode gastar 1 hora para executar um ritual que o aproxima da Anticriação. Se fizer isso, você recebe um embrião rubro, uma larva que se aloja em seu corpo e ocupa 1 espaço. Até o fim da aventura, ou até executar esse ritual novamente, você pode despertar essa larva para receber 1 poder da Tormenta a sua escolha, cujos pré-requisitos cumpra, até o fim da cena. Ao fim da cena, a larva se desaloja e cai no chão como uma pequena poça de visco rubro.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Allihanna)', 1, 'Você recebe +5 em Adestramento e Cavalgar, e pode usar essas perícias com animais mesmo sem ser treinado. Além disso, quando descansa em terreno natural, recebe uma bênção dos espíritos locais. Para cada patamar, você recebe 1d4 de auxílio que pode ser adicionado como um bônus em um teste de perícia feito até o fim do dia.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Arsenal)', 1, 'Quando visita um templo do Deus da Guerra, você pode orar para que ele abençoe seu… arsenal. Escolha uma arma, armadura ou escudo; o item recebe uma melhoria a sua escolha (exceto material especial) cujos pré-requisitos ele cumpra. Essa melhoria não conta no limite de melhorias do item. Se tiver o poder Conjurar Arma, você pode aplicar esse benefício às armas ou munições conjuradas com ele. Esses efeitos duram até o fim da aventura ou até você orar por outra melhoria.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Azgher)', 1, 'Você recebe +5 em Sobrevivência. Além disso, uma vez por aventura, se visitar um templo de Azgher, você pode medir o peso de sua alma. Faça um teste de Religião com CD definida pelo mestre: 15 se você seguiu os preceitos de Azgher à risca durante o último mês; 20 se seguiu-os, mas não perfeitamente; 25 se quebrou suas Obrigações & Restrições. Você recebe 1 TO por patamar para cada ponto do resultado acima da CD.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Hyninn)', 1, 'Quando chega a uma comunidade, você pode fazer um teste de Sabedoria (CD 10). Se passar, faz contato com ladrões locais; até partir desse lugar, você recebe +5 em testes de Diplomacia para barganha e de Investigação para interrogar. Além disso, uma vez durante sua estadia pode ganhar a ajuda de um parceiro veterano de um tipo a sua escolha entre ajudante (Enganação, Furtividade e Ladinagem), assassino, fortão, perseguidor ou vigilante, que não conta em seu limite de parceiros.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Kallyadranoch)', 1, 'Você recebe +5 em Intimidação. Além disso, se visitar um templo de Kallyadranoch, você recebe uma fração da energia dominante do Deus dos Dragões. Durante uma cena a sua escolha, sempre que aplicar uma condição de medo em um ou mais inimigos, você recupera 1d4 PM.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Khalmyr)', 1, 'Você recebe +5 em testes de Diplomacia e Intimidação com agentes da lei (cavaleiros, paladinos, guardas e outros, a critério do mestre). Além disso, uma vez por aventura, se estiver em um templo de Khalmyr, você pode solicitar uma escolta: até dois parceiros iniciantes, cada um de um tipo a sua escolha entre combatente, guardião ou médico. Eles o acompanham até o fim da aventura.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Lena)', 1, 'Você recebe o poder Aparência Inofensiva (se já possuí-lo, a CD para resistir a ele aumenta em +2). Além disso, quando passa um dia descansando em um templo da Deusa da Vida, recebe +1 em testes de resistência e +1 PV por nível até o fim da aventura. A seu critério, aliados que façam o mesmo podem receber esses benefícios.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Lin-Wu)', 1, 'Você recebe +2 em testes de perícia e na CD de suas habilidades contra criaturas treinadas em ao menos uma perícia desonrada (Enganação, Furtividade e Ladinagem) ou que possuam a habilidade Ataque Furtivo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Marah)', 1, 'Você é um conduíte para a beleza de Marah e recebe +1 em Carisma. Além disso, quando usa uma habilidade que cause uma condição entre enfeitiçado, fascinado ou pasmo, pode gastar 2 PM para fazer com que as criaturas afetadas rolem dois dados para seus testes de resistência e usem o pior resultado.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Megalokk)', 1, 'Você tem autoridade até mesmo sobre monstros irracionais. A atitude de qualquer monstro com Int –3 ou menor em relação a você aumenta em uma categoria. Se mesmo assim o monstro atacá-lo, você recebe +1 em testes de ataque e rolagens de dano contra ele.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Nimb)', 1, 'Essa conversa de autoridade não tem muito a ver com Nimb. Você está fora! Uma vez por dia, você pode conferir o status de autoridade de Nimb a outra criatura em alcance curto, que não seja devota do Deus do Caos. A vítima faz um teste de Vontade (CD Sab). Se ela passar, você fica confuso. Contudo, se ela falhar, fica sob efeito das Obrigações & Restrições de Nimb. Além disso, devotos do Deus do Caos procuram a vítima instintivamente, pedindo conselhos, infernizando sua vida e criando caos generalizado. Esse efeito dura um dia e, durante esse tempo, você fica livre das Obrigações & Restrições de Nimb. Conveniente, não?', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Oceano)', 1, 'Você tem autoridade sobre as águas. Seu deslocamento nadando é dobrado. Além disso, uma vez por dia, se estiver em uma extensão de água natural, como um mar, lago ou rio, pode gastar 1 PM para convocar um animal anfíbio ou aquático, um parceiro iniciante a sua escolha entre combatente, fortão ou guardião, que não conta no seu limite de parceiros. O animal o acompanha até o fim do dia.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Sszzaas)', 1, 'Você pode conduzir uma cerimônia especial com devotos do Deus da Traição. Você precisa de no mínimo 3 outros devotos para essa cerimônia, ela dura 1 hora e precisa ser realizada num local totalmente escondido (envolve cânticos profanos e exaltações a Sszzaas). Se fizer isso, para cada outro devoto na cerimônia seu total de PM aumenta em +1 até o fim da aventura e você recebe +1 em Enganação (ambos limitados pelo seu nível). O bônus em Enganação dura indefinidamente, mas diminui em 1 sempre que você fizer um teste dessa perícia.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Tanna-Toh)', 1, 'Você recebe +5 em Conhecimento e em testes de perícia para identificar criatura, item e magia (veja Misticismo em Tormenta20, p. 121). Além disso, se visitar um templo da Deusa do Conhecimento, tem acesso a todo o conteúdo de sua biblioteca. Escolha uma perícia em que não seja treinado. Até o fim da aventura, ou até usar esse benefício novamente, você recebe os benefícios de ser treinado na perícia escolhida.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Tenebra)', 1, 'Se estiver em um templo de Tenebra à noite, você pode conduzir uma cerimônia especial: Súplica à Deusa das Trevas. Isso é uma Missa (veja Tormenta20, p. 57), mas seus efeitos duram uma semana. Os participantes recebem redução de luz e fogo 5 e seus efeitos de trevas causam um dado extra de dano. À noite, esses benefícios são dobrados.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Thwor)', 1, 'Você recebe +5 em qualquer teste de perícias baseadas em Carisma feito para convencer alguém a ajudar a causa duyshidakk (o mestre tem a palavra final sobre as situações em que esse bônus se aplica). Além disso, se visitar um templo de Thwor ou um local qualquer em que haja um diagrama do Akzath como parte da arquitetura, você e quaisquer aliados a sua escolha podem escolher se colocar mais próximos a um lado do Akzath. Escolha entre +10 PV e +1 em testes de perícias, exceto ataques (Vida, Início, Continuidade...) ou +1 em testes de ataque e rolagens de dano (Morte, Fim, Mudança...). Esse benefício dura até o fim da aventura, ou até ser trocado.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Thyatis)', 1, 'Você recebe um ícone da fênix, um item esotérico especial que reduz o custo de magias de adivinhação e de fogo em –1 PM (cumulativo com outras reduções) e que conta como um símbolo sagrado de Thyatis. Se perder esse ícone, você pode receber outro visitando um templo do Deus da Ressurreição e da Profecia e fazendo uma doação de T$ 100.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Valkaria)', 1, 'Você pode permanecer por uma aventura inteira em um mesmo local, desde que haja um templo de Valkaria a no máximo um dia de distância. Além disso, ao visitar um templo de Valkaria, pode decretar que está em uma “demanda”, uma missão envolvendo viagens com um objetivo definido, como recuperar um tesouro ou capturar um vilão. Em uma demanda, você recebe +1 PV por nível e dormir ao relento conta como uma condição de descanso confortável para você, mas dormir sob um teto conta como condição ruim. Esse efeito dura até que a demanda seja cumprida. Se você abandonar a demanda, fica alquebrado até fazer uma penitência.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Autoridade Eclesiástica (Wynna)', 1, 'Você paga metade do preço por pergaminhos, poções e serviços em templos de Wynna. Além disso, se passar um dia meditando em um templo da Deusa da Magia, recebe uma fração de seu conhecimento místico. Escolha uma magia que você não conheça, arcana ou divina, de até 2º círculo. Até o fim da aventura, ou até usar esse benefício novamente, você pode lançar essa magia pagando seu custo normal.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Bênção Fortalecedora', 1, 'Quando você lança Bênção, os aliados abençoados recebem uma quantidade de PV temporários igual a 5 vezes o bônus em testes de ataque fornecido pela magia. Esses PV temporários duram enquanto a magia durar.', true, '{"other":"Bênção"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Canto Monástico', 1, 'Você pode gastar uma ação padrão e 1 PM para entoar um cântico religioso. Faça um teste de Atuação para ajudar (Tormenta20, p. 221). Seus aliados em alcance curto recebem um bônus igual ao bônus de ajuda em um teste de perícia feito até o fim da cena ou na CD para resistir a uma de suas habilidades usada até o fim da cena.', true, '{"other":"treinado em Atuação"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Comunhão Vital', 1, 'Quando lança uma magia que cure uma criatura, você pode pagar +2 PM para que outra criatura em alcance curto (incluindo você mesmo) recupere uma quantidade de pontos de vida igual à metade dos PV da cura original.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Copista', 1, 'Você pode criar pergaminhos, como se tivesse o poder Escrever Pergaminho. Se tiver ambos, pode fabricar o dobro de pergaminhos ao mesmo tempo (pagando o custo de matéria-prima de ambos).', true, '{"other":"treinado em Ofício (escriba)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Conhecimento Mágico', 1, 'Você aprende duas magias de qualquer círculo que possa lançar. Você pode escolher este poder quantas vezes quiser.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Cozinheiro da Abadia', 1, 'Quando prepara um prato especial, você pode combinar os efeitos de dois pratos. Você faz apenas um teste de Ofício, mas paga o custo de ambos.', true, '{"other":"treinado em Ofício (cozinheiro)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Estudante Diligente', 1, 'No começo do dia você pode escolher uma perícia em que não seja treinado. Se fizer isso, até o fim do dia você sofre uma penalidade de –2 PM, mas pode fazer testes da perícia escolhida como se fosse treinado nela.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Fé e Razão', 1, 'Quando usa uma habilidade de frade, você pode gastar uma quantidade de PM limitada por sua Inteligência. Se fizer isso, a CD dessa habilidade aumenta em +1 por PM gasto.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Mago Branco', 1, 'Suas magias de cura de luz custam –1 PM e curam +1 PV por dado de cura.', true, '{"other":"3º nível de frade"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Memorizar Liturgia', 1, 'Uma vez por dia, você pode gastar 1 hora de estudo e um número de pergaminhos que contenham magias divinas igual ou menor que sua Inteligência. Até o fim do dia, você pode lançar as magias contidas nesses pergaminhos como se as conhecesse ou, se já conhecia a magia, você soma sua Inteligência no limite de PM para lançá-la.', true, '{"other":"Copista, 8º nível de frade"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Ofício do Mosteiro', 1, 'Você pode fabricar itens de vestuário com Ofício (artesão) e pode usar essa perícia para fabricar itens com uma melhoria.', true, '{"other":"treinado em Ofício (artesão)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Psicografia', 1, 'Seus textos recebem inspiração divina. Você pode fabricar pergaminhos de qualquer magia divina (mesmo uma que não conheça) de quaisquer círculos a que tenha acesso. A CD para fabricar um desses pergaminhos aumenta em +5.', true, '{"other":"Copista, 5º nível de frade"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Sacrário da Erudição', 1, 'Quando lançam magias a partir de pergaminhos, você e seus aliados dentro do sacrário recebem +1 PM para gastar em aprimoramentos (mesmo que não conheçam a magia).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Sacrário da Misericórdia', 1, 'No início dos seus turnos, cada criatura a sua escolha dentro do sacrário recupera uma quantidade de PV igual a 5 + sua Sabedoria. Este sacrário tem duração sustentada.', true, '{"other":"5º nível de frade"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Sacrário da Resiliência', 1, 'Você e seus aliados dentro do sacrário recebem +2 em testes de resistência e na Defesa. Quando cria este sacrário, você pode gastar mais PM para fortalecer seu efeito; para cada 2 PM adicionais gastos, o bônus concedido pelo sacrário aumenta em +1 (bônus máximo limitado pelo círculo máximo de magias que você pode lançar).', true, '{"other":"5º nível de frade"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Sacrário da Solenidade', 1, 'Criaturas dentro da área ficam sob condição terrível para lançar magias e sofrem –2 na Defesa. Quando cria este sacrário você pode gastar mais PM para fortalecer seu efeito; para cada 2 PM adicionais gastos, a penalidade causada pelo sacrário aumenta em 1 (penalidade máxima limitada pelo círculo máximo de magias que você pode lançar).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Sacrário da Verdade', 1, 'Sempre que uma criatura na área passa em um teste de Acrobacia, Enganação, Furtividade ou Ladinagem, ou acerta um ataque contra uma criatura sob efeito de uma ou mais condições, ela sofre 2d6 pontos de dano psíquico por círculo de magia a que você tem acesso.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Sacrário das Sombras', 1, 'A área do sacrário é coberta por sombras; criaturas dentro dela recebem camuflagem leve e, se forem mortos-vivos, também recebem +2 na Defesa e em testes de perícia.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Sacrário do Compartilhamento', 1, 'Este sacrário tem duração sustentada. Quando lança uma magia de 1º ou 2º círculo que tenha apenas você como alvo, se estiver em alcance curto deste sacrário você pode gastar 2 PM para que um aliado dentro dele receba o efeito básico dessa magia.', true, '{"other":"7º nível de frade"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', ' Sacrário do Ocaso', 1, 'Este sacrário é criado com 60 pontos de ocaso. No início de seus turnos, o sacrário perde 1d10 pontos de ocaso, e cada criatura dentro dele perde esse valor em PV. A perda de PV aumenta em +1d10 para cada círculo de magia que você possa lançar além do 1º. Quando cria o sacrário, você pode gastar mais PM para fortalecer seu efeito; para cada PM adicional gasto, o sacrário é criado com +20 pontos de ocaso. O sacrário desaparece quando seus pontos de ocaso terminam.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Sermão da Celeridade', 1, 'Uma vez por rodada, você pode gastar 5 PM para fazer um aliado em alcance curto ganhar uma ação padrão adicional no próximo turno dele. Você só pode usar esta habilidade uma vez por cena em cada aliado.', true, '{"other":"8º nível de frade"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Sermão da Égide', 1, 'Você pode gastar uma ação padrão e 3 PM para orar por proteção para uma criatura em alcance curto. Até o seu próximo turno, quando essa criatura sofrer dano, ela pode gastar essa proteção para reduzir esse dano à metade.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Teologia Aplicada', 1, 'Escolha duas perícias. Quando faz um teste de uma dessas perícias (exceto testes de ataque), você pode gastar 1 PM para rolar novamente esse teste, usando Religião. Você pode escolher este poder outras vezes para perícias diferentes.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Transferir Sacrário', 1, 'Você pode gastar uma ação de movimento e 1 PM para transferir um de seus sacrários no alcance em que você pode criá-lo para outro ponto no mesmo alcance.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Zelador dos Vinhedos', 1, 'Você pode usar Ofício (cozinheiro) para preparar poções de magias que você conheça e cujo alvo seja 1 criatura. As poções tomam a forma de bebidas e seguem as regras desses itens (Heróis de Arton, Capítulo 3), exceto que ingeri-las é uma ação padrão. A bebida pode ser comum ou especial. No segundo caso, a CD para fabricá-la aumenta em +5 e o custo aumenta conforme a bebida especial, mas consumi-la gera ambos os efeitos (da poção e da bebida especial).', true, '{"other":"treinado em Ofício (cozinheiro)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Dádiva da Fé', 1, 'No 5º nível, você recebe Proteção Sagrada (se sua divindade canaliza energia positiva) ou Cólera Divina (se canaliza energia negativa).
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Frade', 'Solo Santificado', 1, 'No 20º nível, o raio de sua Dádiva da Fé muda para 30m e criaturas afetadas por ela também somam o bônus concedido pela habilidade na CD de suas próprias habilidades.', false, NULL);
INSERT INTO classes (name, publication, hit_points, mana_points, skills, proficiencies) VALUES ('Guerreiro', 'Tormenta20', '20+CON', '3 por nível', '["Luta ou Pontaria","Fortitude","Adestramento","Atletismo","Cavalgar","Guerra","Iniciativa","Intimidação","Luta","Ofício","Percepção","Pontaria","Reflexos"]'::jsonb, '["Armas marciais","Armaduras pesadas","Escudos"]'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Ataque Especial', 1, 'Quando faz um ataque, você pode gastar 1 PM para receber +4 no teste de ataque ou na rolagem de dano. A cada quatro níveis, pode gastar +1 PM para aumentar o bônus em +4. Você pode dividir os bônus igualmente. Por exemplo, no 17º nível, pode gastar 5 PM para receber +20 no ataque, +20 no dano ou +10 no ataque e +10 no dano.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Ambidestria', 1, 'Se estiver empunhando duas armas (e pelo menos uma delas for leve) e fizer a ação agredir, você pode fazer dois ataques, um com cada arma. Se fizer isso, sofre –2 em todos os testes de ataque até o seu próximo turno.', true, '{"other":"Des 2"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Análise Tática', 1, 'Você recebe +2 em Guerra e pode fazer testes dessa perícia para identificar criatura contra humanoides (veja Misticismo em Tormenta20, p. 121).', true, '{"other":"treinado em Guerra"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Arqueiro', 1, 'Se estiver usando uma arma de ataque à distância, você soma sua Sabedoria em rolagens de dano (limitado pelo seu nível).', true, '{"other":"Sab 1"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Arremesso de Investida', 1, 'Quando faz uma investida, você pode gastar 1 PM para realizar um ataque à distância adicional com uma arma de arremesso contra o alvo da investida.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Ataque Reflexo', 1, 'Se um alvo em alcance de seus ataques corpo a corpo ficar desprevenido ou se mover voluntariamente para fora do seu alcance, você pode gastar 1 PM para fazer um ataque corpo a corpo contra esse alvo (apenas uma vez por alvo a cada rodada).', true, '{"other":"Des 1"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Aumento de Atributo', 1, 'Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Bater e Correr', 1, 'Quando faz uma investida, você pode continuar se movendo após o ataque, até o limite de seu deslocamento. Se gastar 2 PM, pode fazer uma investida sobre terreno difícil e sem sofrer a penalidade de Defesa.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Bloqueio Brutal', 1, 'Uma vez por rodada, quando é atingido por um ataque, você pode gastar 2 PM para fazer uma rolagem de dano corpo a corpo e subtrair o resultado dessa rolagem do dano causado pelo ataque.', true, '{"other":"For 5"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Corte Ágil', 1, 'Uma vez por rodada, quando faz um ataque com uma arma ágil ou leve, você pode gastar 1 PM para se mover até metade do seu deslocamento antes ou depois de fazer o ataque. Esse movimento não ativa reações dos inimigos (como de Ataque Reflexo).', true, '{"other":"Des 1"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Criar Oportunidade', 1, 'Quando você ou um aliado em alcance curto atacar uma criatura sob efeito do seu Xadrez de Batalha, você pode gastar 1 PM para que esse ataque cause +1d10 pontos de dano.', true, '{"other":"Xadrez de Batalha"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Defesa Estratégica', 1, 'Você soma sua Inteligência na Defesa, limitada pelo seu nível.', true, '{"other":"Int 1"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Destruidor', 1, 'Quando causa dano com uma arma corpo a corpo de duas mãos, você pode rolar novamente qualquer resultado 1 ou 2 da rolagem de dano da arma.', true, '{"other":"For 1"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Determinação Inabalável', 1, 'Enquanto estiver com metade dos seus pontos de vida ou menos, você recebe +2 em testes de resistência e o custo de sua habilidade Durão diminui em –1 PM.', true, '{"other":"11º nível de guerreiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Esgrimista', 1, 'Quando usa uma arma corpo a corpo leve ou ágil, você soma sua Inteligência em rolagens de dano (limitado pelo seu nível).', true, '{"other":"Int 1"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Especialização em Arma', 1, 'Escolha uma arma. Você recebe +2 em rolagens de dano com essa arma. Você pode escolher este poder outras vezes para armas diferentes.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Especialização em Armadura', 1, 'Você recebe redução de dano 5 se estiver usando uma armadura pesada.', true, '{"other":"12º nível de guerreiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Estrategista Inspirador', 1, 'Em seu primeiro turno de um combate, você pode gastar uma ação padrão e fazer um teste de Guerra. Se fizer isso, para cada 10 pontos no resultado do teste, você e seus aliados em alcance curto recebem 1 PM temporário. Esses PM temporários desaparecem no fim da cena.', true, '{"other":"treinado em Guerra"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Executor', 1, 'Você recebe +1d6 nas rolagens de dano contra criaturas que estejam com menos da metade dos pontos de vida. A cada quatro níveis além do 1º, esse dano extra aumenta em um passo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Fender Defesas', 1, 'Quando você acerta um ataque usando Ataque Especial, a criatura sofre uma penalidade na Defesa igual ao total de PM gastos nessa habilidade por 1 rodada.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Golpe de Raspão', 1, 'Uma vez por rodada, quando erra um ataque, você pode gastar 2 PM. Se fizer isso, causa metade do dano que causaria (ignorando efeitos que se aplicariam caso o ataque acertasse).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Golpe Demolidor', 1, 'Quando usa a manobra quebrar ou ataca um objeto, você pode gastar 2 PM para ignorar a redução de dano dele.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Golpe Pessoal', 1, 'Quando faz um ataque, você pode desferir seu Golpe Pessoal, uma técnica única, com efeitos determinados por você. Você constrói seu Golpe Pessoal escolhendo efeitos da lista a seguir. Cada efeito possui um custo; a soma deles será o custo do Golpe Pessoal (mínimo 1 PM). O Golpe Pessoal só pode ser usado com uma arma específica (por exemplo, apenas espadas longas). Quando sobe de nível, você pode reconstruir seu Golpe Pessoal e alterar a arma que ele usa. Você pode escolher este poder outras vezes para golpes diferentes e não pode gastar mais PM em golpes pessoais em uma mesma rodada do que seu limite de PM.', true, '{"other":"5º nível de guerreiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Ímpeto', 1, 'Você pode gastar 1 PM para aumentar seu deslocamento em +6m por uma rodada.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Inércia do Aço', 1, 'Quando acerta um ataque com uma arma de duas mãos em uma criatura, você pode gastar 3 PM para causar metade do dano desse ataque a cada inimigo adjacente a essa criatura.', true, '{"other":"5º nível de guerreiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Investida Ricochete', 1, 'Uma vez por rodada, quando faz uma investida e acerta o ataque, você pode gastar 2 PM para atacar outra criatura que você consiga alcançar como parte dessa investida.', true, '{"other":"Bater e Correr, 5º nível de guerreiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Manobra Dupla', 1, 'Uma vez por rodada, quando faz uma manobra de combate usando uma arma versátil, você pode pagar 1 PM para executar uma manobra diferente extra.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Mente Disciplinada', 1, 'Sempre que você é afetado por uma habilidade de um aliado que fornece um bônus numérico em testes de perícia, rolagens de dano ou na Defesa, para você esse bônus aumenta em +1.', true, '{"other":"6º nível de guerreiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Mestre em Arma', 1, 'Escolha uma arma. Com esta arma, seu dano aumenta em um passo e quando faz um teste de ataque você pode gastar 2 PM para rolá-lo novamente.', true, '{"other":"Especialização em Arma com a arma escolhida, 12º nível de guerreiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Operações Combinadas', 1, 'Quando usa Ordens de Engajamento, você pode gastar +3 PM. Se fizer isso, pode atacar junto do aliado e, se um de vocês usar habilidades com custo em PM que forneçam bônus a esse ataque ou a seu dano, o outro também é afetado (apenas se isso for aplicável ao ataque).', true, '{"other":"Ordens de Engajamento, 14º nível de guerreiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Ordens de Engajamento', 1, 'Uma vez por rodada, quando acerta um ataque em uma criatura sob efeito do seu Xadrez de Batalha, você pode gastar 2 PM para que um aliado em alcance curto possa fazer um ataque contra essa criatura.', true, '{"other":"Criar Oportunidade, Xadrez de Batalha, 11º nível de guerreiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Planejamento Marcial', 1, 'Uma vez por dia, você pode gastar uma hora e 3 PM para escolher um poder de guerreiro ou de combate cujos pré-requisitos cumpra. Você recebe os benefícios desse poder até o próximo dia.', true, '{"other":"treinado em Guerra, 10º nível de guerreiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Recuperar Fôlego', 1, 'Uma vez por cena, se estiver com 0 PM, você pode gastar uma ação de movimento para recuperar 1d8 PM.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Resiliência Marcial', 1, 'Sempre que sofrer dano letal, você recebe redução de dano 1 cumulativa (limitada pelo seu nível). Esse efeito dura até o fim da cena ou até você recuperar pontos de vida de qualquer forma.', true, '{"other":"4º nível de guerreiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Romper Resistências', 1, 'Quando faz um Ataque Especial, você pode gastar 1 PM adicional para ignorar 10 pontos de redução de dano.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Soldado de Infantaria', 1, 'Você recebe +3m em seu deslocamento e seu limite de carga aumenta em 6 espaços.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Solidez', 1, 'Se estiver usando um escudo, você aplica o bônus na Defesa recebido pelo escudo em testes de resistência.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Tornado de Dor', 1, 'Você pode gastar uma ação padrão e 2 PM para desferir uma série de golpes giratórios. Faça um ataque corpo a corpo e compare-o com a Defesa de cada inimigo em seu alcance natural. Então faça uma rolagem de dano com um bônus cumulativo de +2 para cada acerto e aplique-a em cada inimigo atingido.', true, '{"other":"6º nível de guerreiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Valentão', 1, 'Você recebe +2 em testes de ataque e rolagens de dano contra oponentes caídos, desprevenidos, flanqueados ou indefesos.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Velho de Guerra', 1, 'Seus olhos já viram muito e você não se abala facilmente. Você recebe +5 em Intimidação e imunidade a medo. Além disso, uma vez por cena pode gastar 5 PM para evitar completamente um efeito qualquer (ataque, magia etc.) usado contra você por outra criatura. Se o efeito for de área ou tiver outros alvos, continua funcionando normalmente contra eles.', true, '{"other":"17º nível de guerreiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Xadrez de Batalha', 1, 'Você pode gastar uma ação de movimento e 1 PM para analisar um oponente em alcance curto. Se fizer isso, você recebe +2 na Defesa e em testes de Reflexos contra essa criatura até o fim da cena. Esse bônus aumenta em +1 para cada outro poder que você possua que tenha Xadrez de Batalha como pré-requisito.', true, '{"other":"treinado em Guerra"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Durão', 1, 'A partir do 3ª nível, sua rijeza muscular permite que você absorva ferimentos. Sempre que sofre dano, você pode gastar 3 PM para reduzir esse dano à metade.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Ataque Extra', 1, 'A partir do 6º nível, quando usa a ação agredir, você pode gastar 2 PM para realizar um ataque adicional uma vez por rodada.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Campeão', 1, 'No 20º nível, o dano de todos os seus ataques aumenta em um passo. Além disso, sempre que você faz um Ataque Especial ou um Golpe Pessoal e acerta o ataque, recupera metade dos PM gastos nele. Por exemplo, se fizer um Ataque Especial gastando 5 PM para ganhar +20 nas rolagens de dano e acertar o ataque, recupera 2 PM.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Do Bom e do Melhor (Inovador)', 1, 'Você começa o jogo com uma arma, armadura ou escudo superior a sua escolha, de até T$ 500. Entretanto, você é considerado não proficiente em qualquer arma, armadura ou escudo que não seja superior ou mágico.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Sequência Especial (Inovador)', 1, 'Você pode gastar 2 PM para iniciar uma sequência de movimentos inovadores. Quando faz isso, a cada vez que ataca com uma arma que ainda não tenha usado nessa sequência, você recebe um bônus de +1 em testes de ataque e rolagens de dano (cumulativo até +2). A cada 4 níveis, você pode gastar +1 PM para aumentar o limite desses bônus em +2. A sequência termina ao fim da cena ou se você ficar 1 rodada sem trocar pelo menos uma arma.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Bombardeio Sequencial (Inovador)', 1, 'No 2º nível, você pode usar sua Sequência Especial ao usar itens alquímicos ou poções (nesse caso, aplica o bônus de ataque acumulado à CD para resistir ao item).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Acrobacia Defensiva (Inovador)', 1, 'A partir do 3º nível, quando sofre dano, você pode gastar 2 PM para executar uma pirueta defensiva. Você faz um teste de Acrobacia e subtrai o resultado desse teste do dano sofrido.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Domínio Excêntrico (Inovador)', 1, 'A partir do 4° nível, sempre que passar pelo menos uma semana carregando uma arma exótica ou de fogo superior ou mágica, você recebe proficiência nela.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Técnica Revolucionária (Inovador)', 1, 'A partir do 7° nível, você pode gastar 2 PM para, até o fim do combate, usar armas que esteja empunhando como se elas tivessem uma das seguintes habilidades de arma, a sua escolha: adaptável, ágil, alongada, dupla (use as estatísticas da arma em ambas as pontas) ou versátil (para uma manobra escolhida ao usar esta habilidade). Esse efeito termina se você ativar sua Técnica Revolucionária novamente.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Estilo Único (Inovador)', 1, 'No 20º nível, você consolida seu próprio estilo de combate. Escolha dois poderes de guerreiro ou de combate que possua. Para esses poderes, você ignora todos os requisitos e restrições relacionados a armas, incluindo propósito, empunhadura, características e habilidades das armas. Por exemplo, você pode usar Estilo de Duas Mãos com armas leves, Estilo de Arremesso com uma arma de duas mãos ou até Esgrimista com pistolas! O mestre tem a palavra final sobre como os poderes interagem entre si.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Guerreiro', 'Efeitos do Golpe Pessoal', 1, '• Amplo (+3 PM). Seu ataque atinge todas as criaturas em alcance curto (incluindo aliados, mas não você mesmo). Faça um único teste de ataque e compare com a Defesa de cada criatura.
INSERT INTO classes (name, publication, hit_points, mana_points, skills, proficiencies) VALUES ('Inventor', 'Tormenta20', '12+CON', '4 por nível', '["Ofício","Vontade","Conhecimento,","Cura","Diplomacia","Fortitude","Iniciativa","Investigação","Luta","Misticismo","Pilotagem","Percepção","Pontaria"]'::jsonb, '[]'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Engenhosidade', 1, 'Quando faz um teste de perícia, você pode gastar 2 PM para somar a sua Inteligência no teste. Você não pode usar esta habilidade em testes de ataque.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Protótipo', 1, 'Você começa o jogo com um item superior, ou com 10 itens alquímicos, com preço total de até T$ 500. Veja o Capítulo 3: Equipamento para a lista de itens.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Fabricar Item Superior', 1, 'No 2º nível, você recebe um item superior com preço de até T$ 2.000 e passa a poder fabricar itens superiores com uma melhoria. Veja o Capítulo 3: Equipamento para a lista de melhorias.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Agite Antes de Usar', 1, 'Quando usa um preparado alquímico que cause dano, você pode gastar uma quantidade de PM a sua escolha (limitado por sua Inteligência). Para cada PM que gastar, o item causa um dado extra de dano do mesmo tipo.', true, '{"other":"treinado em Ofício (alquimista)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Ajuste de Mira', 1, 'Você pode gastar uma ação padrão e uma quantidade de PM a sua escolha (limitado pela sua Inteligência) para aprimorar uma arma de ataque à distância. Para cada PM que gastar, você recebe +1 em rolagens de dano com a arma até o final da cena.', true, '{"other":"Balística"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Alquimista de Batalha', 1, 'Quando usa um preparado alquímico ou poção que cause dano, você soma sua Inteligência na rolagem de dano.', true, '{"other":"Alquimista Iniciado"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Alquimista Exímio', 1, 'Quando você usa um preparado alquímico ou uma poção, a CD para resistir a ele aumenta em +2 e, se ele causar dano ou recuperar PV ou PM, esse efeito aumenta em +1 por dado.', true, '{"other":"Alquimista Iniciado"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Alquimista Iniciado', 1, 'Você recebe um livro de fórmulas e pode fabricar poções com fórmulas que conheça de 1º e 2º círculos. Veja as páginas 333 e 341 para as regras de poções.', true, '{"other":"Int 1, Sab 1, treinado em Ofício (alquimista)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Alterar Programação', 1, 'Você pode gastar uma ação completa e 3 PM para alterar a programação de um construto não inteligente (Int –4 ou menor) adjacente. Faça um teste de Ofício (artesão) oposto ao teste de Vontade do construto. Se você vencer, ele fica confuso por 1 rodada e vulnerável. Se for um lacaio, em vez disso fica sob seu controle até o fim da aventura (veja Domar Criatura, p. 17). Você só pode controlar um construto dessa forma por vez e cada construto só pode ser alvo deste poder uma vez por cena.', true, '{"other":"treinado em Ofício (artesão)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Aparato Personalizado', 1, 'O primeiro aparato de cada uma de suas engenhocas não aumenta a CD para ativá-la.', true, '{"other":"Engenhoqueiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Armadura Avançada', 1, 'Quando ativa uma engenhoca acoplada, você recebe um bônus no teste de ativação igual ao número de melhorias da armadura. Além disso, você pode gastar 4 PM para ativar uma engenhoca acoplada como ação livre (apenas se sua ativação for ação de movimento, padrão ou completa).', true, '{"other":"Armadura Mecanizada, 7º nível de inventor"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Armadura Mecanizada', 1, 'Você pode gastar T$ 100 e 1 dia de trabalho para acoplar uma engenhoca em sua armadura. Armaduras leves podem ter uma engenhoca acoplada e armaduras pesadas podem ter até três. Uma engenhoca acoplada não conta em seu limite de itens vestidos e não precisa ser empunhada.', true, '{"other":"Engenhoqueiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Armeiro', 1, 'Você recebe proficiência com armas marciais corpo a corpo. Quando empunha uma arma corpo a corpo, pode usar sua Inteligência em vez de Força nos testes de ataque e rolagens de dano.', true, '{"other":"treinado em Luta e Ofício (armeiro)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Artesão Criativo', 1, 'Você pode usar Ofício (artesão) no lugar de qualquer outro Ofício para qualquer fim (como pré-requisitos, por exemplo).', true, '{"other":"treinado em Ofício (artesão)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Ativação Rápida', 1, 'Ao ativar uma engenhoca com ação padrão, você pode pagar 2 PM para ativá-la com uma ação de movimento, em vez disto.', true, '{"other":"Engenhoqueiro, 7º nível de inventor"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Aumento de Atributo', 1, 'Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Autômato', 1, 'Você fabrica um autômato, um construto que obedece a seus comandos. Ele é um parceiro iniciante de um tipo a sua escolha entre ajudante, assassino, atirador, combatente, guardião, montaria ou vigilante. No 7º nível, ele muda para veterano e, no 15º nível, para mestre. Se o autômato for destruído, você pode fabricar um novo com uma semana de trabalho e T$ 100.', true, '{"other":"Engenhoqueiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Autômato Alquímico', 1, 'Seu autômato pode armazenar itens alquímicos e poções, com uma capacidade de carga igual à sua Inteligência. Além disso, uma vez por rodada, você pode gastar 1 PM para usar um desses itens como uma ação livre.', true, '{"other":"Autômato"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Autômato Engenhocado', 1, 'Você pode gastar T$ 100 e 1 dia de trabalho para acoplar em seu autômato uma engenhoca que simule uma magia de 1º círculo com alvo 1 criatura ou objeto, ou que afete uma área. Uma vez por rodada, se o autômato estiver em alcance curto, você pode gastar +2 PM para ativar essa engenhoca como uma ação de movimento, tendo como origem o autômato.', true, '{"other":"Autômato Prototipado"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Autômato Prototipado', 1, 'Você pode gastar uma ação padrão e 2 PM para ativar uma melhoria experimental em seu autômato. Role 1d6. Em um resultado 2 a 6, você aumenta o nível de parceiro do autômato em um passo (até mestre), ou concede a ele a habilidade iniciante de outro de seus tipos, até o fim da cena. Em um resultado 1, o autômato enguiça como uma engenhoca.', true, '{"other":"Autômato"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Balística', 1, 'Você recebe proficiência com armas marciais de ataque à distância ou com armas de fogo. Quando usa uma arma de ataque à distância, pode usar sua Inteligência em vez de Destreza nos testes de ataque (e, caso possua o poder Estilo de Disparo, nas rolagens de dano).', true, '{"other":"treinado em Pontaria e Ofício (armeiro)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Blindagem', 1, 'Você pode usar sua Inteligência na Defesa quando usa armadura pesada. Se fizer isso, não pode somar sua Destreza, mesmo que outras habilidades ou efeitos permitam isso.', true, '{"other":"Couraceiro, 8º nível de inventor"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Cano Raiado', 1, 'Quando usa uma arma de disparo feita por você mesmo, ela recebe +1 na margem de ameaça.', true, '{"other":"Balística, 5º nível de inventor"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Catalisador Experimental', 1, 'Quando ativa uma engenhoca, você pode usar um catalisador e aplicar seus efeitos a ela.', true, '{"other":"Engenhoqueiro, 5º nível de inventor"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Catalisador Instável', 1, 'Você pode gastar uma ação completa e 3 PM para fabricar um preparado alquímico ou poção cuja fórmula conheça instantaneamente. O custo do item é reduzido à metade e você não precisa fazer o teste de Ofício (alquimista), mas ele só dura até o fim da cena.', true, '{"other":"Alquimista Iniciado"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Chutes e Palavrões', 1, 'Uma vez por rodada, quando faz um teste de Ofício (engenhoqueiro) para ativar uma engenhoca, você pode gastar 1 PM para rolá-lo novamente.', true, '{"other":"Engenhoqueiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Conhecimento de Fórmulas', 1, 'Você aprende três fórmulas de quaisquer círculos que possa aprender. Você pode escolher este poder quantas vezes quiser.', true, '{"other":"Alquimista Iniciado"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Couraceiro', 1, 'Você recebe proficiência com armaduras pesadas e escudos. Quando usa armadura, pode usar sua Inteligência em vez de Destreza na Defesa (mas continua não podendo somar um atributo na Defesa quando usa armadura pesada).', true, '{"other":"treinado em Ofício (armeiro)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Engenhoqueiro', 1, 'Você pode fabricar engenhocas. Veja as regras para isso na página 70.', true, '{"other":"Int 3, treinado em Ofício (engenhoqueiro)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Estilista', 1, 'Se estiver vestindo um item de vestuário feito por você mesmo, o bônus em perícias fornecido por ele aumenta em +1 e se aplica também a testes de Diplomacia e Enganação com criaturas inteligentes (Int –3 ou maior).', true, '{"other":"Car 1, treinado em Ofício (alfaiate)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Explicação Científica', 1, 'Você pode gastar uma ação de movimento e uma quantidade de PM limitada pela sua Inteligência para receber resistência a magia igual aos PM gastos até o fim da cena.', true, '{"other":"5º nível de inventor"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Explorar Fraqueza', 1, 'Quando usa Encontrar Fraqueza em um inimigo, você também ignora 5 pontos da redução de dano dele até o fim da cena.', true, '{"other":"Encontrar Fraqueza"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Farmacêutico', 1, 'Quando usa um item alquímico que cure pontos de vida, você pode gastar uma quantidade de PM a sua escolha (limitado por sua Inteligência). Para cada PM que gastar, o item cura um dado extra do mesmo tipo.', true, '{"other":"Sab 1, treinado em Ofício (alquimista)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Farmácia Mágica', 1, 'Você pode usar Farmacêutico em poções de cura.', true, '{"other":"Alquimista Iniciado, Farmacêutico"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Ferreiro', 1, 'Quando usa uma arma corpo a corpo feita por você mesmo, o dano dela aumenta em um passo.', true, '{"other":"Armeiro, 5º nível de inventor"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Forçar a Calibragem', 1, 'Quando faz um teste para ativar uma engenhoca, você pode sofrer uma penalidade de –5 nesse teste para aumentar a CD para resistir à engenhoca em +2.', true, '{"other":"Engenhoqueiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Galvanização', 1, 'Você pode gastar uma ação padrão para adicionar um material especial a um item adequado (isso não conta no limite de melhorias do item e se acumula com outros materiais especiais). O preço do material é reduzido a 5% do normal e você não precisa fazer o teste de Ofício para aplicá-lo, mas ele só dura até o fim da cena.', true, '{"other":"treinado em Ofício (artesão)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Gênio Inovador', 1, 'Você entende o mundo de forma diferente, e sua capacidade de inovar é quase ilimitada. Você pode usar Inteligência como atributo-chave de até duas perícias a sua escolha (em vez do atributo normal). Além disso, quando fabrica um item superior, você pode adicionar uma melhoria extra gratuita, que não conta no limite (por exemplo, por T$ +6.000, adiciona cinco melhorias, em vez de quatro). Por fim, os itens que você fabrica podem ter dois materiais especiais diferentes (em vez de apenas um).', true, '{"other":"17º nível de inventor"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Golpe de Gênio', 1, 'Uma vez por aventura (ou uma vez por mês, de acordo com o mestre), você pode usar Engenhosidade duas vezes em um mesmo teste, ou pode fabricar um item superior ou mágico com uma semana de trabalho (em vez de um mês).', true, '{"other":"11º nível de inventor"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Granadeiro', 1, 'Você pode arremessar itens alquímicos e poções em alcance médio. Você pode usar sua Inteligência em vez de Destreza para calcular a CD do teste de resistência desses itens.', true, '{"other":"Alquimista de Batalha"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Homúnculo', 1, 'Você possui um homúnculo, uma criatura Minúscula feita de alquimia. Vocês podem se comunicar telepaticamente em alcance longo e ele obedece a suas ordens, mas ainda está limitado ao que uma criatura de seu tamanho pode fazer. Um homúnculo é um parceiro ajudante iniciante. Você pode perder 1d6 pontos de vida para seu homúnculo assumir uma forma capaz de protegê-lo e se tornar também um parceiro guardião iniciante até o fim da cena.', true, '{"other":"Alquimista Iniciado"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Infusão Distante', 1, 'Quando usa um item alquímico ou uma poção que normalmente afetaria apenas um alvo adjacente, você pode gastar 1 PM para afetar um alvo em alcance curto. Se tiver o poder Granadeiro, em vez disso você afeta um alvo em alcance médio.', true, '{"other":"Alquimista Iniciado"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Invenção Potente', 1, 'Quando usa um item ou engenhoca fabricado por você mesmo, você pode pagar 1 PM para aumentar em +2 a CD para resistir a ele.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Maestria em Perícia', 1, 'Escolha um número de perícias treinadas igual a sua Inteligência, exceto bônus temporários. Quando faz um teste dessas perícias, você pode gastar 1 PM para escolher 10 em qualquer situação, exceto testes de ataque.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Manutenção Eficiente', 1, 'A quantidade de engenhocas que você pode manter aumenta em +3. Além disso, cada engenhoca passa a ocupar meio espaço.', true, '{"other":"Engenhoqueiro, 5º nível de inventor"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Mestre Alquimista', 1, 'Você pode fabricar poções com fórmulas que conheça de qualquer círculo.', true, '{"other":"Int 3, Sab 3, Alquimista Iniciado, 10º nível de inventor"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Mestre Cuca', 1, 'Todas as comidas que você cozinha têm seu bônus numérico aumentado em +1.', true, '{"other":"treinado em Ofício (cozinheiro)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Mistura Fervilhante', 1, 'Quando usa um item alquímico ou poção, você pode gastar 2 PM para dobrar a área de efeito dele.', true, '{"other":"Alquimista Iniciado, 5º nível de inventor"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Livro de Fórmulas', 1, 'Quando adquire o poder Alquimista Iniciado, você recebe um livro de fórmulas. Uma “fórmula” é uma magia divina ou arcana (atributo-chave Inteligência) que serve para cumprir os pré-requisitos de fabricação de poções.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Oficina de Campo', 1, 'Você pode gastar uma hora e 2 PM para fazer a manutenção do equipamento de seu grupo. Cada membro do grupo escolhe uma arma, armadura ou escudo para manutenção. Armas recebem +1 em testes de ataque, armaduras e escudos aumentam seu bônus na Defesa em +1. Os benefícios duram um dia.', true, '{"other":"treinado em Ofício (armeiro)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Oficina Esotérica', 1, 'Você pode usar Oficina de Campo em itens esotéricos, poções e pergaminhos. Itens esotéricos aumentam o limite de PM para magias em +1, poções rendem duas doses (a segunda dose deve ser consumida até o fim do dia) e pergaminhos permitem gastar +1 PM em aprimoramentos (mesmo que o usuário não conheça a magia).', true, '{"other":"treinado em Misticismo, Oficina de Campo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Pedra de Amolar', 1, 'Você pode gastar uma ação de movimento e uma quantidade de PM a sua escolha (limitado por sua Inteligência) para aprimorar uma arma corpo a corpo que esteja empunhando. Para cada PM que gastar, você recebe +1 em rolagens de dano com a arma até o final da cena.', true, '{"other":"Armeiro"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Saraivada Alquímica', 1, 'Quando usa um preparado alquímico ou uma poção de dano, você pode gastar 2 PM e uma dose extra do mesmo item para aumentar o dano causado em 50%.', true, '{"other":"Granadeiro, 7º nível de inventor"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Síntese Rápida', 1, 'Quando fabrica um item alquímico ou poção, você pode fabricar o dobro de doses no mesmo tempo (pagando o custo de matéria-prima de cada uma).', true, '{"other":"Alquimista Iniciado"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Comerciante', 1, 'No 3º nível, você pode vender itens 10% mais caro (não cumulativo com barganha).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Encontrar Fraqueza', 1, 'A partir do 7º nível, você pode gastar uma ação de movimento e 2 PM para analisar um objeto em alcance curto. Se fizer isso, ignora a redução de dano dele. Você também pode usar esta habilidade para encontrar uma fraqueza em um inimigo. Se ele estiver de armadura ou for um construto, você recebe +2 em seus testes de ataque contra ele. Os benefícios desta habilidade duram até o fim da cena.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Fabricar Item Mágico', 1, 'No 9º nível, você recebe um item mágico menor e passa a poder fabricar itens mágicos menores. Veja o Capítulo 8: Recompensas para as regras de itens mágicos.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Olho do Dragão', 1, 'A partir do 10º nível, você pode gastar uma ação completa para analisar um item. Você automaticamente descobre se o item é mágico, suas propriedades e como utilizá-las.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Obra-Prima', 1, 'No 20º nível, você fabrica sua obra-prima, aquela pela qual seu nome será lembrado em eras futuras. Você é livre para criar as regras do item, mas ele deve ser aprovado pelo mestre. Como linha geral, ele pode ter benefícios equivalentes a de um item com cinco melhorias e quatro encantos. Considera-se que você estava trabalhando no item e você não gasta dinheiro, tempo ou PM nele.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Laboratório Pessoal (Alquimista)', 1, 'Você começa o jogo com instrumentos de alquimista aprimorados e 10 itens alquímicos com preço total de até T$ 300.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Mistura Básica (Alquimista)', 1, 'A partir do 3º nível, você pode usar catalisadores em itens alquímicos como se fossem magias.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Aplicação Rápida (Alquimista)', 1, 'No 5º nível, você pode gastar uma ação completa e 2 PM para usar dois preparados alquímicos ao mesmo tempo. Você precisa ter ambos em suas mãos ou ser capaz de sacá- -los como ação livre.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Magia Engarrafada (Alquimista)', 1, 'No 7º nível, você pode usar Mistura Básica e Aplicação Rápida em poções.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Odores Alquímicos (Alquimista)', 1, 'A partir do 8º nível, você pode gastar uma ação completa para detectar a presença de itens alquímicos e poções em alcance médio. No caso de itens alquímicos, você descobre seu tipo (preparado, veneno etc.) e uso geral (curar, fornecer bônus etc.). Para poções, você identifica qual magia ela emula e com quantos pontos de mana foi fabricada.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Fabricar Emulsão (Alquimista)', 1, 'No 9º nível, você aprende a fabricar emulsões com um encanto (veja o quadro). Nos níveis 13 e 17, você aprende a fabricar emulsões com respectivamente dois e três encantos.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Emulsões (Alquimista)', 1, 'Uma emulsão é um óleo que concede propriedades mágicas a um item. Usá-la é uma ação padrão e fornece um ou mais encantos para um item até o fim da cena. Conceder um encanto através de uma emulsão não tem custo adicional (além do gasto do óleo) e conta no limite de encantos do item.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Bombardeio Eficiente (Alquimista)', 1, 'A partir do 11º nível, quando usa um preparado alquímico ou uma poção que causa dano, você pode gastar 1 PM para que esse item ignore 10 pontos da redução de dano das criaturas atingidas.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Pedra Filosofal (Alquimista)', 1, 'No 20º nível, você recebe uma pedra filosofal, um material que combina alquimia, magia e sua própria energia vital em uma fórmula única. Enquanto estiver de posse de sua pedra filosofal, você tem Cura Acelerada 10 e, quando faz um teste de Fortitude, rola dois dados e usa o melhor resultado. Além disso, se você ou um aliado em alcance curto for reduzido a 0 PV ou morrer, você pode sacrificar sua pedra filosofal para salvar essa criatura. A pedra se estilhaça em uma explosão de energia positiva que fornece ao alvo o efeito básico da magia Segunda Chance (com o efeito adicional de reconstruir o corpo do alvo, caso tenha sido destruído ou desintegrado). Você só pode ter uma pedra filosofal por vez; se perdê-la, pode fabricar outra com uma semana de trabalho e o gasto de T$ 18.000.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Engenhocas', 1, 'Uma engenhoca é uma invenção que simula o efeito de uma magia. Exemplos incluem um canhão (simula o efeito da magia Bola de Fogo), uma arma de raios (Relâmpago), um casaco blindado (Armadura Arcana), um emplastro curativo (Curar Ferimentos), um guarda-costas mecânico (Conjurar Monstro), um projetor de imagens (Criar Ilusão), um veículo a vapor (Montaria Arcana) etc.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Fabricação', 1, 'Para fabricar uma engenhoca, escolha uma magia arcana ou divina de 1º círculo. Essa será a magia que a engenhoca irá simular. A partir do 6º nível, você pode criar engenhocas com magias de 2º círculo e, a cada quatro níveis, pode criar engenhocas de um círculo maior.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Limite de Engenhocas', 1, 'Engenhocas são itens complexos e delicados, que exigem manutenção constante. O máximo de engenhocas que você pode ter ao mesmo tempo é igual a sua Inteligência.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Ativação', 1, 'Apenas o fabricante de uma engenhoca pode ativá-la. Ativar uma engenhoca exige uma ação padrão (ou a execução da magia, o que for maior) e um teste de Ofício (engenhoqueiro) contra CD 15 + custo em PM da magia. Se você passar, a engenhoca gera o efeito da magia (atributo-chave Int). Se falhar, ela enguiça e não pode ser utilizada até ser consertada, o que exige uma hora de trabalho. Cada nova ativação da engenhoca no mesmo dia aumenta a CD do teste de Ofício em +5.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Efeito Mundano', 1, 'O efeito de uma engenhoca não é mágico. Isso significa que ele não pode ser dissipado, funciona em áreas de antimagia etc.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Penalidade de Armadura', 1, 'A ativação de uma engenhoca exige movimentos rápidos e precisos. Por isso, o teste de Ofício (engenhoqueiro) para ativar engenhocas sofre penalidade de armadura. Porém, você pode ativar engenhocas que geram magias arcanas enquanto usa armadura sem precisar fazer testes de Misticismo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Inventor', 'Efeitos que Impedem Conjuração', 1, 'Um efeito que especificamente impeça um personagem de lançar magias (como a Fúria de um bárbaro ou a magia Transformação de Guerra) também impede um inventor de ativar engenhocas.', false, NULL);
INSERT INTO classes (name, publication, hit_points, mana_points, skills, proficiencies) VALUES ('Ladino', 'Tormenta20', '12+CON', '4 por nível', '["Ladinagem","Reflexos","Acrobacia","Atletismo","Atuação","Cavalgar","Conhecimento","Diplomacia","Enganação","Furtividade","Iniciativa","Intimidação","Intuição","Investigação","Jogatina","Luta","Ofício","Percepção","Pilotagem","Pontaria"]'::jsonb, '[]'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Ataque Furtivo', 1, 'Você sabe atingir os pontos vitais de inimigos distraídos. Uma vez por rodada, quando atinge uma criatura desprevenida com um ataque corpo a corpo ou em alcance curto, ou uma criatura que esteja flanqueando, você causa 1d6 pontos de dano extra. A cada dois níveis, esse dano extra aumenta em +1d6. Uma criatura imune a acertos críticos também é imune a ataques furtivos.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Especialista', 1, 'Escolha um número de perícias treinadas igual a sua Inteligência, exceto bônus temporários (mínimo 1). Ao fazer um teste de uma dessas perícias, você pode gastar 1 PM para dobrar seu bônus de treinamento. Você não pode usar esta habilidade em testes de ataque.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Evasão', 1, 'A partir do 2º nível, quando sofre um efeito que permite um teste de Reflexos para reduzir o dano à metade, você não sofre dano algum se passar. Você ainda sofre dano normal se falhar no teste de Reflexos. Esta habilidade exige liberdade de movimentos; você não pode usá-la se estiver de armadura pesada ou na condição imóvel.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Ameaça Brutal', 1, 'Se fizer um teste de Intimidação para assustar uma criatura na qual tenha causado dano desde a última rodada, você recebe +5 no teste e ela fica apavorada se você passar por 5 ou mais (em vez de 10 ou mais).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Assassinar', 1, 'Você pode gastar uma ação de movimento e 3 PM para analisar uma criatura em alcance curto. Até o fim de seu próximo turno, seu primeiro Ataque Furtivo que causar dano a ela tem seus dados de dano extras dessa habilidade dobrados.', true, '{"other":"5º nível de ladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Assassino em Série', 1, 'Você pode gastar 2 PM para usar Ataque Furtivo uma segunda vez na rodada.', true, '{"other":"11º nível de ladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Ataque Furtivo Letal', 1, 'Quando você faz um ataque furtivo, sempre que rolar o resultado máximo ou um ponto abaixo em um dado da habilidade (por exemplo, um 5 ou 6 ao rolar 1d6), role um dado extra.', true, '{"other":"5º nível de ladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Aumento de Atributo', 1, 'Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Bombardeiro Furtivo', 1, 'Você pode usar Ataque Furtivo ao utilizar preparados alquímicos de dano.', true, '{"other":"treinado em Ofício (alquimista)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Chefe de Gangue', 1, 'Seus capangas podem usar Ataque Furtivo +1d6 e Evasão, e podem fazer testes de Reflexos usando o seu valor nessa perícia.', true, '{"other":"5º nível de ladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Conhecimento Anatômico', 1, 'Contra humanoides, os dados do seu Ataque Furtivo aumentam em um passo.', true, '{"other":"treinado em Cura"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Contatos no Submundo', 1, 'Quando chega em uma comunidade equivalente a uma vila ou maior, você pode gastar 2 PM para fazer um teste de Carisma (CD 10). Se passar, enquanto estiver nessa comunidade, recebe +5 em testes de Investigação para interrogar, pode comprar itens mundanos, poções e pergaminhos com 20% de desconto (não cumulativo com barganha e outros descontos) e, de acordo com o mestre, tem acesso a itens e serviços proibidos (como armas de pólvora e venenos).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Emboscar', 1, 'Na primeira rodada de cada combate, você pode gastar 2 PM para executar uma ação padrão adicional em seu turno.', true, '{"other":"treinado em Furtividade"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Enganar os Olhos', 1, 'Quando você faz um teste de Acrobacia para passar por inimigo, a criatura o considera invisível por 1 rodada (Reflexos CD Des evita).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Escapista', 1, 'Você recebe +5 em testes de Acrobacia para escapar, passar por espaço apertado e passar por inimigo e em testes para resistir a efeitos de movimento.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Finta Acrobática', 1, 'Você soma sua Destreza em testes de Enganação para fintar.', true, '{"other":"treinado em Acrobacia e Enganação"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Fuga Formidável', 1, 'Você pode gastar uma ação completa e 1 PM para analisar o lugar no qual está (um castelo, um porto, a praça de uma cidade...). Até o fim da cena, recebe +3m em seu deslocamento, +5 em Acrobacia e Atletismo e ignora penalidades em movimento por terreno difícil. Você perde esses benefícios se fizer uma ação que não seja diretamente relacionada a fugir. Por exemplo, você só pode atacar um inimigo se ele estiver bloqueando seu caminho, agarrando-o etc. Você pode fazer ações para ajudar seus aliados, mas apenas se eles estiverem tentando escapar.', true, '{"other":"Int 1"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Gatuno', 1, 'Você recebe +2 em Atletismo. Quando escala, não fica desprevenido e avança seu deslocamento normal, em vez de metade dele.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Improvisação Arcana', 1, 'Quando passa em um teste de Misticismo para lançar uma magia arcana que não conhece de um pergaminho, para cada 2 pontos pelos quais seu teste superar a CD, você pode gastar 1 PM em aprimoramentos da magia.', true, '{"other":"treinado em Misticismo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Investida Rasteira', 1, 'Se você acertar um ataque corpo a corpo contra uma criatura que sofreu uma investida desde a última rodada, ela fica desprevenida por 1 rodada e caída (Reflexos CD Des evita).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Ladrão Arcano', 1, 'Quando causa dano com um ataque furtivo em uma criatura capaz de lançar magias, você pode “roubar” uma magia que já a tenha visto lançar. Você precisa pagar 1 PM por círculo da magia e pode roubar magias de até 4º círculo. Até o fim da cena, você pode lançar a magia roubada (atributo-chave Inteligência).', true, '{"other":"Roubo de Mana, 13º nível de ladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Mão na Boca', 1, 'Você recebe +2 em testes de agarrar. Quando acerta um ataque furtivo contra uma criatura desprevenida, você pode fazer um teste de agarrar como uma ação livre. Se agarrar a criatura, ela não poderá falar enquanto estiver agarrada.', true, '{"other":"treinado em Luta"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Mãos Rápidas', 1, 'Uma vez por rodada, ao fazer um teste de Ladinagem para abrir fechaduras, ocultar item, punga ou sabotar, você pode pagar 1 PM para fazê-lo como uma ação livre.', true, '{"other":"Des 2, treinado em Ladinagem"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Mente Criminosa', 1, 'Você soma sua Inteligência em Ladinagem e Furtividade.', true, '{"other":"Int 1"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Mestre Assassino', 1, 'Quando usa Assassinar, você pode gastar +2 PM para:
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Mestre Envenenador', 1, 'Quando afeta uma criatura com um veneno, você pode gastar +2 PM para:
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Papo Furado', 1, 'Quando você passa em um teste de Diplomacia contra uma criatura, se passar também em um teste de Enganação contra ela até o fim do seu próximo turno, a atitude da criatura em relação a você melhora em uma categoria.', true, '{"other":"treinado em Diplomacia e Enganação"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Precisão Furtiva', 1, 'O alcance do seu Ataque Furtivo aumenta em uma categoria (de curto para médio e de médio para longo). Além disso, quando você ataca uma criatura desprevenida ou que você esteja flanqueando, sua margem de ameaça aumenta em +2.', true, '{"other":"treinado em Pontaria, Ataque Furtivo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Oportunismo', 1, 'Uma vez por rodada, quando um inimigo adjacente sofre dano de um de seus aliados, você pode gastar 2 PM para fazer um ataque corpo a corpo contra este inimigo.', true, '{"other":"6º nível de ladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Rei do Crime', 1, 'Você é uma lenda dos becos e das tavernas, e todos querem lhe servir para ter uma chance de progredir no submundo. Uma vez por cena, você pode gastar 6 PM para invocar 2d4+2 assassinos capangas em espaços desocupados em alcance curto. Os assassinos possuem deslocamento 9m, Defesa 17, dano 1d6+5 de corte cada e Ataque Furtivo +4d6. Uma vez por rodada, quando você é alvo de um efeito, pode sacrificar um capanga adjacente para ignorar o efeito. Veja “Capangas”, p. 240.', true, '{"other":"Chefe de Gangue, Contatos no Submundo, Mente Criminosa, 17º nível de ladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Rolamento Defensivo', 1, 'Sempre que sofre dano, você pode gastar 2 PM para reduzir esse dano à metade. Após usar este poder, você fica caído.', true, '{"other":"treinado em Reflexos"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Roubo de Mana', 1, 'Quando você causa dano com um ataque furtivo, para cada 1d6 de dano de seu ataque furtivo, você recebe 1 PM temporário e a criatura perde 1 ponto de mana (se tiver). Você só pode usar este poder uma vez por cena contra uma mesma criatura.', true, '{"other":"Truque Mágico, 7º nível de ladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Sabotagem Corrosiva', 1, 'Quando faz um teste de Ladinagem para abrir fechaduras ou sabotar, você pode gastar um ácido para receber um bônus de +5 nesse teste. Além disso, pode gastar uma ação de movimento e um ácido para fazer um teste de Ladinagem oposto ao teste de Reflexos de uma criatura em alcance curto. Se você vencer o teste oposto, a criatura fica desprevenida e sofre –5 em testes de ataque por 1 rodada.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Saqueador de Tumbas', 1, 'Você recebe +5 em testes de Investigação para encontrar armadilhas e em testes de resistência contra elas. Além disso, gasta uma ação padrão para desabilitar mecanismos, em vez de 1d4 rodadas (veja a perícia Ladinagem).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Senhor do Submundo', 1, 'Você é uma figura sombria e sua mera presença incita medo e respeito. Você recebe +5 em Intimidação e imunidade a medo. Além disso, quando você fica adjacente a outra criatura (independente de quem tenha se movido), você pode deixá-la apavorada e desprevenida por 1 rodada. Uma mesma criatura só pode ser afetada por este poder uma vez por cena.', true, '{"other":"treinado em Intimidação, 17º nível de ladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Sombra', 1, 'Você recebe +2 em Furtividade, não sofre penalidade em testes de Furtividade por se mover no seu deslocamento normal e reduz a penalidade por atacar e fazer outras ações chamativas para –10.', true, '{"other":"treinado em Furtividade"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Truque de Palco', 1, 'Escolha três magias arcanas de 1º círculo que possuam o aprimoramento truque. Você aprende e pode lançar essas magias (atributo-chave Inteligência), mas apenas com esse aprimoramento. Esta não é uma habilidade mágica — os efeitos provêm de prestidigitação (veja “Magias Simuladas”, p. 44).', true, '{"other":"treinado em Atuação"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Truque do Chapéu', 1, 'Uma vez por rodada, você pode gastar uma ação de movimento para tirar e arremessar um item que esteja vestindo em uma criatura em alcance curto. Se fizer isso, você pode fazer um ataque com uma arma de arremesso, ou arremessar um preparado alquímico ou poção contra ela como parte dessa ação.', true, '{"other":"treinado em Enganação"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Truque Mágico', 1, 'Você aprende e pode lançar uma magia arcana de 1º círculo a sua escolha, pagando seu custo normal em PM. Seu atributo-chave para esta magia é Inteligência. Você pode escolher este poder quantas vezes quiser.', true, '{"other":"Int 1"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Velocidade Ladina', 1, 'Uma vez por rodada, você pode gastar 2 PM para realizar uma ação de movimento adicional em seu turno.', true, '{"other":"Des 2, treinado em Iniciativa"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Veneno Persistente', 1, 'Quando aplica uma dose de veneno a uma arma, este veneno dura por três ataques (em vez de apenas um).', true, '{"other":"Veneno Potente, 8º nível de ladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Veneno Potente', 1, 'A CD para resistir aos venenos que você usa aumenta em +5.', true, '{"other":"treinado em Ofício (alquimista)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Vestido Para a Ocasião', 1, 'Se estiver usando um traje da corte ou de viajante, você pode gastar uma ação completa e 1 PM para transformar esse item em outro item de vestuário mundano até o fim da cena. Isso fornece +5 em testes de Enganação para disfarce, além dos benefícios do novo item.', true, '{"other":"treinado em Enganação"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Esquiva Sobrenatural', 1, 'No 4º nível, seus instintos são tão apurados que você consegue reagir ao perigo antes que seus sentidos percebam. Você nunca fica surpreendido.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Olhos nas Costas', 1, 'A partir do 8º nível, você consegue lutar contra diversos inimigos como se fossem apenas um. Você não pode ser flanqueado.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Evasão Aprimorada', 1, 'No 10º nível, quando sofre um efeito que permite um teste de Reflexos para reduzir o dano à metade, você não sofre dano algum se passar e sofre apenas metade do dano se falhar. Esta habilidade exige liberdade de movimentos; você não pode usá-la se estiver de armadura pesada ou na condição imóvel.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'A Pessoa Certa para o Trabalho', 1, 'No 20º nível, você se torna um mestre da ladinagem. Ao fazer um ataque furtivo ou usar uma perícia da lista de ladino, você pode gastar 5 PM para receber +10 no teste.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Charme (Ventanista)', 1, 'Você soma seu Carisma em seu total de PM. Quando faz um teste de perícia (exceto testes de ataque), você pode gastar uma quantidade de PM a sua escolha (limitada pelo seu Carisma). Para cada PM que gastar, recebe +2 no teste.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Truques do Ofício (Ventanista)', 1, 'Você pode lançar magias arcanas de 1º círculo, mas apenas de encantamento e ilusão. Esta não é uma habilidade mágica e provém da sua capacidade de enganar outras pessoas (veja “Magias Simuladas”, p. 44). À medida que sobe de nível, pode lançar magias de círculos maiores (2º círculo no 6º nível, 3º círculo no 10º nível e 4º círculo no 14º nível). 
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Disfarce Elaborado (Ventanista)', 1, 'No 3º nível, você aprende a simular habilidades práticas úteis para seus disfarces. Sempre que fizer um teste de Enganação para disfarce (Tormenta20, p. 118), você pode escolher um poder (exceto poderes da Tormenta) cujos pré-requisitos cumpra e que esteja relacionado a esse disfarce. Enquanto estiver disfarçado dessa forma, você sofre uma penalidade de –3 PM e pode usar o poder escolhido. A cada seis níveis, você pode assumir uma penalidade adicional de –3 PM ao se disfarçar para escolher um poder adicional.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Virar a Casaca (Ventanista)', 1, 'No 7º nível, se estiver disfarçado, você pode gastar 1 PM para remover seu disfarce. Quando faz isso, você pode fazer um teste de esconder-se (Tormenta20, p. 119) usando Enganação no lugar de Furtividade, mesmo sem camuflagem ou cobertura disponível.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'Provocação Ousada (Ventanista)', 1, 'A partir do 11º nível, em seu primeiro turno em cada cena, você pode gastar uma ação completa para provocar seus inimigos. Você pode deixar um cartão de visitas visível, declarar seu plano ou fazer outra ação que alerte seus inimigos de sua presença e de suas intenções. Até o fim da cena, seus inimigos recebem +2 em testes de Percepção, Sobrevivência e Vontade contra você. Entretanto, no início de seus turnos você recupera 2 PM. Esta habilidade só tem efeito se houver um risco associado a declarar suas ações (a critério do mestre) e recupera um máximo de PM por cena igual ao seu nível.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Ladino', 'O Grande Golpe (Ventanista)', 1, 'No 20º nível, no início de cada aventura, você pode escolher uma quantidade de magias, arcanas ou divinas, igual à sua Inteligência (você pode escolher a mesma magia mais de uma vez). Para cada escolha feita, defina um tipo de cena entre ação, exploração e interpretação (Tormenta20, p. 252). Até o fim da aventura, para cada vez que uma magia foi escolhida, se estiver em uma cena do tipo definido para ela, você pode lançá-la sem gastar PM (limite de PM 20, atributo-chave Inteligência). Esta não é uma habilidade mágica e provém da sua capacidade de enganar outras pessoas.', false, NULL);
INSERT INTO classes (name, publication, hit_points, mana_points, skills, proficiencies) VALUES ('Lutador', 'Tormenta20', '20+CON', '3 por nível', '["Fortitude","Luta","Acrobacia","Adestramento","Atletismo","Enganação","Furtividade","Iniciativa","Intimidação","Ofício","Percepção","Pontaria","Reflexos"]'::jsonb, '[]'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Briga', 1, 'Seus ataques desarmados causam 1d6 pontos de dano e podem causar dano letal ou não letal (sem penalidades). A cada quatro níveis, seu dano desarmado aumenta, conforme a tabela. O dano na tabela é para criaturas Pequenas e Médias. Criaturas Minúsculas diminuem esse dano em um passo, Grandes e Enormes aumentam em um passo e Colossais aumentam em dois passos.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Golpe Relâmpago', 1, 'Quando usa a ação agredir para fazer um ataque desarmado, você pode gastar 1 PM para realizar um ataque desarmado adicional.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Aquecimento', 1, 'Em seu primeiro turno de um combate, você pode gastar uma ação completa para aquecer seus músculos. Você soma sua Constituição em seus testes de ataque desarmado (limitada pelo seu nível) e recebe uma quantidade de PV temporários igual a sua Constituição + seu nível. Ambos os bônus duram até o fim da cena.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Arma Improvisada', 1, 'Para você, atacar com armas improvisadas conta como fazer um ataque desarmado, mas seu dano aumenta em um passo. Você pode gastar uma ação de movimento para procurar uma pedra, cadeira, garrafa ou qualquer coisa que possa usar como arma. Faça um teste de Percepção (CD 20). Se você passar, encontra uma arma improvisada. Armas improvisadas são frágeis; se você errar um ataque e o resultado do d20 for um número ímpar, a arma quebra.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Até Acertar', 1, 'Se você errar um ataque desarmado, recebe um bônus cumulativo de +2 em testes de ataque e rolagens de dano desarmado contra o mesmo oponente. Os bônus terminam quando você acertar um ataque ou no fim da cena, o que acontecer primeiro.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Aumento de Atributo', 1, 'Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Braços Calejados', 1, 'Se você não estiver usando armadura, soma sua Força na Defesa, limitado pelo seu nível.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Cabeçada', 1, 'Quando faz um ataque desarmado, você pode gastar 2 PM. Se fizer isso, o oponente fica desprevenido contra este ataque. Você só pode usar este poder uma vez por cena contra um mesmo alvo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Caminhar pelas Paredes', 1, 'Você recebe +10 em testes de Atletismo para saltar e pode se deslocar por paredes e tetos. Contudo, se terminar seu movimento enquanto se desloca em uma parede, você cai (e sofre os efeitos normais de uma queda).', true, '{"other":"treinado em Atletismo"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Caminho Suave', 1, 'Quando faz um teste de manobra com um ataque desarmado, você pode gastar uma quantidade de PM a sua escolha (limitada pela sua Sabedoria). Para cada PM que gastar, você recebe +2 no teste.', true, '{"other":"Sab 1"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Chave', 1, 'Se estiver agarrando uma criatura e fizer um teste de manobra contra ela para causar dano, o dano desarmado aumenta em um passo.', true, '{"other":"Int 1, Lutador de Chão, 4º nível de lutador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Combinações Desarmadas', 1, 'Poderes de Combinação representam golpes que se aproveitam dos efeitos de ataques anteriores sobre seu oponente. Eles compartilham as seguintes regras.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Combinação: Boca do Estômago', 1, 'Quando faz um ataque, você pode gastar 1 PM para que seu golpe seja debilitante. Se acertar, você recebe um bônus na rolagem de dano igual à sua contagem de combinações e o oponente fica enjoado até o fim do seu próximo turno.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Combinação: Chute Circular', 1, 'Quando faz um ataque, você pode gastar 2 PM para que seu golpe seja giratório. Se acertar, para cada ponto em sua contagem de combinações você causa +1d6 pontos de dano. Além disso, você pode fazer uma manobra empurrar contra o mesmo oponente como uma ação livre (use o resultado do ataque como o teste de manobra).', true, '{"other":"outro poder de Combinação"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Combinação: Chute no Joelho', 1, 'Quando faz um ataque, você pode gastar 1 PM para que seu golpe seja um chute baixo cruel. Se acertar, até o fim do seu próximo turno o oponente fica lento e sofre uma penalidade em testes de ataque e rolagens de dano igual à sua contagem de combinações.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Combinação: Esquiva Técnica', 1, 'Uma vez por rodada, quando sofre um ataque corpo a corpo, você pode gastar 2 PM para fazer um teste de Reflexos oposto ao teste de Percepção do atacante. Você recebe um bônus nesse teste igual à sua contagem de combinações. Se vencer o teste oposto, você evita o ataque e recebe +5 em seu próximo teste de ataque desarmado contra o atacante nessa rodada.', true, '{"other":"um poder de Combinação"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Combinação: Quebra-guarda', 1, 'Quando faz um ataque, você pode gastar 1 PM para que seu golpe supere defesas. Se fizer isso, recebe um bônus no teste de ataque igual à sua contagem de combinações. Se acertar, o oponente não pode usar habilidades para reduzir o dano do ataque ou receber RD adicional contra ele. Além disso, o oponente fica vulnerável até o fim do seu próximo turno.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Combinação: Um-Dois', 1, 'Quando faz um ataque, você pode gastar 1 PM para atacar de vários lados. Se fizer isso, você não precisa de um aliado para flanquear o oponente (faz isso sozinho). Além disso, se acertar, recebe um bônus na Defesa igual à sua contagem de combinações até o fim do seu próximo turno.', true, '{"other":"Jogo de Pernas"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Combinação: Técnica de Sacrifício', 1, 'Quando faz um ataque, você pode gastar 1 PM para que ele seja um movimento de projeção. Para isso, faça uma manobra agarrar com um bônus igual à sua contagem de combinações. Se vencer o teste de manobra, além de agarrar o oponente, você se joga no chão com ele. Ambos ficam caídos, mas ele sofre dano como se você tivesse acertado um ataque desarmado.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Confiança dos Ringues', 1, 'Quando um inimigo erra um ataque corpo a corpo contra você, você recebe 2 PM temporários (cumulativos). Você pode ganhar um máximo de PM temporários por cena igual ao seu nível. Esses pontos temporários desaparecem no final da cena.', true, '{"other":"8º nível de lutador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Convencido', 1, 'Acostumado a contar apenas com seus músculos, você adquiriu certo desdém por artes mais sofisticadas. Você recebe resistência a medo e mental +5.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Corpo Fechado', 1, 'Quando faz um teste de resistência, você pode gastar 1 PM para somar sua Constituição no teste.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Dança Marcial', 1, 'Você pode gastar uma ação de movimento e 2 PM para receber +2 na Defesa, em Acrobacia e em testes de Enganação para fintar. A partir do 6º nível, e a cada cinco níveis seguintes (11º e 16º), você pode gastar +1 PM para aumentar esses bônus em +1. Os bônus duram até o fim da cena ou até você ficar atordoado ou sob alguma condição de movimento.', true, '{"other":"treinado em Acrobacia e Atuação"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Gingado Elusivo', 1, 'Se estiver sob efeito de sua Dança Marcial, uma vez por rodada, quando sofre um efeito hostil, você pode gastar 2 PM para receber +5 na Defesa e em testes de Reflexos contra ele. Após a resolução do efeito, você salta para um espaço adjacente desocupado.', true, '{"other":"Dança Marcial, 7º nível de lutador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Golpe Baixo', 1, 'Quando faz um ataque desarmado, você pode gastar 2 PM. Se fizer isso e acertar o ataque, o oponente deve fazer um teste de Fortitude (CD For). Se ele falhar, fica atordoado por uma rodada (apenas uma vez por cena).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Golpe Imprudente', 1, 'Quando usa Golpe Relâmpago, você pode atacar de forma impulsiva. Se fizer isso, seus ataques desarmados recebem um dado de dano extra do mesmo tipo (por exemplo, se o seu dano é 2d6, você causa 3d6), mas você sofre –5 na Defesa até o início de seu próximo turno.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Imobilização', 1, 'Se estiver agarrando uma criatura, você pode gastar uma ação completa para imobilizá-la. Faça um teste de manobra contra ela. Se você passar, imobiliza a criatura — ela fica indefesa e não pode realizar nenhuma ação, exceto tentar se soltar (o que exige um teste de manobra). Se a criatura se soltar da imobilização, ainda fica agarrada. Enquanto estiver imobilizando uma criatura, você sofre as penalidades de agarrar.', true, '{"other":"Chave, 8º nível de lutador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Invencível', 1, 'Você é um campeão de incontáveis embates, famoso e endurecido por isso. Quando faz um teste de perícia baseada em Carisma, você pode gastar 2 PM para somar a sua Força no teste. Além disso, sempre que é reduzido a 0 ou menos pontos de vida, pode gastar 5 PM para recuperar PV igual à metade dos seus PV máximos.', true, '{"other":"Nome na Arena, 17º nível de lutador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Jogo de Pernas', 1, 'Uma vez por rodada, quando faz um ataque corpo a corpo, você pode se mover 1,5m em qualquer direção, antes ou depois do ataque. Esse movimento não ativa reações de seus inimigos (como de Ataque Reflexo).', true, '{"other":"Des 1"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Língua dos Becos', 1, 'Quando faz um teste de perícia baseada em Carisma, você pode pagar 1 PM para usar sua Força no lugar deste atributo.', true, '{"other":"For 1, treinado em Intimidação"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Lutador de Chão', 1, 'Você recebe +2 em testes de ataque para agarrar e derrubar. Quando agarra uma criatura, pode gastar 1 PM para fazer uma manobra derrubar contra ela como uma ação livre.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Mestre das Combinações', 1, 'Sua contagem de combinações aumenta em +2 (em vez de +1) para cada ataque de Combinação diferente com o qual você acertar o oponente.', true, '{"other":"dois poderes de Combinação"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Nome na Arena', 1, 'Você construiu uma reputação no circuito de lutas de Arton. Uma vez por cena, pode gastar uma ação completa para fazer um teste de Luta (CD 10) e impressionar os presentes. Se passar, você recebe +2 em todos os seus testes de perícias originalmente baseadas em Carisma até o fim da cena e a atitude de qualquer pessoa que seja fã de lutas aumenta em uma categoria em relação a você (veja a página 259). Esse bônus aumenta em +2 para cada 10 pontos pelos quais o resultado do teste exceder a CD (+4 para um resultado 20, +6 para 30 e assim por diante).', true, '{"other":"11º nível de lutador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Punhos de Adamante', 1, 'Seus ataques desarmados ignoram 10 pontos de redução de dano do alvo, se houver.', true, '{"other":"8º nível de lutador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Rasteira', 1, 'Quando faz um ataque desarmado contra uma criatura até uma categoria de tamanho maior que a sua, você pode gastar 2 PM. Se fizer isso e acertar o ataque, a criatura fica caída.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Rilhar os Dentes', 1, 'Quando sofre dano de um ataque corpo a corpo, você pode gastar 1 PM para receber RD igual a 5 + sua Constituição contra esse dano.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Rolamento Escapatório', 1, 'Quando falha em um teste para evitar uma condição de movimento (como o teste oposto para evitar ser agarrado), você pode gastar 2 PM para rolá-lo novamente usando Acrobacia.', true, '{"other":"treinado em Acrobacia"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Ruas Furiosas', 1, 'Quando destrói um objeto empunhado por um inimigo com a manobra quebrar, você recebe uma quantidade de PV temporários igual a 1d6 x sua Constituição.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Sarado', 1, 'Você soma sua Força no seu total de pontos de vida e em Fortitude. Você pode usar Força em vez de Carisma em testes de Diplomacia com pessoas que se atraiam por físicos bem definidos.', true, '{"other":"For 3"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Sequência Defensiva', 1, 'Quando acerta um ataque desarmado em uma criatura, você recebe um bônus cumulativo de +2 na Defesa contra essa criatura até o início do seu próximo turno.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Sequência Destruidora', 1, 'No início do seu turno, você pode gastar 2 PM para dizer um número (no mínimo 2). Se fizer e acertar uma quantidade de ataques igual ao número dito, o último recebe um bônus cumulativo de +4 na rolagem de dano por ataque feito. Por exemplo, se você falar “três” e fizer e acertar três ataques, o último ataque (o terceiro) receberá +12 na rolagem de dano.', true, '{"other":"Trocação, 12º nível de lutador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Trincado', 1, 'Esculpido à exaustão, seu corpo se tornou uma máquina. Você soma sua Constituição nas rolagens de dano desarmado.', true, '{"other":"Con 3, Sarado, 10º nível de lutador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Trocação', 1, 'Quando você começa a bater, não para mais. Ao acertar um ataque desarmado, pode fazer outro ataque desarmado contra o mesmo alvo, pagando uma quantidade de PM igual à quantidade de ataques já realizados por você na rodada. Ou seja, pode fazer o primeiro ataque extra gastando 1 PM, um segundo ataque extra gastando mais 2 PM e assim por diante, até errar um ataque ou não ter mais pontos de mana.', true, '{"other":"6º nível de lutador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Trocação Tumultuosa', 1, 'Quando usa a ação agredir para fazer um ataque desarmado, você pode gastar 2 PM para atingir todas as criaturas adjacentes — incluindo aliados! Você deve usar este poder antes de rolar o ataque e compara o resultado de seu teste contra a Defesa de cada criatura.', true, '{"other":"Trocação, 8º nível de lutador"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Valentão', 1, 'Você recebe +2 em testes de ataque e rolagens de dano contra oponentes caídos, desprevenidos, flanqueados ou indefesos.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Voadora', 1, 'Quando faz uma investida desarmada, você pode gastar 2 PM. Se fizer isso, recebe +1d6 no dano para cada 3m que se deslocar até chegar ao oponente, limitado pelo seu nível.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Casca Grossa', 1, 'No 3º nível, você soma sua Constituição na Defesa, limitado pelo seu nível e apenas se não estiver usando armadura pesada. Além disso, no 7º nível, e a cada quatro níveis, você recebe +1 na Defesa.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Golpe Cruel', 1, 'No 5º nível, você acerta onde dói. Sua margem de ameaça com ataques desarmados aumenta em +1.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Golpe Violento', 1, 'No 9º nível, você bate com muita força. Seu multiplicador de crítico com ataques desarmados aumenta em +1.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Dono da Rua', 1, 'No 20º nível, seu dano desarmado aumenta para 2d10 (para criaturas Médias). Além disso, quando usa a ação agredir para fazer um ataque desarmado, você pode fazer dois ataques, em vez de um (podendo usar Golpe Relâmpago para fazer um terceiro).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Façanha Atlética (Atleta)', 1, 'Quando faz um teste de perícia, você pode gastar uma quantidade de PM a sua escolha (limitada pela sua Força). Para cada PM que gastar, recebe +2 no teste.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Arremesso Atlético (Atleta)', 1, 'No 2º nível, o alcance de seus ataques com armas de arremesso aumenta em um passo (de curto para médio e de médio para longo). Além disso, quando ataca com uma dessas armas, você pode usar o dano da habilidade Briga no lugar do dano básico da arma. A partir do 10º nível, seus ataques com armas de arremesso contam como ataques desarmados para efeito de suas habilidades de lutador.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Poderio Muscular (Atleta)', 1, 'No 2º nível, você aprende e pode lançar Primor Atlético, mas apenas em si mesmo. Esta não é uma habilidade mágica e provém de seu extenso treinamento físico (veja “Magias Simuladas”, p. 44).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Mais Alto e Mais Rápido (Atleta)', 1, 'No 5º nível, seu deslocamento aumenta em +3m. Além disso, você recebe deslocamento de escalada e natação igual à metade de seu deslocamento normal (se já os possui, em vez disso eles aumentam em +3m). Ao contrário do normal, esse deslocamento de natação não fornece a capacidade de respirar debaixo d’água, mas você soma seu nível de atleta no total de rodadas para prender sua respiração (veja Tormenta20, p. 319).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Disciplina Atlética (Atleta)', 1, 'A partir do 9º nível, quando falha em um teste de resistência, você pode gastar 2 PM para rolar esse teste novamente, usando Atletismo no lugar da perícia original.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Lutador', 'Corpo Ideal (Atleta)', 1, 'No 20º nível, você atinge o ápice físico de um corpo mortal. Você recebe imunidade a cansaço, condições de metabolismo e veneno, redução de dano 10 e seu dano desarmado e com armas de arremesso aumenta para 2d10 (criaturas Médias).', false, NULL);
INSERT INTO classes (name, publication, hit_points, mana_points, skills, proficiencies) VALUES ('Nobre', 'Tormenta20', '16+CON', '4 por nível', '["Diplomacia  ou Intimidação","Vontade","Adestramento","Atuação","Cavalgar","Conhecimento","Diplomacia","Enganação","Fortitude","Guerra","Iniciativa","Intimidação","Intuição","Investigação","Jogatina","Luta","Nobreza","Ofício","Percepção","Pontaria"]'::jsonb, '["Armas marciais","Armaduras pesadas","Escudos"]'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Autoconfiança', 1, 'Você pode usar seu Carisma em vez de Destreza na Defesa (mas continua não podendo somar um atributo na Defesa quando usa armadura pesada).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Espólio', 1, 'Você recebe um item a sua escolha com preço de até T$ 2.000.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Orgulho', 1, 'Quando faz um teste de perícia, você pode gastar uma quantidade de PM a sua escolha (limitado pelo seu Carisma). Para cada PM que gastar, recebe +2 no teste.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Agente de Elite', 1, 'Você recebe um agente especial, um parceiro veterano que fornece os benefícios de um parceiro a sua escolha (Tormenta20, p. 260) ou um poder de outra classe, cujos pré-requisitos você cumpra (para efeitos de nível na classe desse poder, considere seu nível de nobre −4). No início de cada aventura, você pode trocar seu agente.', true, '{"other":"Título, 11º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Armadura Brilhante', 1, 'Você pode usar seu Carisma na Defesa quando usa armadura pesada. Se fizer isso, não pode somar sua Destreza, mesmo que outras habilidades ou efeitos permitam isso.', true, '{"other":"8º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Aumento de Atributo', 1, 'Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Autoridade Feudal', 1, 'Você pode gastar uma hora e 2 PM para conclamar o povo a ajudá-lo (qualquer pessoa sem um título de nobreza ou uma posição numa igreja reconhecida pelo seu reino). Em termos de jogo, essas pessoas contam como um parceiro iniciante de um tipo a sua escolha (aprovado pelo mestre) que lhe acompanha até o fim da aventura. Esta habilidade só pode ser usada em locais onde sua posição carregue alguma influência (a critério do mestre).', true, '{"other":"6º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Comandante de Campo', 1, 'Seus capangas recebem +2 nas rolagens de dano e um bônus na Defesa igual ao seu Carisma. Além disso, quando contrata ou recebe capangas por qualquer motivo, você recebe um capanga adicional do mesmo tipo.', true, '{"other":"5º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Comitiva', 1, 'Seu limite de parceiros aumenta em +1. A partir do 11º nível, esse limite aumenta em +1 adicional.', true, '{"other":"5º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Discurso de Batalha', 1, 'Em seu primeiro turno de um combate, você pode gastar uma ação completa e fazer um teste de Diplomacia ou Intimidação. Se fizer isso, para cada 10 pontos no resultado do teste, você e seus aliados em alcance curto recebem 2 PM temporários. Esses PM temporários desaparecem no fim da cena.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Educação Privilegiada', 1, 'Você se torna treinado em duas perícias de nobre a sua escolha.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Estrategista', 1, 'Você pode direcionar aliados em alcance curto. Gaste uma ação padrão e 1 PM por aliado que quiser direcionar (limitado pelo seu Carisma). No próximo turno do aliado, ele ganha uma ação de movimento.', true, '{"other":"Int 1, treinado em Guerra, 6º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Favor', 1, 'Você pode usar sua influência para pedir favores a pessoas poderosas. Isso gasta 5 PM e uma hora de conversa e bajulação, ou mais, de acordo com o mestre, e funciona como o uso persuasão de Diplomacia (veja a página 118). Porém, você pode pedir favores ainda mais caros, difíceis ou perigosos — um convite para uma festa particular, uma carona de barco até Galrasia ou mesmo acesso aos planos militares do reino. Se você falhar, não pode pedir o mesmo favor por pelo menos uma semana.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Fofocas da Corte', 1, 'Quando chega em um ambiente social (taverna, acampamento militar, praça de vila, salão de castelo etc.), você pode gastar 1 hora para se inteirar das “novidades”. A critério do mestre, você recebe uma informação útil sobre os habitantes ou acontecimentos locais. Além disso, recebe 4d6 dados de auxílio. Sempre que faz um teste de perícia baseada em Carisma nesse ambiente, você pode gastar um desses dados e adicionar como um bônus no teste.', true, '{"other":"treinado em Intuição e Investigação"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'General', 1, 'Quando você usa o poder Estrategista, aliados direcionados recebem 1d4 PM temporários. Esses PM duram até o fim do turno do aliado e não podem ser usados em efeitos que concedam PM.', true, '{"other":"Estrategista, 12º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Grito Tirânico', 1, 'Você pode usar Palavras Afiadas como uma ação completa, em vez de padrão. Se fizer isso, seus dados de dano aumentam para d8 e você atinge todos os inimigos em alcance curto.', true, '{"other":"8º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Guarda Pessoal', 1, 'Você recebe um pelotão de infantaria (p. 241) veterano que atua como seu guarda-costas. No 11º nível, o pelotão se torna um parceiro mestre. Se perder seu pelotão de infantaria, você pode arregimentar outro após uma semana.', true, '{"other":"5º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Hedonismo Aristocrático', 1, 'Uma vez por dia, você pode gastar 1 hora e um valor a sua escolha entre T$ 100, T$ 500 e T$ 2.000 em luxos como comida, bebida e apresentações artísticas. Se tiver gastado T$ 100, você recebe 4 PM temporários por patamar, que duram até o fim do dia. Se tiver gastado T$ 500, o ganho aumenta para 5 PM por patamar e, se tiver gastado T$ 2.000, para 6 PM por patamar.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Inspirar Confiança', 1, 'Sua presença faz as pessoas darem o melhor de si. Quando um aliado em alcance curto faz um teste, você pode gastar 2 PM para fazer com que ele possa rolar esse teste novamente.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Inspirar Glória', 1, 'A presença de um nobre motiva as pessoas a realizarem grandes façanhas. Uma vez por rodada, você pode gastar 5 PM para fazer um aliado em alcance curto ganhar uma ação padrão adicional no próximo turno dele. Você só pode usar esta habilidade uma vez por cena em cada aliado.', true, '{"other":"Inspirar Confiança, 8º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Instigar Violência', 1, 'Uma vez por rodada por aliado, quando um aliado em alcance curto faz um acerto crítico em um inimigo, você pode gastar 3 PM para que esse aliado faça mais um ataque contra o mesmo inimigo.', true, '{"other":"treinado em Guerra, 11º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Insuflar Investida', 1, 'Quando faz uma investida, você pode gastar 1 PM por aliado a sua escolha em alcance curto. Se fizer isso, a próxima investida que cada um desses aliados fizer até o início do seu próximo turno causa +2d8 pontos de dano.', true, '{"other":"Estrategista"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Jogo da Corte', 1, 'Quando faz um teste de Diplomacia, Intuição ou Nobreza, você pode gastar 1 PM para rolá-lo novamente.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Legado Mágico', 1, 'Você recebe um item mágico menor a sua escolha, como um presente ou uma herança de família. No início de cada aventura, você pode substituir esse item por outro. A partir do 14º nível, quando substitui o item pode escolher um item mágico médio e, a partir do 17º nível, um item mágico maior.', true, '{"other":"11º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Liderar pelo Exemplo', 1, 'Você pode gastar 2 PM para servir de inspiração. Até o início de seu próximo turno, sempre que você passar em um teste de perícia, aliados em alcance curto que fizerem um teste da mesma perícia podem usar o resultado do seu teste em vez de fazer o seu próprio.', true, '{"other":"6º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Líder Enérgico', 1, 'Você soma seu Carisma em Iniciativa. Além disso, se for o primeiro na iniciativa, em seu primeiro turno você pode usar uma habilidade de nobre com execução de ação de movimento ou padrão como ação livre.', true, '{"other":"treinado em Iniciativa"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Líder Impiedoso', 1, 'Sempre que um aliado sob efeito da sua habilidade Gritar Ordens fizer um acerto crítico ou reduzir um inimigo para 0 PV ou menos, você recupera 1 PM.', true, '{"other":"5º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Língua de Ouro', 1, 'Você pode gastar uma ação padrão e 4 PM para gerar o efeito da magia Enfeitiçar com os aprimoramentos de sugerir ação e afetar todas as criaturas dentro do alcance (CD Car). Esta não é uma habilidade mágica e provém de sua capacidade de influenciar outras pessoas.', true, '{"other":"Língua de Prata, 8º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Língua de Prata', 1, 'Quando faz um teste de perícia baseada em Carisma, você pode gastar 2 PM para receber um bônus no teste igual a metade do seu nível.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Língua Rápida', 1, 'Quando faz um teste de Diplomacia para mudar atitude como uma ação completa, você sofre uma penalidade de –5, em vez de –10.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Linhagem Distinta', 1, 'Você descende de uma família ilustre — ou, por suas ações, tornou sua família ilustre. Seja como for, o nome de sua família o inspira a grandes feitos. Quando você usa Orgulho, o custo da habilidade diminui em –1 PM. Além disso, uma vez por cena, quando usa Orgulho, você pode gastar +5 PM. Se fizer isso, o bônus fornecido pela habilidade dobra e, ao fazer o teste de perícia afetado por ela, você rola dois dados e usa o melhor resultado.', true, '{"other":"17º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Ordens Agressivas', 1, 'Quando você usa Gritar Ordens, a habilidade também soma seu bônus na primeira rolagem de dano dos aliados até o início do seu próximo turno.', true, '{"other":"5º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Ordens Encorajadoras', 1, 'Quando você usa Gritar Ordens, a habilidade também fornece 10 PV temporários cumulativos. Esses pontos desaparecem no fim da cena.', true, '{"other":"5º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Palavras de Efeito', 1, 'Você soma seu Carisma no dano de sua habilidade Palavras Afiadas e a ação necessária para usá-la diminui em um passo (de completa para padrão, de padrão para movimento).', true, '{"other":"5º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Palavras Ressonantes', 1, 'Quando você usa Palavras Afiadas, sempre que rolar o resultado máximo ou um ponto abaixo do máximo em um dado da habilidade (por exemplo, um 5 ou 6 ao rolar 1d6), role um dado extra.', true, '{"other":"5º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Presença Majestosa', 1, 'Sua Presença Aristocrática passa a funcionar contra qualquer criatura com valor de Inteligência (passa a afetar até mesmo animais, embora continue não funcionando contra criaturas sem Int). Além disso, você pode usá-la mais de uma vez contra uma mesma criatura na mesma cena.', true, '{"other":"16º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Protocolo Impecável', 1, 'Quando chega em um ambiente social (veja Fofocas da Corte), você pode gastar 2 PM e fazer um teste de Nobreza (CD 20). Se passar, porta-se da maneira ideal para a situação, o que melhora a atitude de todas as criaturas em relação a você em uma categoria. Se passar por 10 ou mais, a critério do mestre você pode receber possibilidades de interação que normalmente não teria — por exemplo, ao chegar em um acampamento militar ou castelo, pode ser convidado para falar com o general ou o nobre comandante.', true, '{"other":"treinado em Nobreza, Jogo da Corte"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Senescal', 1, 'Você recebe +1 por patamar em testes de perícia para resolver ações de base, domínio ou negócio e, uma vez por turno dessas estruturas, pode executar uma ação de estrutura adicional.', true, '{"other":"5º nível de nobre"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Título', 1, 'Você adquire um título de nobreza. Converse com o mestre para definir os benefícios exatos de seu título. Como regra geral, no início de cada aventura você recebe 20 TO por nível de nobre (rendimentos dos impostos) ou a ajuda de um parceiro veterano (um membro de sua corte).', true, '{"other":"Autoridade Feudal, 10º nível de nobre, ter conquistado terras ou realizado um serviço para um nobre que possa se tornar seu suserano"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Voz Límpida', 1, 'Quando você usa uma habilidade de nobre que afete um ou mais aliados, o custo dessa habilidade diminui em –1 PM (isso não reduz efeitos baseados no custo em PM pago).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Voz Poderosa', 1, 'Você recebe +2 em Diplomacia e Intimidação. Suas habilidades de nobre com alcance curto passam para alcance médio.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Palavras Afiadas', 1, 'Você pode gastar uma ação padrão e 1 PM para fazer um teste de Diplomacia ou Intimidação oposto ao teste de Vontade de uma criatura inteligente (Int –3 ou maior) em alcance curto. Se vencer, você causa 2d6 pontos de dano psíquico não letal à criatura. Se perder, causa metade deste dano. Se a criatura for reduzida a 0 ou menos PV, em vez de cair inconsciente, ela se rende (se você usou Diplomacia) ou fica apavorada e foge de você da maneira mais eficiente possível (se usou Intimidação). A cada quatro níveis, você pode gastar +1 PM para aumentar o dano (veja a tabela da classe). Mental.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Riqueza', 1, 'No 3º nível, você passa a receber dinheiro de sua família, patrono ou negócios. Uma vez por aventura, pode fazer um teste de Carisma com um bônus igual ao seu nível de nobre. Você recebe um número de Tibares de ouro igual ao resultado do teste. Assim, um nobre de 5º nível com Carisma 4 que role 13 no dado recebe 22 TO. O uso desta habilidade é condicionado a sua relação com sua família, patrono ou negócios e a onde você está. Por exemplo, um nobre viajando pelos ermos, isolado da civilização, dificilmente teria como receber dinheiro.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Gritar Ordens', 1, 'A partir do 4º nível, você pode gastar uma quantidade de PM a sua escolha (limitado pelo seu Carisma). Até o início de seu próximo turno, todos os seus aliados em alcance curto recebem um bônus nos testes de perícia igual à quantidade de PM que você gastou.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Presença Aristocrática', 1, 'A partir do 5º nível, sempre que uma criatura inteligente tentar machucá-lo (causar dano com um ataque, magia ou habilidade) você pode gastar 2 PM. Se fizer isso, a criatura deve fazer um teste de Vontade (CD Car). Se falhar, não conseguirá machucá-lo e perderá a ação. Você só pode usar esta habilidade uma vez por cena contra cada criatura.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Realeza', 1, 'No 20º nível, a CD para resistir a sua Presença Aristocrática aumenta em +5 e uma criatura que falhe no teste de Vontade por 10 ou mais se arrepende tanto de ter tentado machucá-lo que passa a lutar ao seu lado (e seguir suas ordens, se puder entendê-lo) pelo resto da cena. Além disso, uma criatura que seja reduzida a 0 PV por Palavras Afiadas não sofre este dano; em vez disso, passa a lutar ao seu lado pelo resto da cena.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Meios de Produção (Burguês)', 1, 'No início de cada aventura, você recebe T$ 100 em dinheiro, itens mundanos ou poções a sua escolha. Esse valor aumenta para T$ 300 no patamar veterano, T$ 600 no campeão e T$ 1.000 no lenda.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Poder Monetário (Burguês)', 1, 'Quando usa uma habilidade com um custo em PM, você pode consumir uma quantidade de tibares de ouro (limitada pelo seu Carisma). Cada TO consumido dessa forma paga 1 PM do custo da habilidade. Você pode consumir um número de TO por dia igual ao seu nível. No 5º nível, este limite aumenta para o dobro do seu nível.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Desmoralizar (Burguês)', 1, 'No 2º nível, você aprende e pode lançar Perdição, e pode usar seus aprimoramentos como se tivesse acesso aos mesmos círculos de magia que um clérigo de seu nível. Entretanto, pode lançá-la apenas em criaturas inteligentes (Int –3 ou maior). Esta não é uma habilidade mágica e provém da sua capacidade de abalar a autoconfiança de outras pessoas (veja “Magias Simuladas”, p. 44). Mental.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Negociante Nato (Burguês)', 1, 'No 3º nível, quando chega em uma nova comunidade, você pode gastar 1 dia fazendo contatos com o comércio local para fazer um teste de Diplomacia (CD 20). Se passar, pode vender itens nessa comunidade por 60% do seu preço (em vez de 50%). Para cada 10 pontos pelos quais o resultado do teste exceder a CD, você aumenta o preço de venda em +10% (até o máximo de 100%). Esta habilidade não se acumula com barganha, e NPCs ainda estão limitados a comprar somente o que desejam, com o dinheiro que possuem.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Suborno (Burguês)', 1, 'No 4º nível, você aprende e pode lançar Enfeitiçar (atributo-chave Carisma). Esta não é uma habilidade mágica e provém de sua capacidade de instigar os outros com promessas de enriquecimento (veja “Magias Simuladas”, p. 44). A CD para resistir a essa magia aumenta em +2 se você tiver consumido pelo menos 1 tibar de ouro para pagar seu custo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Ostentação (Burguês)', 1, 'A partir do 5º nível, você pode se beneficiar de um item vestido adicional. Além disso, a CD para resistir às suas habilidades de burguês aumenta em +1 se você possuir um item banhado a ouro, cravejado de gemas ou de mitral. Esse aumento é cumulativo; possuir três itens diferentes com as três modificações aumenta a CD em +3.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Novo Rico (Burguês)', 1, 'No 9º nível, para cada item mágico que você estiver vestindo, você recebe +1 PM por nível de poder do item (somente após 1 dia de uso).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Nobre', 'Magnata (Burguês)', 1, 'No 20º nível, quando você usa Desmoralizar, a penalidade em testes de ataque também se aplica à CD das habilidades das criaturas afetadas. Além disso, sempre que consome um tibar de ouro para pagar o custo em PM de uma habilidade, você recebe 10 PV temporários cumulativos, que duram até o fim da cena.', false, NULL);
INSERT INTO classes (name, publication, hit_points, mana_points, skills, proficiencies) VALUES ('Origens', 'Tormenta20', 'undefined+CON', 'undefined por nível', '[]'::jsonb, '[]'::jsonb);
INSERT INTO classes (name, publication, hit_points, mana_points, skills, proficiencies) VALUES ('Paladino', 'Tormenta20', '20+CON', '3 por nível', '["Luta","Vontade","Adestramento","Atletismo","Cavalgar","Cura","Diplomacia","a Fortitude","Guerra","Iniciativa","Intuição","Nobreza","Percepção","Religião"]'::jsonb, '["Armas marciais","Armaduras pesadas","Escudos"]'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Abençoado', 1, 'Você soma seu Carisma no seu total de pontos de mana no 1º nível. Além disso, torna-se devoto de um deus disponível para paladinos (Azgher, Khalmyr, Lena, Lin-Wu, Marah, Tanna-Toh, Thyatis, Valkaria). Veja as regras de devotos na página 96. Ao contrário de devotos normais, você recebe dois poderes concedidos por se tornar devoto, em vez de apenas um. Como alternativa, você pode ser um paladino do bem, lutando em prol da bondade e da justiça como um todo. Não recebe nenhum Poder Concedido, mas não precisa seguir nenhuma Obrigação & Restrição (além do Código do Herói, abaixo). Cultuar o bem conta como sua devoção.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Código do Herói', 1, 'Você deve sempre manter sua palavra e nunca pode recusar um pedido de ajuda de alguém inocente. Além disso, nunca pode mentir, trapacear ou roubar. Se violar o código, você perde todos os seus PM e só pode recuperá-los a partir do próximo dia.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Golpe Divino', 1, 'Quando faz um ataque corpo a corpo, você pode gastar 2 PM para desferir um golpe destruidor. Você soma seu Carisma no teste de ataque e +1d8 na rolagem de dano. A cada quatro níveis, pode gastar +1 PM para aumentar o dano em +1d8.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Mensagem de Paz', 1, 'Você pode gastar uma ação padrão e 1 PM para diminuir o desejo de violência de uma criatura em alcance curto. Faça um teste de Diplomacia oposto ao teste de Vontade da criatura. Se você vencer, a criatura sofre uma penalidade cumulativa de –1 em testes de ataque e rolagens de dano e, se for um lacaio, fica também pasma por 1 rodada (uma criatura só pode ficar pasma por este efeito uma vez por cena). Para cada 10 pontos pelos quais você vencer o teste oposto, a penalidade aumenta em 1 e, se a criatura estava enfeitiçada, fascinada ou pasma, a penalidade aumenta em 1 para cada uma dessas condições. A cada rodada, a penalidade acumulada da criatura diminui em 1. A cada quatro níveis, você pode gastar +1 PM para receber +5 no teste de Diplomacia. A partir do 5º nível, quando usa esta habilidade, você pode gastar +2 PM. Se fizer isso, afeta todas as criaturas à sua escolha em alcance curto. Mental.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Cura pelas Mãos', 1, 'A partir do 2º nível, você pode gastar uma ação de movimento e 1 PM para curar 1d8+1 pontos de vida por luz em um alvo em alcance corpo a corpo (incluindo você). A cada quatro níveis, você pode gastar +1 PM para aumentar os PV curados em +1d8+1. Esta habilidade causa dano de luz a mortos-vivos (CD Car). A partir do 6º nível, você pode gastar +1 PM quando usa Cura pelas Mãos para anular uma condição afetando o alvo, entre abalado, apavorado, atordoado, cego, doente, exausto, fatigado ou surdo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Arma Juramentada', 1, 'Se você estiver empunhando a arma preferida de sua divindade, ela recebe uma fração do poder divino. Em suas mãos, ela é considerada mágica e recebe os benefícios de uma melhoria (escolhido ao receber este poder, exceto material especial), cujos pré-requisitos ela cumpra. Essa melhoria não conta no limite da arma. Se você descumprir as Obrigações & Restrições da divindade, este efeito deixa de funcionar até você recuperar seus PM.', true, '{"other":"devoto de uma divindade"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Arma Sacramentada', 1, 'A conexão de sua arma com sua divindade se torna mais forte. Em suas mãos, a arma também recebe os benefícios de um encanto (escolhido ao receber este poder) cujos pré-requisitos ela cumpra. Esse encanto não conta no limite da arma e também deixa de funcionar se você descumprir suas Obrigações & Restrições.', true, '{"other":"Arma Juramentada, 11º nível de paladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Arma Sagrada', 1, 'Quando usa Golpe Divino para atacar com a arma preferida de sua divindade, o dado de dano que você rola por Golpe Divino aumenta para d12.', true, '{"other":"devoto de uma divindade (exceto Lena e Marah)"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Aumento de Atributo', 1, 'Você recebe +1 em um atributo. Você pode escolher este poder várias vezes, mas apenas uma vez por patamar para um mesmo atributo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Aura Antimagia', 1, 'Enquanto sua aura estiver ativa, você e os aliados dentro da aura podem rolar novamente qualquer teste de resistência contra magia recém realizado.', true, '{"other":"14° nível de paladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Aura Ardente', 1, 'Enquanto sua aura estiver ativa, no início de cada um de seus turnos, espíritos e mortos-vivos a sua escolha dentro dela sofrem dano de luz igual a 5 + seu Carisma.', true, '{"other":"10° nível de paladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Aura de Cura', 1, 'Enquanto sua aura estiver ativa, no início de seus turnos, você e os aliados a sua escolha dentro dela curam um número de PV igual a 5 + seu Carisma.', true, '{"other":"6° nível de paladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Aura de Invencibilidade', 1, 'Enquanto sua aura estiver ativa, você ignora o primeiro dano que sofrer na cena. O mesmo se aplica a seus aliados dentro da aura.', true, '{"other":"18° nível de paladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Aura Poderosa', 1, 'O raio da sua aura aumenta para 30m.', true, '{"other":"6° nível de paladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Aura Vingadora', 1, 'Enquanto sua aura estiver ativa, você e cada aliado dentro dela recebem +1d6 de luz em uma rolagem de dano corpo a corpo uma vez por rodada.', true, '{"other":"8º nível de paladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Bloqueio Divino', 1, 'Quando sofre um ataque, se estiver empunhando um escudo, você pode gastar 2 PM para receber +5 na Defesa contra esse ataque.', true, '{"other":"proficiência com escudos"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Convicção Heroica', 1, 'Uma vez por cena, quando seus pontos de vida forem reduzidos a 0 ou menos, você pode gastar 5 PM para curar 50 PV.', true, '{"other":"11º nível de paladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Expurgo Sagrado', 1, 'Quando você usa Golpe Divino contra um abissal ou um morto-vivo, seu custo diminui em –1 PM (cumulativo com outras reduções) e o bônus de dano da habilidade aumenta em mais um dado.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Escudo Fraterno', 1, 'Se você estiver empunhando um escudo, sua Égide Sagrada afeta aliados até 9m (em vez de apenas adjacentes).', true, '{"other":"Égide Sagrada"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Escudo Sagrado', 1, 'Se estiver empunhando um escudo, você pode gastar uma ação de movimento e 1 PM para criar uma barreira sagrada com duração sustentada a partir dele. Você recebe redução de dano igual ao seu Carisma.', true, '{"other":"Bloqueio Divino, 7º nível de paladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Fulgor Ardente', 1, 'Quando usa Golpe Divino, você pode gastar +1 PM. Se fizer isso e acertar o ataque, todos os inimigos a até 6m do alvo do ataque sofrem dano de luz igual ao dano extra causado por essa habilidade.', true, '{"other":"Fulgor Divino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Fulgor Divino', 1, 'Quando usa Golpe Divino, todos os inimigos em alcance curto ficam ofuscados até o início do seu próximo turno.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Guardião Celestial', 1, 'Você pode gastar uma ação padrão e 10 PM para convocar um espírito para lutar ao seu lado. O guardião celestial flutua ao seu redor, é incorpóreo e imune a dano e possui 100 pontos de luz. Uma vez por rodada, quando você sofre dano, pode fazer o espírito absorver esse dano. Ele perde pontos de luz igual ao dano que você sofreria, e desaparece se seus pontos de luz forem reduzidos a 0. Além disso, uma vez por rodada, você pode gastar 2 PM para fazer o espírito atacar uma criatura em alcance curto (ataque igual a sua Religião com um bônus adicional de +10, dano 4d8 mais seu Carisma de luz, crítico 18/x3).', true, '{"other":"17º nível de paladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Investida Sagrada', 1, 'Quando faz uma investida montada, você pode pagar 1 PM para receber deslocamento de voo igual ao seu deslocamento base até o fim do seu turno e causar +1d8 pontos de dano.', true, '{"other":"Montaria Sagrada, 10º nível de paladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Julgamentos Divinos', 1, 'Alguns poderes do paladino são Julgamentos Divinos. Esses poderes compartilham as seguintes regras.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Julgamento Divino: Arrependimento', 1, 'Você pode gastar 2 PM para marcar um inimigo em alcance curto. Na próxima vez que esse inimigo acertar um ataque em você ou em um de seus aliados, deve fazer um teste de Vontade (CD Car). Se falhar, fica atordoado no próximo turno dele (apenas uma vez por cena).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Julgamento Divino: Autoridade', 1, 'Você pode gastar 1 PM para comandar uma criatura em alcance curto. Faça um teste de Diplomacia oposto pelo teste de Vontade do alvo. Se você vencer, ele obedece a um comando simples, como “pare” ou “largue a arma” (apenas uma vez por cena). Mental.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Julgamento Divino: Coragem', 1, 'Você pode gastar 2 PM para inspirar coragem em uma criatura em alcance curto, incluindo você mesmo. A criatura fica imune a efeitos de medo e recebe +2 em testes de ataque contra o inimigo com maior ND na cena.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Julgamento Divino: Desafio', 1, 'Você pode gastar 2 PM para marcar um inimigo em alcance curto. Sempre que esse inimigo ataca um de seus aliados, ele recebe uma penalidade cumulativa de –1 em testes de ataque (limitado pelo seu Carisma). Essa penalidade acaba se ele atacar você ou se você terminar seu turno além do alcance corpo a corpo dele.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Julgamento Divino: Iluminação', 1, 'Você pode marcar um inimigo em alcance curto. Quando acerta um ataque corpo a corpo nesse inimigo, você recebe 2 PM temporários. Você só pode proferir este julgamento uma vez por cena.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Julgamento Divino: Justiça', 1, 'Você pode gastar 2 PM para marcar um inimigo em alcance curto. A próxima vez que esse inimigo causar dano em você ou em um de seus aliados, deve fazer um teste de Vontade (CD Car). Se falhar, sofre dano de luz igual à metade do dano que causou.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Julgamento Divino: Libertação', 1, 'Você pode gastar 5 PM para cancelar uma condição negativa qualquer (como abalado, paralisado etc.) que esteja afetando uma criatura em alcance curto.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Julgamento Divino: Proteção', 1, 'Você pode gastar 2 PM para conceder 10 PV temporários e +2 na Defesa para uma criatura em alcance curto.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Julgamento Divino: Redenção', 1, 'Você é capaz de criar um vínculo espiritual com um aliado. Você pode lançar Escudo da Fé, mas apenas com o aprimoramento que divide o dano entre o alvo e você (mas não precisa cumprir seu requisito de círculo).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Julgamento Divino: Retribuição', 1, 'Você pode marcar um inimigo em alcance curto. Na próxima vez em que esse inimigo causar dano em você, você pode gastar 2 PM para fazer um ataque corpo a corpo contra ele (desde que ele esteja em seu alcance).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Julgamento Divino: Salvação', 1, 'Você pode gastar 2 PM para marcar um inimigo em alcance curto. Até o fim da cena, quando você acerta um ataque corpo a corpo nesse inimigo, recupera 5 pontos de vida.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Julgamento Divino: Vindicação', 1, 'Você pode gastar 2 PM para marcar um inimigo que tenha causado dano a você ou a seus aliados na cena. Você recebe +1 em testes de ataque e +1d8 em rolagens de dano contra o inimigo escolhido, mas sofre –5 em testes de ataque contra quaisquer outros alvos. No 5º nível, e a cada cinco níveis seguintes, você pode pagar +1 PM para aumentar o bônus de ataque em +1 e o bônus de dano em +1d8. O efeito termina caso o alvo fique inconsciente.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Julgamento Divino: Zelo', 1, 'Você pode gastar 1 PM para marcar um alvo em alcance longo. Pelo restante da cena, sempre que se mover na direção desse alvo, você se move com o dobro de seu deslocamento.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Luz Purificadora', 1, 'Quando usa Golpe Divino, você pode gastar +1 PM para converter todo o dano causado para luz e ignorar 10 pontos de redução de dano do alvo.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Manto de Batalha', 1, 'Você aprende e pode lançar Vestimenta da Fé, e pode usar seus aprimoramentos como se tivesse acesso aos mesmos círculos de magia que um clérigo de seu nível.', true, '{"other":"5º nível de paladino"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Orar', 1, 'Você aprende e pode lançar uma magia divina de 1º círculo a sua escolha. Seu atributo-chave para esta magia é Sabedoria. Você pode escolher este poder quantas vezes quiser.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Paladino do Reino', 1, 'Você recebe um poder de cavaleiro cujos pré-requisitos cumpra, usando seu nível como nível de cavaleiro.', true, '{"other":"treinado em Nobreza"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Rajada Divina', 1, 'Quando faz um Golpe Divino com Luz Purificadora, você pode gastar +1 PM para aumentar o alcance desse ataque para curto (ele ainda conta como um ataque corpo a corpo).', true, '{"other":"Luz Purificadora"}'::jsonb);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Sacrifício', 1, 'Uma vez por rodada, quando faz um ataque corpo a corpo, você pode sacrificar 5 PV por patamar para aumentar o dano desse ataque em +1d10 por patamar. Por exemplo, se você for um personagem de 5º nível, pode perder 10 PV para causar +2d10 pontos de dano.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Sentença Dobrada', 1, 'Quando profere um julgamento, você pode gastar +1 PM para proferir um segundo julgamento com a mesma ação (pagando o custo de ambos).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Virtude Paladinesca: Caridade', 1, 'O custo de suas habilidades de paladino que tenham um aliado como alvo é reduzido em –1 PM.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Virtude Paladinesca: Castidade', 1, 'Você se torna imune a efeitos de encantamento e recebe +5 em testes de Intuição para perceber blefes.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Virtude Paladinesca: Compaixão', 1, 'Você pode usar Cura pelas Mãos em alcance curto e, para cada PM que gastar, cura 2d6+1 (em vez de 1d8+1).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Virtude Paladinesca: Humildade', 1, 'Na primeira rodada de um combate, você pode gastar uma ação completa para rezar e pedir orientação. Você recebe uma quantidade de PM temporários igual ao seu Carisma (duram até o fim da cena).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Virtude Paladinesca: Paciência', 1, 'Em combate, você pode ficar uma rodada inteira em meditação, sem fazer ações (exceto reações), para receber +2 em testes de perícia e na Defesa até o fim da cena.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Virtude Paladinesca: Temperança', 1, 'Quando ingere um alimento, item alquímico ou poção, você consome apenas metade do item. Na prática, cada item desses rende duas “doses” para você.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Aura Sagrada', 1, 'No 3º nível, você pode gastar 1 PM para gerar uma aura com 9m de raio a partir de você e duração sustentada. A aura emite uma luz dourada e agradável. Além disso, você e os aliados dentro da aura somam seu Carisma nos testes de resistência.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Bênção da Justiça', 1, 'No 5º nível, escolha entre égide sagrada e montaria sagrada. Uma vez feita, esta escolha não pode ser mudada.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Égide Sagrada', 1, 'Você pode gastar uma ação de movimento e 2 PM para recobrir de energia seu escudo ou símbolo sagrado. Até o fim da cena, você e todos os aliados adjacentes somam seu Carisma na Defesa (cumulativo com outros efeitos). A partir do 11º nível, quando faz um teste de resistência contra uma magia lançada contra você, você pode gastar 5 PM para rolá-lo novamente. Se você passar no teste de resistência e a magia tiver você como único alvo, ela é revertida de volta ao conjurador (que se torna o novo alvo da magia; todas as demais características da magia, incluindo CD do teste de resistência, se mantêm).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Montaria Sagrada', 1, 'Você pode gastar uma ação de movimento e 2 PM para invocar uma montaria sagrada. Veja o quadro para mais detalhes.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Vingador Sagrado', 1, 'No 20º nível, você pode gastar uma ação completa e 10 PM para se cobrir de energia divina, assumindo a forma de um vingador sagrado até o fim da cena. Nesta forma, você recebe deslocamento de voo 18m e redução de dano 20. Além disso, seu Golpe Divino tem seu custo é reduzido à metade e causa mais dois dados de dano.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Ladainha de Combate (Santo)', 1, 'Você pode gastar uma ação padrão e 2 PM para gerar uma aura de 9m de raio com duração sustentada. Você e os aliados dentro da aura recebem +1 em testes de ataque, rolagens de dano e na Defesa. A cada quatro níveis, você pode gastar +2 PM para aumentar esses bônus em +1. Sua ladainha conta como Aura Sagrada (veja Tormenta20, p. 84) para pré-requisitos e efeitos de poderes de paladino.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Santo Curandeiro (Santo)', 1, 'A partir do 2º nível, você pode gastar uma ação de movimento e uma quantidade de PM a sua escolha (limitada pelo seu Carisma). Para cada PM que você gastar, o aliado em alcance médio com a maior redução em seus PV (por dano ou perda de vida) recupera 2d8 pontos de vida por luz.
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Vaso do Espírito (Santo)', 1, 'A partir do 3º nível, quando faz um teste de resistência, você pode gastar 1 PM para somar seu Carisma nesse teste.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Mártir (Santo)', 1, 'A partir do 6º nível, quando um aliado em alcance médio faz um teste de resistência, você pode gastar 1 PM para conceder a ele um bônus nesse teste igual ao seu próprio Carisma. A partir do 12º nível, uma vez por cena, se ele ainda assim falhar, você pode sofrer o efeito no lugar dele (mas você é afetado mesmo que seja imune ao efeito).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Pira Santa (Santo)', 1, 'No 8º nível, enquanto estiver sob efeito de Ladainha de Combate, você pode gastar uma ação de movimento e uma quantidade de PM a sua escolha (limitada pelo seu Carisma). Para cada PM que gastar, o inimigo de maior ND em alcance médio sofre 2d8 pontos de dano de luz e fica ofuscado por 1 rodada (Fort CD Car reduz à metade).', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Vingador Santificado (Santo)', 1, 'No 20º nível, quando usa Ladainha de Combate, você pode gastar +5 PM. Se fizer isso, os bônus numéricos fornecidos por sua Ladainha dobram e você e os aliados dentro da aura recebem imunidade a acertos críticos e RD igual a 5 + seu Carisma.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Montaria Sagrada Detalhes', 1, 'Um paladino de 5º nível pode receber uma montaria sagrada, designada pelos deuses. Este animal vai atuar como um fiel companheiro de batalhas. Normalmente será um cavalo de guerra para paladinos de tamanho Médio ou um pônei para Pequenos, mas suplementos futuros trarão outras opções de montarias. Para invocar sua montaria você gasta uma ação de movimento e 2 PM. Ela aparece com um brilho de luz dourada ao seu lado e fica até o fim da cena, quando desaparece de volta para o mundo divino de onde veio. Como opção para campanhas mais realistas, a montaria sagrada pode ser um animal mundano, em vez de invocado. Neste caso, você nunca precisa gastar uma ação ou PM para ter a montaria — que já estará com você. Por outro lado, o animal pode não ser capaz de acompanhá-lo em todos os lugares (um cavalo, por exemplo, não conseguirá entrar num túnel apertado ou escalar uma montanha). Você e sua montaria têm um vínculo mental, sendo sempre capazes de entender um ao outro (não é preciso fazer testes de Adestramento). Ela fornece os benefícios de um parceiro veterano de seu tipo. No 11º nível, passa a fornecer os benefícios de um parceiro mestre. Veja a lista de parceiros na página 260. Uma montaria cumpre qualquer ordem sua, mesmo que signifique arriscar a vida. Se a montaria sagrada morrer, você fica atordoado por uma rodada. Você pode invocar uma nova montaria após um dia de prece e meditação.', false, NULL);
INSERT INTO class_abilities (class_name, name, level, description, is_power, prerequisites) VALUES ('Paladino', 'Virtudes Paladinescas', 1, 'Este conjunto de poderes representa obediência veemente a um comportamento específico. Você recebe um bônus progressivo em seu total de pontos de mana de acordo com a quantidade de poderes desse tipo que possui: +1 PM para uma Virtude, +3 PM para duas, +6 PM para três, +10 PM para quatro e +15 PM para cinco Virtudes. Virtudes Paladinescas são poderosas, mas possuem uma contrapartida — você deve se comportar de acordo com quaisquer Virtudes que possuir. Um paladino caridoso, por exemplo, deve sempre ajudar os necessitados, enquanto um casto nunca pode cair em tentação. Não seguir uma Virtude Paladinesca que você possua conta como uma violação do Código do Herói. O mestre tem a palavra final sobre o que exatamente constitui uma violação.', false, NULL);
INSERT INTO classes (name, publication, hit_points, mana_points, skills, proficiencies) VALUES ('Poderes Concedidos', 'Tormenta20', 'undefined+CON', 'undefined por nível', '[]'::jsonb, '[]'::jsonb);
INSERT INTO classes (name, publication, hit_points, mana_points, skills, proficiencies) VALUES ('Poderes da Tormenta', 'Tormenta20', 'undefined+CON', 'undefined por nível', '[]'::jsonb, '[]'::jsonb);
